@import "tailwindcss";

:root {
  --navy: #17324d;
  --navy-2: #21486d;
  --teal: #17877f;
  --teal-soft: #e4f4f1;
  --ink: #20313f;
  --muted: #6b7c89;
  --line: #dce4e8;
  --canvas: #f4f7f8;
  --white: #ffffff;
  --shadow: 0 12px 34px rgba(23, 50, 77, 0.07);
}

.mobile-app-install {
  position: fixed;
  z-index: 1000;
  left: max(12px, env(safe-area-inset-left));
  right: max(12px, env(safe-area-inset-right));
  bottom: max(12px, calc(env(safe-area-inset-bottom) + 8px));
  display: none;
  grid-template-columns: 38px minmax(0, 1fr) auto 24px;
  gap: 10px;
  align-items: center;
  padding: 12px;
  border: 1px solid color-mix(in srgb, #17324d 22%, #fff);
  border-radius: 18px;
  background: color-mix(in srgb, #fff 96%, #e4f4f1);
  box-shadow: 0 14px 38px rgba(17, 42, 66, .22);
  color: #17324d;
}

.mobile-app-install__icon { display:grid; place-items:center; width:38px; height:38px; border-radius:13px; background:linear-gradient(145deg,#17324d,#17877f); color:#f7d78c; font-size:18px; }
.mobile-app-install strong { display:block; font-size:.78rem; line-height:1.15; }
.mobile-app-install p { margin:3px 0 0; color:#617180; font-size:.67rem; line-height:1.3; }
.mobile-app-install button,
.mobile-app-install__download { min-height:34px; border:0; border-radius:10px; background:#17324d; color:#fff; padding:0 10px; font:inherit; font-size:.67rem; font-weight:850; cursor:pointer; }
.mobile-app-install__download { display:inline-flex; align-items:center; justify-content:center; text-decoration:none; white-space:nowrap; }
.mobile-app-install .mobile-app-install__close { width:24px; min-height:24px; background:transparent; color:#6b7c89; padding:0; font-size:1.3rem; font-weight:400; }
.mobile-app-install__help { grid-column:1 / -1; padding:9px 10px; border-radius:11px; background:#e4f4f1; color:#365160; font-size:.7rem; line-height:1.4; }

@media (max-width: 760px) {
  .mobile-app-install { display:grid; }
}

.login-section-save {
  min-height: 38px;
  margin-left: auto;
  padding: 0 13px;
  border: 0;
  border-radius: 10px;
  background: var(--pilot-gradient);
  color: #fff;
  font-size: 9px;
  font-weight: 900;
  cursor: pointer;
}

.signup-required-fields,
.signup-account-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 16px 16px 0;
}

.signup-required-fields > span {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 2px 9px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, #27a56b 26%, var(--pilot-line));
  border-radius: 12px;
  background: color-mix(in srgb, #27a56b 6%, var(--pilot-surface));
}

.signup-required-fields i {
  grid-row: 1 / 3;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: color-mix(in srgb, #27a56b 14%, var(--pilot-surface));
  color: #27a56b;
  font-style: normal;
}

.signup-required-fields strong { font-size: 10px; }
.signup-required-fields small { color: var(--pilot-muted); font-size: 8px; }

.signup-account-summary { padding-top: 14px; }

.signup-account-summary > span {
  display: grid;
  gap: 3px;
  padding: 12px;
  border: 1px solid var(--pilot-line);
  border-radius: 12px;
  background: var(--pilot-surface);
}

.signup-account-summary strong { font-size: 19px; }
.signup-account-summary small { color: var(--pilot-muted); font-size: 8px; }
.signup-privacy-note { margin: 0; padding: 0 16px 16px; color: var(--pilot-muted); font-size: 8px; }

.diaconia-readonly-status {
  justify-self: start;
  padding: 7px 10px;
  border: 1px solid var(--pilot-line);
  border-radius: 999px;
  background: var(--pilot-surface-2);
  color: var(--pilot-text);
  font-size: 9px;
  font-weight: 850;
}

.diaconia-observation-copy { grid-column: 1 / -1; color: var(--pilot-muted); line-height: 1.55; }
.diaconia-readonly-note { margin: 0; padding: 14px 17px; border-top: 1px solid var(--pilot-line); color: var(--pilot-muted); font-size: 9px; line-height: 1.55; }
.diaconia-check-item .danger-button { border: 1px solid color-mix(in srgb, #e8667b 30%, var(--pilot-line)); background: color-mix(in srgb, #e8667b 10%, var(--pilot-surface)); color: #d64d66; }

.pilot-dashboard[data-visual-editor-root],
.vinkulo-site[data-visual-editor-root] {
  background-color: var(--ve-surface, transparent);
}

/* O tema da comunidade governa o painel privado. O Editor Visual continua
   personalizando componentes, mas não pode manter um fundo antigo sobre o
   modo claro, escuro ou automático. */
.pilot-dashboard[data-visual-editor-root] {
  background: var(--pilot-bg) !important;
  color: var(--pilot-text);
}

.global-editor-navigation-lock,
.global-editor-reset {
  min-height: 42px;
  padding: 9px 11px;
  border: 1px solid #d3d9e5;
  border-radius: 10px;
  background: #f7f8fb;
  color: #344057;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
}

.global-editor-navigation-lock { margin: 10px 16px 0; font-size: .75rem; }
.global-editor-navigation-lock.locked { border-color: #6b55ff; background: #eeebff; color: #5942ef; }

@media (max-width: 760px) {
  .signup-required-fields,
  .signup-account-summary { grid-template-columns: 1fr; }
  .login-config-section > header { align-items: flex-start; flex-wrap: wrap; }
  .login-section-save { width: 100%; margin-left: 0; }
}

/* V4.7.4 — operações guiadas, sem estados visuais ambíguos */
.parking-map > section > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}
.parking-sector-editor { position: relative; }
.parking-sector-editor > summary {
  min-height: 30px;
  display: inline-flex;
  align-items: center;
  border: 1px solid color-mix(in srgb, var(--sector-color) 54%, var(--pilot-line));
  border-radius: 9px;
  background: var(--pilot-surface-2);
  color: var(--pilot-text);
  padding: 0 9px;
  font-size: .62rem;
  font-weight: 850;
  cursor: pointer;
  list-style: none;
}
.parking-sector-editor > summary::-webkit-details-marker { display: none; }
.parking-sector-editor > form {
  position: absolute;
  top: calc(100% + 7px);
  right: 0;
  z-index: 12;
  width: min(280px, 76vw);
  display: grid;
  gap: 9px;
  border: 1px solid var(--pilot-line);
  border-radius: 14px;
  background: var(--pilot-surface);
  color: var(--pilot-text);
  padding: 12px;
  box-shadow: 0 18px 48px rgba(3, 10, 26, .28);
}
.parking-sector-editor label { display: grid; gap: 4px; color: var(--pilot-muted); font-size: .62rem; font-weight: 800; }
.parking-sector-editor :is(input, button) { min-height: 38px; border-radius: 9px; }
.parking-sector-editor input { border: 1px solid var(--pilot-line); background: var(--pilot-surface-2); color: var(--pilot-text); padding: 0 9px; }
.parking-sector-editor button { border: 0; background: var(--parking-accent); color: #fff; font-weight: 850; }

.self-profile-readonly {
  min-height: 48px;
  display: flex;
  align-items: center;
  border: 1px solid var(--pilot-line);
  border-radius: 11px;
  background: var(--pilot-surface-2);
  color: var(--pilot-text);
  padding: 10px 12px;
  font-weight: 800;
}
.self-profile-card form label > small { color: var(--pilot-muted); line-height: 1.4; }
.request-person-search { display: grid; gap: 5px; margin: 10px 0 12px; }
.request-person-search > span { color: var(--pilot-text); font-size: .66rem; font-weight: 850; }
.request-person-search input { min-height: 42px; border: 1px solid var(--pilot-line); border-radius: 10px; background: var(--pilot-surface-2); color: var(--pilot-text); padding: 0 11px; }

.secretary-assignment-status-list { display: grid; gap: 7px; margin: 12px 0; }
.secretary-assignment-status-list > article {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 9px;
  border: 1px solid var(--pilot-line);
  border-radius: 12px;
  background: var(--pilot-surface-2);
  padding: 9px;
}
.secretary-assignment-status-list article > div:nth-child(2) { display: grid; gap: 2px; }
.secretary-assignment-status-list small { color: var(--pilot-muted); }
.secretary-response-actions,
.secretary-manager-assignment-actions { display: flex; gap: 5px; }
.secretary-response-actions button,
.secretary-manager-assignment-actions button,
.secretary-replacement-form button {
  min-height: 34px;
  border: 1px solid var(--pilot-line);
  border-radius: 9px;
  background: var(--pilot-primary);
  color: #fff;
  padding: 0 9px;
  font-size: .62rem;
  font-weight: 850;
  cursor: pointer;
}
.secretary-response-actions .secondary,
.secretary-manager-assignment-actions button { background: var(--pilot-surface); color: var(--pilot-text); }
.secretary-replacement-form {
  display: grid;
  grid-template-columns: auto minmax(150px, 1fr) minmax(130px, 1fr) auto;
  align-items: center;
  gap: 8px;
  margin: 10px 0;
  border: 1px dashed var(--pilot-line);
  border-radius: 12px;
  padding: 10px;
}
.secretary-replacement-form :is(select, input) { min-height: 38px; border: 1px solid var(--pilot-line); border-radius: 9px; background: var(--pilot-surface-2); color: var(--pilot-text); padding: 0 9px; }

.event-registrants { margin-top: 12px; border-top: 1px solid var(--pilot-line); padding-top: 10px; }
.event-registrants > summary { color: var(--pilot-text); font-size: .7rem; font-weight: 850; cursor: pointer; }
.event-registrants > summary span { margin-left: 5px; border-radius: 999px; background: var(--pilot-surface-2); padding: 3px 7px; }
.event-registrants > div { display: grid; gap: 6px; margin-top: 9px; }
.event-registrants article { display: grid; grid-template-columns: 34px 1fr; align-items: center; gap: 8px; border-radius: 10px; background: var(--pilot-surface-2); padding: 8px; }
.event-registrants article > span { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 10px; background: color-mix(in srgb, var(--pilot-primary) 18%, var(--pilot-surface)); color: var(--pilot-primary); font-weight: 900; }
.event-registrants article > div { display: grid; gap: 2px; }
.event-registrants small { color: var(--pilot-muted); }

.login-shell.login-shell-v2[data-login-theme="escuro"] {
  --login-v2-card: rgba(5, 15, 38, .72);
  --login-v2-card-strong: rgba(4, 12, 31, .9);
  --login-v2-text: #f8fbff;
  --login-v2-muted: #c1cbe0;
  --login-v2-line: rgba(188, 208, 246, .32);
  background-color: #020617;
  background-image:
    radial-gradient(circle at 18% 22%, color-mix(in srgb, var(--login-accent) 34%, transparent), transparent 31%),
    radial-gradient(circle at 78% 58%, rgba(36, 99, 235, .34), transparent 38%),
    linear-gradient(145deg, #071a3d 0%, #020817 68%, #01040c 100%);
}
.login-shell.login-shell-v2[data-login-theme="escuro"]::before {
  background:
    linear-gradient(180deg, rgba(2, 8, 24, .04), rgba(1, 5, 15, .5)),
    radial-gradient(circle at 50% 36%, transparent 0 26%, rgba(1, 4, 13, .24) 76%);
}
.login-shell.login-shell-v2[data-login-theme="escuro"] .login-card.login-v2-card {
  box-shadow: 0 34px 100px rgba(0, 0, 0, .52), inset 0 1px 0 rgba(255,255,255,.06);
  backdrop-filter: blur(26px) saturate(135%);
}
.login-shell.login-shell-v2[data-login-theme="escuro"] .login-v2-card .login-form :is(input, textarea) {
  background: rgba(2, 9, 25, .78) !important;
  caret-color: var(--login-accent);
}

.secretary-share-window {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr)) auto;
  align-items: end;
  gap: 10px;
  margin: 12px 0;
  border: 1px solid var(--pilot-line);
  border-radius: 14px;
  padding: 12px;
}
.secretary-share-window legend { padding: 0 6px; color: var(--pilot-text); font-weight: 850; }
.secretary-share-window label { display: grid; gap: 5px; color: var(--pilot-muted); font-size: .7rem; font-weight: 800; }
.secretary-share-window input { min-width: 0; min-height: 40px; border: 1px solid var(--pilot-line); border-radius: 10px; background: var(--pilot-surface-2); color: var(--pilot-text); padding: 0 9px; }
.secretary-share-window button { min-height: 40px; border: 0; border-radius: 10px; background: var(--pilot-primary); color: white; padding: 0 13px; font-weight: 850; cursor: pointer; }
.secretary-share-window button:disabled { opacity: .5; cursor: not-allowed; }
.secretary-share-window > small { grid-column: 1 / -1; color: var(--pilot-muted); }
.shared-secretary-access-state { min-height: 100dvh; display: grid; place-items: center; padding: 24px; }
.shared-secretary-access-state > section { width: min(560px, 100%); border: 1px solid rgba(148,163,184,.28); border-radius: 24px; background: #101a29; color: #f8fafc; padding: clamp(24px, 6vw, 48px); box-shadow: 0 28px 80px rgba(0,0,0,.34); }
.shared-secretary-access-state h1 { margin: 20px 0 10px; font-size: clamp(1.8rem, 7vw, 3rem); }
.shared-secretary-access-state p { color: #b8c3d4; line-height: 1.6; }
.shared-secretary-pending-state .shared-secretary-countdown { display: grid; gap: 6px; margin: 20px 0; border: 1px solid rgba(148,163,184,.24); border-radius: 14px; background: rgba(255,255,255,.06); padding: 16px; }
.shared-secretary-pending-state .shared-secretary-countdown small { color: #9eacc0; font-weight: 800; }
.shared-secretary-pending-state .shared-secretary-countdown strong { color: #fff; font-size: clamp(1.25rem,6vw,2rem); }
.shared-secretary-pending-state button { width: 100%; min-height: 48px; border: 0; border-radius: 12px; background: linear-gradient(135deg,#7046e8,#35c9c2); color: #fff; font-weight: 900; cursor: pointer; }

@media (max-width: 680px) {
  .secretary-share-window { grid-template-columns: 1fr; }
  .secretary-share-window > small { grid-column: auto; }
}

@media (max-width: 760px) {
  .secretary-assignment-status-list > article { grid-template-columns: 38px minmax(0, 1fr); }
  .secretary-response-actions,
  .secretary-manager-assignment-actions { grid-column: 1 / -1; }
  .secretary-response-actions button,
  .secretary-manager-assignment-actions button { flex: 1; }
  .secretary-replacement-form { grid-template-columns: 1fr; }
  .parking-sector-editor > form { position: fixed; inset: auto 14px calc(96px + env(safe-area-inset-bottom)) 14px; width: auto; }
}

/* VÍNKULO — conversas, públicos e acompanhamento configurável */
.pilot-message-shortcut {
  position: relative;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid var(--pilot-line);
  border-radius: 14px;
  background: var(--pilot-surface);
  color: var(--pilot-text);
  font-size: 18px;
  cursor: pointer;
}
.pilot-message-shortcut:hover { border-color: var(--pilot-primary); color: var(--pilot-primary); }
.pilot-message-shortcut > svg {
  width: 22px;
  height: 22px;
  overflow: visible;
  stroke: currentColor;
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pilot-message-shortcut b {
  position: absolute;
  top: -5px;
  right: -5px;
  min-width: 19px;
  height: 19px;
  display: grid;
  place-items: center;
  padding: 0 5px;
  border: 2px solid var(--pilot-surface);
  border-radius: 999px;
  background: #dc405e;
  color: #fff;
  font-size: 9px;
}
.private-chat-avatar { position: relative; }
.private-chat-avatar > i {
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 10px;
  height: 10px;
  border: 2px solid var(--pilot-surface);
  border-radius: 50%;
  background: #778090;
}
.private-chat-avatar > i.online { background: #25b987; }

.visitor-category-section,
.request-audience {
  min-width: 0;
  border: 1px solid var(--pilot-line);
  border-radius: 20px;
  background: var(--pilot-surface);
  padding: 18px;
}
.visitor-category-section > header { display: flex; justify-content: space-between; gap: 16px; align-items: start; margin-bottom: 14px; }
.visitor-category-grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(220px,1fr)); gap: 12px; }
.visitor-category-grid > article {
  min-width: 0;
  display: grid;
  grid-template-columns: 42px minmax(0,1fr);
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--pilot-line);
  border-radius: 16px;
  background: var(--pilot-surface-2);
}
.visitor-category-grid > article > div { min-width: 0; display: grid; gap: 4px; }
.visitor-category-grid > article > div:last-child { grid-column: 1 / -1; grid-template-columns: 1fr auto; }
.visitor-category-grid input,
.visitor-category-grid select,
.visitor-category-grid textarea,
.visitor-category-create input,
.visitor-category-create select,
.visitor-category-create textarea { min-width: 0; width: 100%; min-height: 42px; border: 1px solid var(--pilot-line); border-radius: 11px; background: var(--pilot-surface); color: var(--pilot-text); padding: 0 11px; }
.visitor-category-grid textarea,.visitor-category-create textarea { min-height: 78px; padding-block: 10px; resize: vertical; }
.visitor-category-grid > article > div > p { margin: 0; color: var(--pilot-muted); font-size: .64rem; line-height: 1.45; }
.visitor-category-icon { width: 42px; height: 42px; display: grid; place-items: center; border-radius: 13px; background: color-mix(in srgb,var(--category-color,#7357e8) 16%,var(--pilot-surface)); color: var(--category-color,#7357e8); font-weight: 900; }
.visitor-category-create { display: grid; grid-template-columns: minmax(180px,1fr) 90px 70px minmax(180px,1fr) auto; gap: 10px; margin-top: 14px; }

.request-privacy-readonly { display: flex; align-items: center; min-height: 46px; border: 1px solid var(--pilot-line); border-radius: 12px; background: var(--pilot-surface-2); padding: 0 13px; color: var(--pilot-muted); }
.request-audience { display: grid; gap: 13px; }
.request-audience > legend { padding: 0 8px; font-weight: 900; }
.request-audience > p { margin: 0; color: var(--pilot-muted); }
.request-audience-grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(190px,1fr)); gap: 12px; }
.request-audience-grid > section { min-width: 0; padding: 13px; border: 1px solid var(--pilot-line); border-radius: 14px; background: var(--pilot-surface-2); }
.request-audience-grid > section > strong { display: block; margin-bottom: 9px; }
.request-audience-grid > section > div { display: grid; gap: 7px; max-height: 210px; overflow: auto; }
.request-audience-grid label { display: grid; grid-template-columns: auto minmax(0,1fr); align-items: start; gap: 8px; padding: 8px; border-radius: 10px; background: var(--pilot-surface); cursor: pointer; }
.request-audience-grid label span { min-width: 0; display: grid; gap: 2px; }
.request-audience-grid label small { color: var(--pilot-muted); }
.request-audience-preview { border-radius: 11px; background: color-mix(in srgb,var(--pilot-primary) 9%,var(--pilot-surface)); color: var(--pilot-primary); padding: 10px 12px; font-weight: 800; }

@media (max-width: 760px) {
  .pilot-message-shortcut { width: 42px; height: 42px; }
  .visitor-category-section { padding: 14px; }
  .visitor-category-grid { grid-template-columns: 1fr; }
  .visitor-category-create { grid-template-columns: 1fr 1fr; }
  .visitor-category-create > :first-child,
  .visitor-category-create > :nth-child(4),
  .visitor-category-create > button { grid-column: 1 / -1; }
  .request-audience { padding: 14px; }
  .request-audience-grid { grid-template-columns: 1fr; }
}

/* Cadastro institucional de comunidade — layout compacto e profissional. */
.create-community-dialog {
  width:min(920px,calc(100vw - 36px));
  padding:0;
  border-radius:26px;
  background:var(--pilot-surface,#fff);
  color:var(--pilot-text,#17202c);
}
.create-community-dialog::before { display:none; }
.create-community-dialog>header {
  margin:0;
  padding:30px 36px 24px;
  border-bottom:1px solid var(--pilot-line,#dce3ea);
  background:linear-gradient(135deg,color-mix(in srgb,var(--pilot-primary,#6d45ed) 7%,var(--pilot-surface,#fff)),var(--pilot-surface,#fff));
}
.create-community-dialog>header>div { max-width:690px; }
.create-community-dialog h2 { margin:6px 0 8px; color:var(--pilot-text,#17202c); font-size:clamp(30px,4vw,44px); line-height:1.05; letter-spacing:-.04em; }
.create-community-dialog header p:last-child { max-width:650px; color:var(--pilot-muted,#657082); font-size:14px; line-height:1.55; }
.create-community-dialog header>button { flex:0 0 auto; border-color:var(--pilot-line,#dce3ea); background:var(--pilot-surface-2,#f5f7fa); color:var(--pilot-text,#17202c); }
.create-community-progress { margin:22px 36px 0; padding:8px; border:1px solid var(--pilot-line,#dce3ea); border-radius:16px; background:var(--pilot-surface-2,#f5f7fa); }
.create-community-progress button { min-height:58px; border-radius:12px; background:transparent; }
.create-community-progress button.active { border-color:color-mix(in srgb,var(--pilot-primary,#6d45ed) 35%,var(--pilot-line,#dce3ea)); background:var(--pilot-surface,#fff); box-shadow:0 8px 22px rgb(12 20 35 / .08); }
.create-community-progress button strong { color:var(--pilot-text,#17202c); }
.create-community-progress button small { color:var(--pilot-muted,#657082); }
.create-community-form { padding:24px 36px 0; }
