.create-community-section label { min-width: 0; }
.create-community-section label small { display:block; margin-top:6px; color:#95a2b4; line-height:1.45; }
.create-community-loading { grid-column:1/-1; color:#aeb7c6; }
.create-community-seal-note {
  display:flex;
  align-items:center;
  gap:12px;
  padding:14px;
  border:1px solid rgba(53,189,125,.3);
  border-radius:15px;
  background:rgba(53,189,125,.09);
}
.create-community-seal-note > span { display:grid; width:34px; height:34px; place-items:center; border-radius:10px; background:#35bd7d; color:#07140e; font-weight:950; }
.create-community-seal-note strong,.create-community-seal-note small { display:block; }
.create-community-seal-note small { margin-top:3px; color:#aeb7c6; }

.public-mobile-nav .create-community-shortcut.compact {
  min-width:0;
  width:auto;
  min-height:52px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  gap:2px;
  margin:0;
  padding:3px 5px;
  border:0;
  border-radius:14px;
  background:transparent;
  box-shadow:none;
  text-align:center;
}
.public-mobile-nav .create-community-shortcut.compact > span { width:32px; height:32px; border-radius:50%; }
.public-mobile-nav .create-community-shortcut.compact strong { font-size:8px; }
.public-mobile-nav .create-community-shortcut.compact small { display:none; }

.pilot-desktop-community-switcher { position:relative; }
.pilot-desktop-community-switcher > summary {
  min-height:42px;
  max-width:245px;
  display:grid;
  grid-template-columns:30px minmax(0,1fr) auto;
  align-items:center;
  gap:8px;
  padding:5px 10px 5px 6px;
  border:1px solid var(--pilot-line);
  border-radius:13px;
  background:var(--pilot-surface);
  color:var(--pilot-text);
  cursor:pointer;
  list-style:none;
}
.pilot-desktop-community-switcher > summary::-webkit-details-marker { display:none; }
.pilot-desktop-community-switcher > summary > span { width:30px; height:30px; display:grid; place-items:center; border-radius:9px; background:var(--pilot-gradient); color:#fff; font-size:8px; font-weight:950; }
.pilot-desktop-community-switcher > summary strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:9px; }
.pilot-desktop-community-switcher > summary i { font-style:normal; }
.pilot-desktop-community-switcher > div {
  position:absolute;
  z-index:180;
  top:calc(100% + 9px);
  right:0;
  width:min(340px, calc(100vw - 24px));
  padding:12px;
  border:1px solid var(--pilot-line);
  border-radius:17px;
  background:var(--pilot-surface);
  box-shadow:0 24px 70px rgba(4,10,20,.24);
}
.pilot-desktop-community-switcher input { width:100%; min-height:40px; border:1px solid var(--pilot-line); border-radius:11px; background:var(--pilot-surface-2); color:var(--pilot-text); padding:0 12px; }
.pilot-desktop-community-switcher nav { display:grid; gap:6px; max-height:300px; overflow:auto; margin-top:9px; }
.pilot-desktop-community-switcher nav button { display:grid; grid-template-columns:34px 1fr; align-items:center; gap:9px; padding:8px; border:1px solid var(--pilot-line); border-radius:11px; background:var(--pilot-surface); color:var(--pilot-text); text-align:left; cursor:pointer; }
.pilot-desktop-community-switcher nav button > span { width:34px; height:34px; display:grid; place-items:center; border-radius:10px; background:var(--pilot-surface-2); color:var(--pilot-purple); font-weight:900; }
.pilot-desktop-community-switcher nav button strong,.pilot-desktop-community-switcher nav button small { display:block; }
.pilot-desktop-community-switcher nav button small { margin-top:2px; color:var(--pilot-muted); }
.pilot-desktop-community-switcher nav button.active { border-color:var(--pilot-purple); }

.community-creation-config {
  overflow:hidden;
  border:1px solid var(--pilot-line);
  border-radius:22px;
  background:var(--pilot-surface);
}
.community-creation-config-toggle { width:100%; display:grid; grid-template-columns:42px minmax(0,1fr) auto; align-items:center; gap:13px; padding:18px; border:0; background:transparent; color:var(--pilot-text); text-align:left; cursor:pointer; }
.community-creation-config-toggle > span { width:42px; height:42px; display:grid; place-items:center; border-radius:13px; background:var(--pilot-gradient); color:#fff; font-size:20px; }
.community-creation-config-toggle strong,.community-creation-config-toggle small { display:block; }
.community-creation-config-toggle small { margin-top:4px; color:var(--pilot-muted); }
.community-creation-config-toggle em { color:var(--pilot-purple); font-style:normal; font-weight:900; }
.community-creation-config-body { padding:0 18px 18px; border-top:1px solid var(--pilot-line); }
.community-creation-config-body > header { display:flex; justify-content:space-between; gap:18px; padding:18px 0; }
.community-creation-config-body > header h3 { margin:3px 0; }
.community-creation-config-body > header p:last-child { color:var(--pilot-muted); }
.community-creation-config-body button { border:0; border-radius:11px; background:var(--pilot-gradient); color:#fff; padding:10px 13px; font-weight:900; }
.community-creation-field-list { display:grid; gap:9px; }
.community-creation-field-list article { display:grid; grid-template-columns:32px 1.2fr .7fr 1.2fr auto auto auto; align-items:end; gap:9px; padding:12px; border:1px solid var(--pilot-line); border-radius:14px; background:var(--pilot-surface-2); }
.community-creation-field-list article > span { align-self:center; font-weight:950; color:var(--pilot-purple); }
.community-creation-field-list label { display:grid; gap:6px; color:var(--pilot-muted); font-size:8px; font-weight:800; }
.community-creation-field-list :is(input,select) { min-height:39px; border:1px solid var(--pilot-line); border-radius:10px; background:var(--pilot-surface); color:var(--pilot-text); padding:0 10px; }
.community-creation-field-list label.toggle { display:flex; align-items:center; gap:6px; min-height:39px; color:var(--pilot-text); }
.community-creation-field-list label.toggle input { min-height:0; width:auto; }
.community-creation-field-list button.danger { min-height:39px; }
.community-creation-config-save { display:flex; align-items:center; justify-content:space-between; gap:15px; margin-top:14px; padding-top:14px; border-top:1px solid var(--pilot-line); }
.community-creation-config-save p { margin:0; color:var(--pilot-muted); }

.login-builder-actions,.signup-account-header-actions { display:flex; align-items:center; gap:8px; }
.login-builder-actions button.secondary,.signup-account-header-actions button { min-height:36px; padding:0 11px; border:1px solid var(--pilot-line); border-radius:10px; background:var(--pilot-surface); color:var(--pilot-text); font-size:8px; font-weight:900; }
.signup-account-header-actions > strong { padding:6px 9px; border-radius:999px; background:color-mix(in srgb,var(--pilot-purple) 10%,var(--pilot-surface)); color:var(--pilot-purple); font-size:8px; }
.signup-account-search { display:block; padding:14px 14px 0; }
.signup-account-search input { width:100%; min-height:42px; border:1px solid var(--pilot-line); border-radius:12px; background:var(--pilot-surface); color:var(--pilot-text); padding:0 13px; }
.signup-delete-data { margin:0 13px 13px; border:1px solid #d65a70; border-radius:10px; background:transparent; color:#d24e66; padding:9px 12px; font-weight:850; }
.signup-delete-data:disabled { opacity:.4; }

.editorial-manual-publish { display:grid; grid-template-columns:minmax(0,1fr) minmax(160px,.5fr) auto; align-items:center; gap:10px; margin-top:14px; padding:13px; border:1px solid rgba(53,189,125,.3); border-radius:13px; background:rgba(53,189,125,.08); }
.editorial-manual-publish strong,.editorial-manual-publish small { display:block; }
.editorial-manual-publish small { margin-top:3px; color:var(--pilot-muted); }
.editorial-manual-publish input { min-height:40px; border:1px solid var(--pilot-line); border-radius:10px; background:var(--pilot-surface); color:var(--pilot-text); padding:0 11px; }

.pastoral-seal-panel { border:1px solid var(--pilot-line); border-radius:22px; background:var(--pilot-surface); padding:20px; }
.pastoral-seal-panel > header { display:flex; justify-content:space-between; gap:16px; }
.pastoral-seal-panel > header h2 { margin:4px 0; }
.pastoral-seal-panel > header p:last-child { color:var(--pilot-muted); }
.pastoral-seal-panel > header > span { height:max-content; padding:7px 10px; border-radius:999px; background:rgba(128,89,238,.1); color:var(--pilot-purple); font-weight:900; }
.pastoral-seal-panel > div { display:grid; gap:10px; margin-top:16px; }
.pastoral-seal-panel article { display:grid; grid-template-columns:minmax(0,1fr) auto minmax(220px,.65fr); gap:14px; align-items:center; padding:15px; border:1px solid var(--pilot-line); border-radius:15px; background:var(--pilot-surface-2); }
.pastoral-seal-panel article strong,.pastoral-seal-panel article small,.pastoral-seal-panel article em { display:block; }
.pastoral-seal-panel article p { margin:4px 0; color:var(--pilot-muted); }
.pastoral-seal-panel article em { color:var(--pilot-muted); font-style:normal; }
.pastoral-seal-status { padding:6px 9px; border-radius:999px; font-size:8px; font-weight:950; }
.pastoral-seal-status.status-pendente { background:rgba(216,154,54,.13); color:#bb7810; }
.pastoral-seal-status.status-aprovado { background:rgba(53,189,125,.13); color:#279f69; }
.pastoral-seal-status.status-rejeitado { background:rgba(220,77,102,.12); color:#c54058; }
.pastoral-seal-actions { display:grid; grid-template-columns:1fr auto auto; gap:8px; }
.pastoral-seal-actions label:first-child { grid-column:1/-1; }
.pastoral-seal-actions label { display:grid; gap:5px; color:var(--pilot-muted); font-size:8px; font-weight:800; }
.pastoral-seal-actions input { min-height:38px; border:1px solid var(--pilot-line); border-radius:10px; background:var(--pilot-surface); color:var(--pilot-text); padding:0 10px; }

html[data-pilot-theme="escuro"] .public-social-home {
  background:linear-gradient(rgba(5,8,13,.78),rgba(5,8,13,.92)),var(--platform-feed-banner,none) center top/cover fixed,#070b11;
}

@media (prefers-color-scheme: dark) {
  html:not([data-pilot-theme]) .public-social-home {
    background:linear-gradient(rgba(5,8,13,.78),rgba(5,8,13,.92)),var(--platform-feed-banner,none) center top/cover fixed,#070b11;
  }
}

@media (max-width: 900px) {
  .pilot-desktop-community-switcher { display:none; }
  .community-creation-field-list article { grid-template-columns:32px repeat(2,minmax(0,1fr)); }
  .community-creation-field-list article .wide { grid-column:2/-1; }
  .community-creation-field-list article button.danger { grid-column:2/-1; }
  .pastoral-seal-panel article { grid-template-columns:1fr auto; }
  .pastoral-seal-actions { grid-column:1/-1; }
}

@media (max-width: 760px) {
  .create-community-backdrop {
    align-items:end;
    padding:max(12px, env(safe-area-inset-top)) 0 0;
  }
  .create-community-dialog {
    width:100%;
    max-height:calc(100dvh - max(12px, env(safe-area-inset-top)));
    padding:18px 16px calc(24px + env(safe-area-inset-bottom));
    border-radius:24px 24px 0 0;
  }
  .create-community-dialog h2 { font-size:27px; }
  .create-community-section { grid-template-columns:1fr; padding:14px; }
  .create-community-section .composer-wide { grid-column:auto; }
  .community-creation-config-toggle { grid-template-columns:38px minmax(0,1fr); }
  .community-creation-config-toggle em { grid-column:2; }
  .community-creation-config-body > header,.community-creation-config-save { flex-direction:column; align-items:stretch; }
  .community-creation-field-list article { grid-template-columns:28px 1fr; }
  .community-creation-field-list article > :not(span) { grid-column:2; }
  .login-builder-actions,.signup-account-header-actions { width:100%; justify-content:space-between; }
  .editorial-manual-publish { grid-template-columns:1fr; }
  .pastoral-seal-panel { padding:16px; }
  .pastoral-seal-panel > header { flex-direction:column; }
  .pastoral-seal-panel article { grid-template-columns:1fr; }
  .pastoral-seal-actions { grid-template-columns:1fr; }
  .pastoral-seal-actions label:first-child { grid-column:auto; }
}

* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-geist-sans), Arial, sans-serif;
}
button,
input,
select,
textarea {
  font: inherit;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}

.login-shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(430px, 0.8fr);
  background: var(--login-bg);
}
.login-shell.mode-cadastro {
  grid-template-columns:minmax(320px,.85fr) minmax(560px,1.15fr);
}
.login-showcase {
  position: relative;
  overflow: hidden;
  padding: clamp(34px, 6vw, 78px);
  color: white;
  background:
    radial-gradient(
      circle at 82% 12%,
      color-mix(in srgb, var(--login-accent) 72%, transparent),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      var(--login-bg),
      color-mix(in srgb, var(--login-bg) 72%, #000)
    );
}
.login-showcase::after {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  right: -170px;
  bottom: -180px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;
  box-shadow:
    0 0 0 55px rgba(255, 255, 255, 0.03),
    0 0 0 110px rgba(255, 255, 255, 0.02);
  pointer-events: none;
}
.login-brand {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 13px;
}
.login-brand > span,
.setup-mark {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: var(--login-accent, var(--teal));
  color: white;
  font-size: 22px;
  font-weight: 850;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.16);
}
.login-brand img {
  width: 48px;
  height: 48px;
  object-fit: contain;
  border-radius: 14px;
  padding: 4px;
  background: white;
}
.login-brand strong {
  font-size: 18px;
  letter-spacing: 0.09em;
}
.login-welcome {
  position: relative;
  z-index: 1;
  max-width: 720px;
  margin-top: clamp(70px, 12vh, 130px);
}
.login-kicker {
  color: var(--login-accent, var(--teal));
  margin: 0 0 10px;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.16em;
}
.login-showcase .login-kicker {
  color: color-mix(in srgb, var(--login-accent) 55%, white);
}
.login-welcome h1 {
  max-width: 680px;
  margin: 0 0 18px;
  font-size: clamp(38px, 5.2vw, 72px);
  line-height: 0.99;
  letter-spacing: -0.055em;
}
.login-welcome > p:last-child {
  max-width: 600px;
  margin: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: clamp(13px, 1.5vw, 17px);
  line-height: 1.7;
}
.login-message-list {
  position: relative;
  z-index: 1;
  max-width: 720px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 38px;
}
.login-message-list article {
  min-height: 82px;
  display: grid;
  grid-template-columns: 30px 1fr;
  gap: 10px;
  align-items: start;
  padding: 17px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(10px);
}
.login-message-list span {
  color: color-mix(in srgb, var(--login-accent) 50%, white);
  font-size: 9px;
  font-weight: 850;
}
.login-message-list p {
  margin: 0;
  color: rgba(255, 255, 255, 0.82);
  font-size: 11px;
  line-height: 1.55;
}
.login-public-news {
  position: relative;
  z-index: 1;
  max-width: 720px;
  margin-top: 28px;
}
.login-public-news > article {
  display: grid;
  grid-template-columns: 74px 1fr;
  gap: 5px 12px;
  padding: 12px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}
.login-public-news small {
  grid-row: 1 / 3;
  align-self: start;
  width: max-content;
  border-radius: 999px;
  padding: 4px 7px;
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.72);
  font-size: 7px;
  font-weight: 800;
}
.login-public-news strong {
  font-size: 11px;
}
.login-public-news article p {
  margin: 0;
  color: rgba(255, 255, 255, 0.6);
  font-size: 9px;
}
.login-public-news .login-news-urgente {
  border-left: 3px solid #f07a7a;
  padding-left: 11px;
}
.login-access {
  min-height: 100vh;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 22px;
  padding: clamp(24px, 5vw, 70px);
  background: #f6f8f9;
}
.login-card {
  width: min(460px, 100%);
  padding: clamp(27px, 4vw, 42px);
  border: 1px solid #e0e7ea;
  border-radius: 24px;
  background: white;
  box-shadow: 0 30px 80px rgba(16, 43, 67, 0.11);
}
.login-card.signup-card { width:min(720px,100%); }
.login-card-header {
  display: flex;
  align-items: center;
  gap: 13px;
}
.login-lock {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: color-mix(in srgb, var(--login-accent) 12%, white);
  color: var(--login-accent);
  font-size: 20px;
}
.login-card h2 {
  margin: 0;
  color: #17324d;
  font-size: 24px;
  letter-spacing: -0.035em;
}
.login-card .login-kicker {
  margin-bottom: 4px;
}
.login-explanation {
  margin: 20px 0;
  color: #70818e;
  font-size: 11px;
  line-height: 1.65;
}
.login-form {
  display: grid;
  gap: 15px;
}
.login-signup-form { grid-template-columns:repeat(2,minmax(0,1fr)); }
.login-signup-form .login-signup-wide,
.login-signup-form .login-terms-check,
.login-signup-form .login-feedback,
.login-signup-form .login-submit { grid-column:1/-1; }
.login-form label,
.setup-form label {
  color: #243d50;
  font-size: 9px;
  font-weight: 800;
}
.login-form input,
.login-form textarea,
.setup-form input {
  width: 100%;
  min-height: 47px;
  margin-top: 7px;
  border: 1px solid #dbe4e8;
  border-radius: 11px;
  background: #fbfcfd;
  color: #20313f;
  padding: 0 13px;
  outline: none;
  font-size: 12px;
}
.login-form textarea {
  min-height:92px;
  padding:12px 13px;
  resize:vertical;
}
.login-form input:focus,
.login-form textarea:focus,
.setup-form input:focus {
  border-color: var(--login-accent, var(--teal));
  box-shadow: 0 0 0 3px
    color-mix(in srgb, var(--login-accent, var(--teal)) 12%, transparent);
}
.password-field {
  position: relative;
}
.password-field input {
  padding-right: 75px;
}
.password-field button {
  position: absolute;
  right: 10px;
  top: 18px;
  border: 0;
  background: none;
  color: var(--login-accent);
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}
.login-submit {
  width: 100%;
  min-height: 47px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 12px;
  background: var(--login-accent, var(--teal));
  color: white;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
  box-shadow: 0 10px 25px
    color-mix(in srgb, var(--login-accent, var(--teal)) 25%, transparent);
  cursor: pointer;
}
.login-submit:disabled {
  opacity: 0.6;
  cursor: wait;
}
.login-feedback {
  margin: 0;
  padding: 13px 14px;
  border: 1px solid #f0c36d;
  border-radius: 10px;
  background: #fff4dc;
  color: #67430a;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.5;
}
.login-links {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 18px;
}
.login-links button {
  border: 0;
  background: none;
  color: var(--login-accent);
  padding: 3px 0;
  font-size: 9px;
  font-weight: 750;
  cursor: pointer;
}
.login-admin-first {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid #edf1f3;
  color: #8a9aa5;
  font-size: 8px;
}
.login-admin-first a {
  color: #607889;
  font-weight: 750;
}
.login-access footer {
  color: #91a0aa;
  font-size: 8px;
}
.setup-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 20% 10%, #e0f1ee, transparent 32%), #f4f7f8;
}
.setup-card {
  width: min(500px, 100%);
  padding: 38px;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: white;
  box-shadow: 0 30px 80px rgba(23, 50, 77, 0.1);
}
.setup-card h1 {
  color: var(--navy);
  margin: 17px 0 10px;
  font-size: 27px;
  letter-spacing: -0.04em;
}
.setup-card > p:not(.login-kicker) {
