  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: white;
  padding: 16px;
  box-shadow: var(--shadow);
}
.mobile-menu-card.notice-menu-card {
  border-color: #e7c16f;
  background: linear-gradient(135deg, #fff7e3, #fff);
}
.mobile-menu-open,
.mobile-menu-label {
  border: 0;
  background: none;
  cursor: pointer;
}
.mobile-menu-open {
  min-height: 54px;
  display: grid;
  place-items: center;
  padding: 0;
  color: var(--teal);
}
.mobile-menu-card.notice-menu-card .mobile-menu-open {
  color: #c48418;
}
.mobile-menu-open span {
  font-size: 25px;
}
.mobile-menu-card > div {
  min-width: 0;
  display: grid;
  gap: 7px;
}
.mobile-menu-card input {
  width: 100%;
  min-width: 0;
  border: 1px dashed #bccbd2;
  border-radius: 8px;
  background: #f8fafb;
  color: var(--navy);
  padding: 7px 8px;
  outline: none;
  font-size: 11px;
  font-weight: 750;
}
.mobile-menu-card .inline-name-trigger {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0;
  color: var(--navy);
  text-align: left;
  font-size: 12px;
  font-weight: 750;
}
.mobile-menu-name .inline-name-trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  border-bottom: 1px solid #e4c77e;
  padding: 7px 0;
  color: var(--navy);
  text-align: left;
  font-size: 13px;
  font-weight: 750;
}
.mobile-menu-card input:focus {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(23, 135, 127, 0.09);
}
.mobile-menu-label {
  padding: 0;
  color: var(--navy);
  text-align: left;
  font-size: 12px;
  font-weight: 750;
}
.mobile-menu-card small {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.4;
}
.site-footer {
  margin-top: 44px;
  padding: 24px 0 0;
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  color: var(--muted);
}
.site-footer > div {
  display: grid;
  gap: 5px;
}
.site-footer strong {
  color: var(--navy);
  font-size: 13px;
  letter-spacing: 0.08em;
}
.site-footer span,
.site-footer small {
  font-size: 9px;
}
.future-contacts {
  justify-items: end;
}
.future-contacts span {
  color: #4f6575;
  font-weight: 650;
}
.future-contacts a {
  color: var(--teal);
  text-decoration: none;
  font-size: 9px;
  font-weight: 700;
}
.future-contacts small {
  color: #8a9aa5;
}
.access-blocked {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: var(--canvas);
}
.access-blocked > div {
  width: min(440px, 100%);
  padding: 38px;
  border-radius: 20px;
  background: white;
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  text-align: center;
}
.access-blocked span {
  color: var(--teal);
  font-size: 34px;
}
.access-blocked h1 {
  color: var(--navy);
  margin: 12px 0 8px;
}
.access-blocked p {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}
.access-blocked a {
  display: inline-flex;
  margin-top: 12px;
  color: var(--teal);
  font-size: 11px;
  font-weight: 750;
}
.login-admin-first {
  display: none !important;
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.section-block {
  margin-top: 30px;
}
.section-block + .section-block {
  margin-top: 38px;
}
.team-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}
.team-grid > .empty-state {
  grid-column: 1 / -1;
}
.team-card {
  --team-color: var(--teal);
  position: relative;
  overflow: hidden;
  display: grid;
  gap: 17px;
  min-width: 0;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: white;
  box-shadow: var(--shadow);
}
.team-stripe {
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  background: var(--team-color);
}
.team-card header {
  display: flex;
  align-items: center;
  gap: 12px;
}
.team-card header h3 {
  margin: 0 0 4px;
  color: var(--navy);
  font-size: 16px;
}
.team-card header p {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}
.team-color {
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  border: 4px solid color-mix(in srgb, var(--team-color) 18%, white);
  border-radius: 50%;
  background: var(--team-color);
}
.service-card {
  position: relative;
  overflow: hidden;
}
.team-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--team-color);
}
.role-pill.complete {
  color: #15725d;
  background: #e4f7f0;
}
.resource-links {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.resource-link-card {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-items: center;
  gap: 1px 9px;
  min-width: 0;
  padding: 12px;
  border: 1px solid #dce7ea;
  border-radius: 12px;
  background: #f8fbfb;
  color: var(--navy);
  text-decoration: none;
  transition:
    transform 0.15s ease,
    border-color 0.15s ease;
}
.resource-link-card:hover {
  transform: translateY(-2px);
  border-color: var(--teal);
}
.resource-link-card > span {
  grid-row: 1 / 3;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: var(--teal);
  color: white;
  font-size: 13px;
}
.resource-link-card strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10px;
}
.resource-link-card small {
  color: var(--muted);
  font-size: 8px;
}
.checklist-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}
.checklist-item {
  display: flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 9px !important;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: #f8fafb;
  color: var(--navy);
}
.checklist-item input {
  width: 17px;
  height: 17px;
  accent-color: var(--teal);
}
.checklist-complete {
  padding: 14px;
  border-radius: 12px;
  background: #edf8f6;
  color: var(--navy);
}
.checklist-summary {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-bottom: 12px;
  color: var(--muted);
  font-size: 10px;
}
.checklist-summary strong {
  color: var(--teal);
  font-size: 20px;
}
.ranking-panel {
  margin-top: 38px;
  padding: 26px;
  border: 1px solid #dbe6e7;
  border-radius: 20px;
  background: linear-gradient(145deg, #f7fbfb, white);
  box-shadow: var(--shadow);
}
.ranking-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-bottom: 22px;
}
.ranking-header h2 {
  margin: 4px 0 5px;
  color: var(--navy);
  font-size: 21px;
}
.ranking-header p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}
.ranking-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.ranking-list {
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: white;
}
.ranking-list h3 {
  margin: 0 0 12px;
  color: var(--navy);
  font-size: 13px;
}
.ranking-row {
  display: grid;
  grid-template-columns: 30px 10px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 10px 0;
  border-top: 1px solid #edf1f3;
}
.ranking-position {
  color: var(--teal);
  font-size: 11px;
}
.ranking-color {
  width: 10px;
  height: 26px;
  border-radius: 8px;
}
.ranking-row > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.ranking-row > div strong {
  overflow: hidden;
  color: var(--navy);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ranking-row small {
  color: var(--muted);
  font-size: 8px;
}
.ranking-row > b {
  color: var(--navy);
  font-size: 9px;
  white-space: nowrap;
}

/* Controles de cor mais claros e fáceis de tocar */
.form-grid input[type="color"] {
  height: 58px;
  padding: 6px;
  border: 1px solid #cfdde2;
  border-radius: 13px;
  background: linear-gradient(135deg, #f5f8f9, #fff);
  cursor: pointer;
}
.form-grid input[type="color"]::-webkit-color-swatch-wrapper {
  padding: 0;
}
.form-grid input[type="color"]::-webkit-color-swatch {
  border: 0;
  border-radius: 9px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.08);
}
.form-grid input[type="color"]::-moz-color-swatch {
  border: 0;
  border-radius: 9px;
}
.color-picker-card,
.admin-settings label:has(input[type="color"]) {
  padding: 11px;
  border: 1px solid #dce6e9;
  border-radius: 14px;
  background: linear-gradient(145deg, #f8fbfb, #fff);
}

/* Pessoas cadastradas nas equipes de diaconia */
.member-picker {
  margin: 0;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 15px;
}
.member-picker legend {
  padding: 0 7px;
}
.member-picker > div {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 12px;
}
.member-picker > div > label {
  min-width: 0;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: center;
  gap: 2px 8px;
  padding: 11px;
  border: 1px solid #e0e8eb;
  border-radius: 11px;
  background: #f8fafb;
}
.member-picker input {
  width: 17px;
  height: 17px;
  grid-row: 1 / 3;
  margin: 0;
  accent-color: var(--teal);
}
.member-picker span {
  overflow: hidden;
  color: var(--navy);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.member-picker small {
  color: #a56a12;
  font-size: 7px;
}

/* Checklist por tarefa e resultados com cores */
.task-checklist {
  display: grid;
  gap: 12px;
}
.task-check-card {
  overflow: hidden;
  border: 1px solid #dfe7ea;
  border-left: 5px solid #a8b4bc;
  border-radius: 14px;
  background: #fff;
}
.task-check-card.task-feita {
  border-left-color: #2d9a70;
}
.task-check-card.task-ausente {
  border-left-color: #d45e5e;
}
.task-check-card.task-substituto {
  border-left-color: #6c68bd;
}
.task-check-card.task-pendente {
  border-left-color: #d6a03f;
}
.task-check-card > header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 14px;
  background: #f8fafb;
}
.task-check-card > header > span {
  width: 26px;
  height: 26px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: var(--navy);
  color: #fff;
  font-size: 9px;
  font-weight: 800;
}
.task-check-card > header div {
  display: grid;
  gap: 3px;
}
.task-check-card > header strong {
  color: var(--navy);
  font-size: 11px;
}
.task-check-card > header small {
  color: var(--muted);
  font-size: 8px;
}
.task-check-fields {
  display: grid;
  grid-template-columns: 0.8fr 1.1fr 1.1fr;
  gap: 10px;
  padding: 13px 14px 16px;
}
.task-result > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}
.task-result > b {
  border-radius: 999px;
  padding: 5px 8px;
  font-size: 7px;
  text-transform: uppercase;
}
.task-result.task-feita > span,
.task-result.task-feita > b {
  color: #15725d;
  background: #e4f7f0;
}
.task-result.task-ausente > span,
.task-result.task-ausente > b {
  color: #a43c48;
  background: #fbe8ea;
}
.task-result.task-substituto > span,
.task-result.task-substituto > b {
  color: #574d9b;
  background: #eeeafd;
}
.task-result.task-pendente > span,
.task-result.task-pendente > b {
  color: #8a611d;
  background: #fff3da;
}

/* Interações nas notícias */
.news-interactions {
  margin-top: 15px;
  padding-top: 13px;
  border-top: 1px solid #e8eef0;
}
.reaction-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.reaction-bar button {
  min-width: 43px;
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid #dce5e8;
  border-radius: 999px;
  background: #f8fafb;
  cursor: pointer;
}
.reaction-bar button.selected {
  border-color: var(--teal);
  background: var(--teal-soft);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--teal) 10%, transparent);
}
.reaction-bar span {
  font-size: 15px;
}
.reaction-bar b {
  color: var(--navy);
  font-size: 8px;
}
.comments-panel {
  margin-top: 11px;
}
.comments-panel > summary {
  color: var(--navy);
  font-size: 9px;
  font-weight: 800;
}
.comments-list {
  display: grid;
  gap: 8px;
  margin-top: 10px;
}
.comments-list article {
  position: relative;
  padding: 10px 11px;
  border: 1px solid #e3e9ec;
  border-radius: 10px;
  background: #f8fafb;
}
.comments-list article > div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.comments-list strong {
  color: var(--navy);
  font-size: 9px;
}
.comments-list time {
  color: var(--muted);
  font-size: 7px;
}
.comments-list p {
  margin: 6px 0 0 !important;
  color: #4b606f !important;
  font-size: 9px !important;
}
.comments-list article > button {
  margin-top: 7px;
  border: 0;
  background: none;
  color: #b14d58;
  padding: 0;
  font-size: 7px;
  font-weight: 800;
  cursor: pointer;
}
.comment-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
  margin-top: 10px;
}
.comment-form input {
  min-width: 0;
  border: 1px solid #dce5e8;
  border-radius: 10px;
  padding: 9px 10px;
  background: #fff;
  font-size: 9px;
  outline: none;
}
.comment-form input:focus {
  border-color: var(--teal);
}
.comment-form button {
  border: 0;
  border-radius: 10px;
  padding: 0 12px;
  background: var(--teal);
  color: white;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}

/* Área Teens */
.teens-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}
.teens-grid > .empty-state {
  grid-column: 1 / -1;
}
.teen-card {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: linear-gradient(145deg, #fff, #f6fbfb);
  box-shadow: var(--shadow);
}
.teen-age {
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  align-content: center;
  border-radius: 18px;
  background: var(--teal);
  color: white;
  font-size: 19px;
  font-weight: 850;
}
.teen-age small {
  font-size: 7px;
  font-weight: 700;
  text-transform: uppercase;
}
.teen-card h2 {
  margin: 0 0 7px;
  color: var(--navy);
  font-size: 15px;
}
.teen-card p {
  margin: 3px 0;
  color: var(--muted);
  font-size: 9px;
}
.teen-card p strong {
  color: #435a6a;
}

/* Caixas de texto livres */
.text-box-zone {
  display: grid;
  gap: 11px;
  margin-bottom: 24px;
}
.text-box-rodape {
  margin-top: 32px;
  margin-bottom: 0;
}
.add-text-box {
  width: max-content;
  max-width: 100%;
  border: 1px dashed color-mix(in srgb, var(--teal) 48%, #cbd7dc);
  border-radius: 11px;
  background: color-mix(in srgb, var(--teal) 5%, white);
  color: var(--teal);
  padding: 9px 12px;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}
.text-box-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
}
.custom-text-box {
  min-width: 0;
  padding: 17px 18px;
  border: 1px solid color-mix(in srgb, var(--box-color) 72%, #cad6da);
  border-left: 5px solid color-mix(in srgb, var(--box-color) 58%, var(--navy));
  border-radius: 14px;
  background: color-mix(in srgb, var(--box-color) 72%, white);
}
.custom-text-box h3 {
  margin: 0 0 8px;
  color: var(--navy);
  font-size: 14px;
}
.custom-text-box p {
  margin: 0;
  color: #405666;
  font-size: 10px;
  line-height: 1.65;
  white-space: pre-wrap;
}
.custom-text-box > div {
  display: flex;
  gap: 7px;
  margin-top: 12px;
}
.custom-text-box > div button {
  border: 0;
  border-radius: 8px;
  padding: 6px 9px;
  background: rgba(255, 255, 255, 0.75);
  color: var(--navy);
  font-size: 7px;
  font-weight: 800;
  cursor: pointer;
}
.custom-text-box > div button:last-child {
  color: #a94450;
}
@keyframes reveal {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes modal-in {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 1080px) {
  .metrics-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .dashboard-grid,
  .bottom-grid {
    grid-template-columns: 1fr;
  }
  .security-grid {
    grid-template-columns: 1fr;
  }
  .team-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .teens-grid {
    grid-template-columns: 1fr;
  }
  .report-grid {
    grid-template-columns: 1fr;
  }
  .news-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .module-grid {
    grid-template-columns: 1fr;
  }
  .news-strip {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .login-shell {
    grid-template-columns: 1fr;
  }
  .login-shell.mode-cadastro { grid-template-columns:1fr; }
  .login-showcase {
    min-height: auto;
    padding: 28px 20px 36px;
  }
  .login-welcome {
    margin-top: 48px;
  }
  .login-welcome h1 {
    font-size: 39px;
  }
  .login-message-list {
    grid-template-columns: 1fr;
    margin-top: 28px;
  }
  .login-message-list article:nth-child(n + 4) {
    display: none;
  }
  .login-public-news {
    margin-top: 22px;
  }
  .login-public-news > article:nth-child(n + 3) {
    display: none;
  }
  .login-access {
    min-height: auto;
    padding: 28px 16px 42px;
  }
  .login-card {
    padding: 25px 20px;
    border-radius: 20px;
  }
  .login-signup-form { grid-template-columns:1fr; }
  .login-signup-form .login-signup-wide,
  .login-signup-form .login-terms-check,
  .login-signup-form .login-feedback,
  .login-signup-form .login-submit { grid-column:1; }
  .login-links,
  .login-admin-first {
    flex-direction: column;
  }
  .setup-card {
    padding: 28px 21px;
  }
  body {
    padding-bottom: 76px;
  }
