  }
  .page-header > .primary-button {
    width: auto;
    max-width: 48%;
    padding: 0 13px;
    white-space: normal;
    line-height: 1.2;
  }
  .header-actions {
    width: 100%;
  }
  .header-actions > button {
    flex: 1;
    padding-inline: 10px;
  }
  .page-header > .primary-button span {
    font-size: 18px;
    margin: 0 3px 0 0;
  }
  .metrics-grid {
