  .mobile-nav > button {
    color: var(--muted);
    border: 0;
    background: none;
    display: grid;
    justify-items: center;
    gap: 3px;
    font-size: 8px;
    cursor: pointer;
  }
  .mobile-nav > button span {
    font-size: 17px;
  }
  .mobile-nav > button.active {
    color: var(--teal);
  }
  .mobile-nav > button.notice-mobile {
    color: #b9770d;
  }
  .mobile-nav > button.notice-mobile.active {
    color: #9b6207;
  }
  .mobile-nav > button.mobile-add {
    justify-self: center;
    width: 45px;
    height: 45px;
    margin-top: -24px;
    border: 4px solid var(--canvas);
    border-radius: 15px;
    background: var(--teal);
    color: white;
    font-size: 24px;
    box-shadow: 0 7px 16px rgba(23, 135, 127, 0.25);
  }
  .page-header {
    align-items: center;
  }
  .list-toolbar {
    align-items: stretch;
    flex-direction: column;
  }
  .person-card {
    grid-template-columns: 38px 1fr;
  }
  .person-card .secondary-button {
    grid-column: 1 / -1;
  }
  .followup-card {
    grid-template-columns: 38px 1fr;
  }
  .followup-card .row-actions {
    grid-column: 1 / -1;
  }
  .user-card {
    grid-template-columns: 38px 1fr auto;
  }
  .user-card .role-pill,
  .user-card .active-label,
  .user-card .inactive-label {
    display: none;
  }
  .user-card-actions {
    grid-column: 1 / -1;
    width: 100%;
  }
  .user-card-actions button {
    flex: 1;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
  .span-2 {
    grid-column: 1;
  }
  .permission-grid {
    grid-template-columns: 1fr;
  }
  .modal {
    padding: 19px;
  }
  .pdf-editor,
  .detail-sheet {
    grid-template-columns: 1fr;
  }
  .pdf-actions,
  .detail-field.wide {
    grid-column: 1;
  }
  .pdf-actions {
    justify-content: stretch;
