    justify-content: center;
    text-align: center;
  }
  .pdf-preview-frame {
    height: 48vh;
  }
  .ministry-grid,
  .news-grid,
  .module-grid {
    grid-template-columns: 1fr;
  }
  .team-grid,
  .ranking-grid {
    grid-template-columns: 1fr;
  }
  .resource-links,
  .checklist-grid {
    grid-template-columns: 1fr;
  }
  .member-picker > div,
  .text-box-grid {
    grid-template-columns: 1fr;
  }
  .task-check-fields {
    grid-template-columns: 1fr;
  }
  .teen-card {
    grid-template-columns: 52px minmax(0, 1fr);
  }
  .teen-card > button {
    grid-column: 1 / -1;
    width: 100%;
  }
  .comment-form {
    grid-template-columns: 1fr;
  }
  .comment-form button {
    min-height: 36px;
  }
  .ranking-panel {
    padding: 18px;
  }
  .ranking-header {
    align-items: stretch;
    flex-direction: column;
  }
  .ranking-header button {
    width: 100%;
  }
  .ministry-card,
  .news-card,
  .module-card {
    padding: 17px;
  }
  .module-card {
    grid-template-columns: 42px 1fr;
  }
  .module-actions {
    grid-column: 1 / -1;
    grid-template-columns: 1fr 1fr;
  }
  .module-records > div {
    grid-template-columns: 1fr;
  }
  .detail-row {
    grid-template-columns: minmax(120px, 1fr) 36px;
  }
  .detail-row small {
    grid-column: 1 / -1;
    text-align: left;
  }
  .task-row {
    grid-template-columns: 20px 1fr;
  }
  .task-row small {
    grid-column: 2;
  }
  .mobile-menu-grid {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }
  .mobile-menu-card {
    min-height: 110px;
    grid-template-columns: 34px minmax(0, 1fr);
    padding: 13px;
  }
  .mobile-menu-open {
    min-height: 48px;
  }
  .site-footer {
    flex-direction: column;
    margin-top: 32px;
  }
  .future-contacts {
    justify-items: start;
  }
}

/* Upload nativo de imagens */
.native-image-upload {
  grid-column: 1 / -1;
  display: grid;
  gap: 8px;
  color: var(--pilot-muted);
  font-size: 11px;
  font-weight: 750;
}
.native-image-upload-picker {
  min-height: 116px;
  display: grid;
  grid-template-columns: 76px minmax(0,1fr);
  align-items: center;
  gap: 14px;
  padding: 14px;
  border: 1px dashed var(--pilot-line);
  border-radius: 16px;
  background: var(--pilot-surface-2);
  cursor: pointer;
  transition: border-color .18s ease,background .18s ease,transform .18s ease;
}
.native-image-upload-picker:hover,.native-image-upload-picker.dragging {
  border-color: var(--pilot-purple);
  background: color-mix(in srgb,var(--pilot-purple) 8%,var(--pilot-surface));
  transform: translateY(-1px);
}
.native-image-upload img,.native-image-upload-picker > b {
  width: 76px;
  height: 76px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: var(--pilot-surface);
  color: var(--pilot-purple);
  object-fit: cover;
  font-size: 25px;
}
.native-image-upload-picker > span{display:grid;gap:5px}
.native-image-upload.banner .native-image-upload-picker{grid-template-columns:1fr;align-items:stretch}
.native-image-upload.banner .native-image-upload-picker>img{
  width:100%;
  height:auto;
  aspect-ratio:16/7;
  border:1px solid var(--pilot-line);
  border-radius:13px;
  background:color-mix(in srgb,var(--pilot-surface) 84%,var(--pilot-surface-2));
  object-fit:contain;
  object-position:center;
}
.native-image-upload.banner .native-image-upload-picker>span{padding:2px}
.native-image-upload small{color:var(--pilot-muted);font-weight:600;line-height:1.45}
.native-image-upload-input{position:absolute;width:1px!important;height:1px!important;opacity:0;pointer-events:none}
.native-image-upload-actions{display:flex;flex-wrap:wrap;gap:8px}
.native-image-upload-actions > button{
  min-height:36px;
  padding:0 12px;
  border:1px solid var(--pilot-line);
  border-radius:10px;
  background:var(--pilot-surface);
  color:var(--pilot-text);
  font-weight:750;
  cursor:pointer;
}
.native-image-upload-actions > button:disabled{cursor:wait;opacity:.68}
.native-image-upload-message.error{color:#c64062}
.native-image-upload-message.success{color:#16825f}

/* Paletas prontas e testadas */
.community-palette-grid{
  grid-column:1/-1;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:10px;
}
.community-palette-grid>button{
  min-height:154px;
  display:grid;
  align-content:start;
  gap:7px;
  padding:11px;
  border:1px solid var(--pilot-line);
  border-radius:16px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  text-align:left;
  cursor:pointer;
}
.community-palette-grid>button.active{
  border-color:var(--pilot-purple);
  box-shadow:0 0 0 2px color-mix(in srgb,var(--pilot-purple) 18%,transparent);
}
.community-palette-grid>button>span{
  height:58px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  border-radius:11px;
}
.community-palette-grid i,.login-palette-picker i{width:18px;height:18px;border:2px solid rgba(255,255,255,.72);border-radius:50%}
.community-palette-grid small{color:var(--pilot-muted);font-size:9px;line-height:1.4}
.login-palette-picker{display:grid;gap:8px;color:var(--pilot-muted);font-size:11px;font-weight:750}
.login-palette-picker>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.login-palette-picker button{
  min-height:70px;
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:6px;
  padding:10px;
  border:1px solid var(--pilot-line);
  border-radius:13px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  cursor:pointer;
}
.login-palette-picker button.active{border-color:var(--pilot-purple);box-shadow:0 0 0 2px color-mix(in srgb,var(--pilot-purple) 16%,transparent)}
.login-palette-picker button strong{flex-basis:100%;font-size:10px}

@media(max-width:760px){
  .community-palette-grid,.login-palette-picker>div{grid-template-columns:1fr}
  .native-image-upload-picker{grid-template-columns:58px minmax(0,1fr);min-height:96px;padding:12px}
  .native-image-upload img,.native-image-upload-picker > b{width:58px;height:58px}
  .native-image-upload.banner .native-image-upload-picker{grid-template-columns:1fr;min-height:0}
  .native-image-upload.banner .native-image-upload-picker>img{width:100%;height:auto;aspect-ratio:16/9}
}

/* V4.5 — Editor visual integrado (substitui o cartão Smart UI) */
.visual-layout-editor {
  --layout-accent: #24c9c2;
  --layout-background: transparent;
  position: relative;
  margin: 0 0 28px;
  color: var(--pilot-text, #f4f7ff);
}

.visual-editor-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 54px;
  margin-bottom: 14px;
}

.visual-editor-topbar > div {
  display: grid;
  gap: 2px;
}

.visual-editor-topbar strong {
  font-size: 1.35rem;
}

.visual-editor-topbar small {
  color: var(--pilot-muted, #91a0ba);
}

.visual-editor-topbar button,
.visual-editor-panel button,
.visual-empty-layout {
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .28));
  border-radius: 11px;
  background: var(--pilot-panel-soft, rgba(255, 255, 255, .04));
  color: inherit;
  font: inherit;
  font-weight: 760;
  cursor: pointer;
}

.visual-editor-topbar button {
  min-height: 42px;
  padding: 9px 16px;
}

.visual-editor-topbar button:hover,
.visual-editor-topbar button.active,
.visual-editor-panel button:hover,
.visual-editor-panel button.active {
  border-color: var(--layout-accent);
  color: var(--layout-accent);
}

.visual-layout-canvas {
  display: grid;
  grid-template-columns: repeat(var(--layout-columns, 3), minmax(0, 1fr));
  gap: 14px;
  min-height: 190px;
  padding: 2px;
  border-radius: 22px;
  background: var(--layout-background);
  transition: background .18s ease, padding .18s ease;
}

.visual-layout-editor.columns-2 .visual-layout-canvas { --layout-columns: 2; }
.visual-layout-editor.columns-3 .visual-layout-canvas { --layout-columns: 3; }
.visual-layout-editor.columns-4 .visual-layout-canvas { --layout-columns: 4; }

.visual-layout-editor.is-editing .visual-layout-canvas {
  padding: 14px;
  outline: 1px dashed color-mix(in srgb, var(--layout-accent) 52%, transparent);
}

.visual-widget {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: 14px;
  min-width: 0;
  min-height: 174px;
  padding: 20px;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .24));
  border-radius: 18px;
  background: var(--pilot-card, rgba(7, 13, 26, .7));
  box-shadow: 0 13px 34px rgba(4, 9, 20, .08);
  transition: border-color .18s ease, transform .18s ease, box-shadow .18s ease;
}

.visual-layout-editor.cards-soft .visual-widget {
  border-color: transparent;
  background: color-mix(in srgb, var(--layout-accent) 7%, var(--pilot-card, #10182a));
}

.visual-layout-editor.cards-solid .visual-widget {
  background: var(--pilot-panel, #111a2d);
  box-shadow: 0 16px 42px rgba(4, 9, 20, .17);
}

.visual-layout-editor.is-editing .visual-widget {
  cursor: pointer;
  outline: 1px dashed color-mix(in srgb, var(--layout-accent) 48%, transparent);
}

.visual-layout-editor.is-editing .visual-widget:hover,
.visual-widget.selected {
  border-color: var(--layout-accent);
  outline: 2px solid color-mix(in srgb, var(--layout-accent) 38%, transparent);
  box-shadow: 0 16px 42px color-mix(in srgb, var(--layout-accent) 13%, transparent);
}

.visual-widget.size-p { grid-column: span 1; }
.visual-widget.size-m { grid-column: span 1; }
.visual-widget.size-g { grid-column: span 2; }

.visual-widget-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 12px;
  background: color-mix(in srgb, var(--layout-accent) 17%, transparent);
  color: var(--layout-accent);
  font-size: .72rem;
  font-weight: 900;
}

.visual-widget h3 {
  margin: 2px 0 7px;
  font-size: 1.05rem;
}

.visual-widget p {
  margin: 0;
  color: var(--pilot-muted, #91a0ba);
  line-height: 1.5;
}

.visual-widget-open {
  align-self: end;
  min-height: 38px;
  padding: 8px 11px;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .28));
  border-radius: 10px;
  background: var(--pilot-panel-soft, rgba(255, 255, 255, .04));
  color: inherit;
  font: inherit;
  font-weight: 760;
  cursor: pointer;
}

.visual-widget-open:hover {
  border-color: var(--layout-accent);
  color: var(--layout-accent);
}

.visual-widget-drag {
  position: absolute;
  top: 7px;
  right: 9px;
  color: var(--layout-accent);
  letter-spacing: -4px;
  opacity: .8;
}

.visual-layout-editor.density-compact .visual-layout-canvas { gap: 8px; }
.visual-layout-editor.density-compact .visual-widget {
  min-height: 142px;
  padding: 14px;
}

.visual-layout-editor.density-expanded .visual-layout-canvas { gap: 20px; }
.visual-layout-editor.density-expanded .visual-widget {
  min-height: 220px;
  padding: 26px;
}

.visual-empty-layout {
  grid-column: 1 / -1;
  min-height: 170px;
  border-style: dashed;
}

.visual-editor-backdrop {
  position: fixed;
  z-index: 119;
  inset: 0;
  border: 0;
  background: transparent;
  pointer-events: none;
  cursor: default;
}

.visual-editor-panel {
  position: fixed;
  z-index: 120;
  top: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  width: min(390px, 94vw);
  height: 100dvh;
  border-left: 1px solid var(--pilot-border, rgba(130, 150, 190, .25));
  background: var(--pilot-panel, #10182a);
  color: var(--pilot-text, #f4f7ff);
  box-shadow: -28px 0 70px rgba(2, 7, 15, .26);
  animation: visual-panel-in .2s ease both;
}

@keyframes visual-panel-in {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

.visual-editor-panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 72px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--pilot-border, rgba(130, 150, 190, .2));
}

.visual-editor-panel > header > div {
  display: grid;
  gap: 3px;
}

.visual-editor-panel > header small,
.visual-editor-section p {
  color: var(--pilot-muted, #91a0ba);
}

.visual-editor-panel > header button {
  width: 38px;
  height: 38px;
  font-size: 1.35rem;
}

.visual-editor-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-bottom: 1px solid var(--pilot-border, rgba(130, 150, 190, .2));
}

.visual-editor-tabs button {
  min-height: 48px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
}

.visual-editor-tabs button.active {
  border-bottom-color: var(--layout-accent);
}

.visual-editor-panel-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.visual-editor-section {
  padding: 0 0 18px;
  margin: 0 0 18px;
  border-bottom: 1px solid var(--pilot-border, rgba(130, 150, 190, .18));
}

.visual-editor-section h4 {
  margin: 0 0 7px;
}

.visual-editor-section p {
  margin: 0 0 12px;
  font-size: .82rem;
}

.visual-editor-section label {
  display: grid;
  gap: 6px;
  margin-top: 12px;
  color: var(--pilot-muted, #91a0ba);
  font-size: .8rem;
  font-weight: 760;
}

.visual-editor-section input:not([type="color"]),
.visual-editor-section textarea {
  width: 100%;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .28));
  border-radius: 10px;
  padding: 10px 11px;
  background: var(--pilot-input, rgba(255, 255, 255, .04));
  color: var(--pilot-text, #f4f7ff);
  font: inherit;
}

.visual-editor-section textarea {
  min-height: 82px;
  resize: vertical;
}

.visual-block-list,
.visual-add-blocks,
.visual-hidden-list {
  display: grid;
  gap: 8px;
}

.visual-block-list button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 44px;
  padding: 8px 10px;
  text-align: left;
}

.visual-size-picker,
.visual-color-row,
.visual-choice-grid,
.visual-editor-actions-grid,
.visual-editor-secondary-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.visual-size-picker {
  margin-top: 14px;
}

.visual-size-picker > span {
  width: 100%;
  color: var(--pilot-muted, #91a0ba);
  font-size: .8rem;
  font-weight: 760;
}

.visual-size-picker button,
.visual-choice-grid button {
  flex: 1;
  min-height: 40px;
  padding: 8px;
}

.visual-editor-actions-grid {
  margin-top: 12px;
}

.visual-editor-actions-grid button,
.visual-add-blocks button,
.visual-hidden-list button {
  flex: 1 1 44%;
  min-height: 40px;
  padding: 8px 10px;
}

.visual-color-row label {
  flex: 1;
}

.visual-color-row input[type="color"] {
  width: 100%;
  height: 44px;
  padding: 3px;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .28));
  border-radius: 10px;
  background: transparent;
}

.visual-choice-grid + h4 {
  margin-top: 18px;
}

.visual-editor-panel > footer {
  display: grid;
  gap: 9px;
  padding: 14px 16px max(14px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--pilot-border, rgba(130, 150, 190, .2));
  background: var(--pilot-panel, #10182a);
}

.visual-editor-panel > footer button {
  min-height: 42px;
  padding: 9px 11px;
}

.visual-editor-secondary-actions button {
  flex: 1;
  font-size: .76rem;
}

.visual-publish-default {
  border-color: color-mix(in srgb, var(--layout-accent) 52%, transparent) !important;
}

.visual-save-layout {
  min-height: 48px !important;
  border-color: var(--layout-accent) !important;
  background: var(--layout-accent) !important;
  color: #051918 !important;
}

.visual-editor-panel button:disabled {
  opacity: .45;
  cursor: not-allowed;
}

@media (max-width: 1150px) {
  .visual-layout-editor.columns-4 .visual-layout-canvas {
    --layout-columns: 2;
  }
  .visual-widget.size-g { grid-column: span 2; }
}

@media (max-width: 760px) {
  .visual-editor-topbar {
    align-items: flex-start;
  }
  .visual-editor-topbar button {
    min-width: 136px;
  }
  .visual-layout-canvas,
  .visual-layout-editor.columns-2 .visual-layout-canvas,
  .visual-layout-editor.columns-3 .visual-layout-canvas,
  .visual-layout-editor.columns-4 .visual-layout-canvas {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .visual-widget,
  .visual-widget.size-p,
  .visual-widget.size-m,
  .visual-widget.size-g {
    width: 100%;
    min-height: 164px;
    grid-template-columns: auto minmax(0, 1fr);
  }
  .visual-widget-open {
    grid-column: 2;
    justify-self: end;
  }
  .visual-editor-panel {
    top: auto;
    right: 0;
    bottom: 0;
    left: 0;
    width: 100%;
    height: min(78dvh, 720px);
    border-top: 1px solid var(--pilot-border, rgba(130, 150, 190, .25));
    border-left: 0;
    border-radius: 24px 24px 0 0;
    animation-name: visual-drawer-in;
  }
  .visual-editor-backdrop {
    background: rgba(2, 7, 15, .48);
    pointer-events: auto;
  }
  @keyframes visual-drawer-in {
    from { transform: translateY(100%); }
    to { transform: translateY(0); }
  }
  .visual-editor-panel > header {
    min-height: 62px;
  }
  .visual-editor-panel > header::before {
    content: "";
    position: absolute;
    top: 7px;
    left: 50%;
    width: 42px;
    height: 4px;
    border-radius: 99px;
    background: var(--pilot-muted, #91a0ba);
    transform: translateX(-50%);
    opacity: .55;
  }
  .visual-editor-actions-grid button,
  .visual-add-blocks button,
  .visual-hidden-list button {
    min-height: 44px;
  }
}

@media (max-width: 410px) {
  .metrics-grid {
    grid-template-columns: 1fr;
  }
  .metric-card {
    min-height: 94px;
    align-items: center;
  }
  .bar-chart {
    gap: 7px;
    padding-inline: 0;
  }
  .period-tabs button {
    padding-inline: 7px;
  }
}

/* Preferência individual de tema e prévia administrativa */
.preview-toolbar {
  position: relative;
  z-index: 10;
  width: max-content;
  max-width: 100%;
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 22px auto;
  padding: 9px 10px 9px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 16px 44px rgba(17, 38, 58, 0.16);
  backdrop-filter: blur(12px);
}
.preview-toolbar.active {
  border-color: #e7b554;
  box-shadow: 0 16px 44px rgba(157, 105, 12, 0.18);
}
.preview-toolbar span {
  color: var(--navy);
  font-size: 9px;
  font-weight: 800;
}
.preview-toolbar select,
.preview-toolbar button {
  min-height: 34px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--canvas);
  color: var(--ink);
  padding: 0 10px;
  font-size: 9px;
  font-weight: 700;
  cursor: pointer;
}
.preview-toolbar button {
  border-color: #dd9e2f;
  background: #fff7e6;
  color: #80520b;
}
.theme-toggle {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 9px !important;
  background: rgba(255, 255, 255, 0.08) !important;
  color: #dbe7ef !important;
  font-size: 15px;
}
.theme-toggle:hover {
  background: rgba(255, 255, 255, 0.16) !important;
}
.profile-card {
  grid-template-columns: 38px minmax(0, 1fr) auto auto;
}

/* Fotos nas notícias */
.news-image {
  width: calc(100% + 42px);
  height: 180px;
  display: block;
  object-fit: cover;
  margin: -1px -21px 18px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

/* Rotinas dos Cultos */
.cult-module {
  display: grid;
  gap: 22px;
}
.page-heading,
.section-heading,
.cult-routine-top,
.responsive-heading,
.entry-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}
.page-heading h1 {
  margin: 0 0 8px;
  color: var(--navy);
  font-size: clamp(27px, 3vw, 36px);
  letter-spacing: -0.045em;
}
.page-heading p,
.section-heading p,
.panel-heading p,
.cult-routine-top p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}
.section-heading h2,
.panel-heading h2,
.cult-routine-card h2 {
  margin: 0 0 5px;
  color: var(--navy);
  font-size: 18px;
  letter-spacing: -0.025em;
}
.compact-metrics {
  margin: 0;
  grid-template-columns: repeat(5, minmax(0, 1fr));
}
.cult-chart-panel {
  min-width: 0;
}
.segmented-control {
  display: inline-flex;
  gap: 3px;
  padding: 4px;
  border-radius: 11px;
  background: var(--canvas);
}
.segmented-control button {
  min-height: 32px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  font-size: 9px;
  font-weight: 750;
  cursor: pointer;
}
.segmented-control button.active {
  background: var(--white);
  color: var(--teal);
  box-shadow: 0 4px 13px rgba(23, 50, 77, 0.08);
}
.cult-bar-chart {
  min-height: 230px;
  display: flex;
  align-items: flex-end;
  gap: 10px;
  overflow-x: auto;
  padding: 26px 6px 4px;
}
.cult-bar-column {
  min-width: 42px;
  flex: 1 0 42px;
  display: grid;
  grid-template-rows: 18px 160px 23px;
  align-items: end;
  justify-items: center;
  gap: 5px;
}
.cult-bar-column strong {
  color: var(--navy);
  font-size: 9px;
}
.cult-bar-column small {
  max-width: 78px;
  overflow: hidden;
  color: var(--muted);
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.cult-bar-track {
  width: min(30px, 70%);
  height: 160px;
  display: flex;
  align-items: flex-end;
  border-radius: 8px;
  background: color-mix(in srgb, var(--teal) 8%, transparent);
  overflow: hidden;
}
.cult-bar-track span {
  width: 100%;
  display: block;
  border-radius: 8px 8px 3px 3px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--teal) 72%, white),
    var(--teal)
  );
  transition: height 0.3s ease;
}
.cult-routine-list {
  display: grid;
  gap: 16px;
}
.cult-routine-card {
  display: grid;
  gap: 17px;
}
.card-kicker {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.team-color-dot {
  width: 9px;
  height: 9px;
  flex: 0 0 auto;
  border-radius: 50%;
}
.card-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 7px;
}
.primary-button.small,
.ghost-button.small,
.danger-button.small {
  min-height: 34px;
  padding: 0 11px;
  font-size: 8px;
}
.ghost-button {
  min-height: 40px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--white);
  color: var(--navy);
  padding: 0 14px;
  font-weight: 750;
  cursor: pointer;
}
.status-pill.aberta,
.status-pill.encerrada {
  width: max-content;
  padding: 6px 9px;
}
.status-pill.aberta {
  background: #def3e9;
  color: #20704e;
}
.status-pill.encerrada {
  background: #edf0f2;
  color: #647481;
}
.routine-notes {
  margin: 0;
  padding: 12px 14px;
  border-radius: 11px;
  background: var(--canvas);
  color: var(--muted);
  font-size: 10px;
  line-height: 1.6;
}
.entry-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
}
.entry-card {
  min-width: 0;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--canvas);
}
.entry-card-header strong,
.entry-card-header small {
  display: block;
}
.entry-card-header strong {
  color: var(--navy);
  font-size: 13px;
}
.entry-card-header small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 8px;
}
.entry-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}
.entry-stats span {
  padding: 6px 8px;
  border-radius: 8px;
  background: var(--white);
  color: var(--muted);
  font-size: 8px;
}
.entry-stats b {
  color: var(--teal);
}
.entry-card > p {
  margin: 12px 0 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.55;
}
.empty-inline {
  padding: 14px;
  border: 1px dashed var(--line);
  border-radius: 11px;
  color: var(--muted);
  font-size: 9px;
  text-align: center;
}
.danger-text {
  color: #b94a55 !important;
}
.modal-overlay {
  position: fixed;
  z-index: 100;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(11, 27, 41, 0.58);
  backdrop-filter: blur(5px);
}
.modal-card {
  width: min(760px, 100%);
  max-height: min(88vh, 850px);
  overflow: auto;
  padding: 25px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--white);
  color: var(--ink);
  box-shadow: 0 32px 90px rgba(8, 24, 38, 0.26);
}
.modal-card .modal-header {
  margin-bottom: 20px;
}
.modal-card .modal-header h2 {
  margin: 0;
  color: var(--navy);
}
.modal-card .modal-header p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 9px;
}
.close-button {
  width: 36px;
  height: 36px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--canvas);
  color: var(--muted);
  cursor: pointer;
}
.full-field {
  grid-column: 1 / -1;
}
.field small {
  display: block;
  margin-top: 5px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 500;
}
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}

.custom-fields-builder {
  display: grid;
  gap: 13px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: color-mix(in srgb, var(--canvas) 68%, var(--white));
}
.custom-fields-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.custom-fields-heading > div {
  min-width: 0;
  display: grid;
  gap: 4px;
}
.custom-fields-heading > div > span {
  color: var(--navy);
  font-size: 10px;
  font-weight: 800;
}
.custom-fields-heading small {
  margin: 0;
}
.custom-field-list {
  display: grid;
  gap: 9px;
}
.custom-field-row {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(150px, 0.8fr) auto;
  align-items: end;
  gap: 9px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--white);
}
.custom-field-remove {
  margin-bottom: 1px;
}
.custom-fields-empty {
  padding: 15px;
  border: 1px dashed var(--line);
  border-radius: 11px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.55;
  text-align: center;
}

/* Modo escuro: preferência salva por usuário */
.app-shell.dark-mode {
  color-scheme: dark;
  --navy: #eef5f9;
  --navy-2: #d6e4ec;
  --teal: color-mix(in srgb, var(--brand-accent, #17877f) 72%, #73e3d8);
  --ink: #e9f1f6;
  --muted: #a9bac6;
  --line: #2a3b48;
  --canvas: #09131b;
  --white: #111e28;
  --teal-soft: #173b39;
  --shadow: 0 16px 46px rgba(0, 0, 0, 0.24);
  min-height: 100vh;
  background:
    radial-gradient(
      circle at 92% 0,
      color-mix(in srgb, var(--teal) 9%, transparent),
      transparent 30rem
    ),
    var(--canvas);
  color: var(--ink);
}
.dark-mode .sidebar {
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--brand-primary, #17324d) 58%, #071019),
    color-mix(in srgb, var(--brand-secondary, #21486d) 35%, #050c12)
  );
  box-shadow: 18px 0 50px rgba(0, 0, 0, 0.16);
}
.dark-mode .main-content,
.dark-mode .mobile-nav {
  background: transparent;
}
.dark-mode .panel,
.dark-mode .metric-card,
.dark-mode .icon-button,
.dark-mode .news-strip > button,
.dark-mode .visitor-list,
.dark-mode .visitor-row,
.dark-mode .person-card,
.dark-mode .followup-card,
.dark-mode .user-card,
.dark-mode .ministry-card,
.dark-mode .module-card,
.dark-mode .news-card,
.dark-mode .text-box-card,
.dark-mode .ranking-panel,
.dark-mode .modal,
.dark-mode .modal-card,
.dark-mode .detail-sheet,
.dark-mode .pdf-editor,
.dark-mode .mobile-menu-card,
.dark-mode .preview-toolbar {
  border-color: var(--line);
  background: var(--white);
  color: var(--ink);
  box-shadow: 0 15px 42px rgba(0, 0, 0, 0.2);
}
.dark-mode .news-card.type-aviso,
.dark-mode .news-card.type-noticia,
