.dark-mode h1,
.dark-mode h2,
.dark-mode h3,
.dark-mode .topbar h1,
.dark-mode .page-heading h1,
.dark-mode .section-heading h2,
.dark-mode .panel-heading h2,
.dark-mode .cult-routine-card h2,
.dark-mode .entry-card-header strong,
.dark-mode .metric-card strong,
.dark-mode .ministry-card h2,
.dark-mode .ministry-card h3,
.dark-mode .module-card h2,
.dark-mode .news-card h2,
.dark-mode .preview-toolbar span,
.dark-mode .chart-summary strong,
.dark-mode .donut strong,
.dark-mode .legend strong,
.dark-mode .section-title h2,
.dark-mode .visitor-name strong,
.dark-mode .action-item strong,
.dark-mode td strong,
.dark-mode .person-card strong,
.dark-mode .user-card strong,
.dark-mode .followup-card strong,
