}
.dark-mode input,
.dark-mode select,
.dark-mode textarea,
.dark-mode .segmented-control,
.dark-mode .entry-card,
.dark-mode .routine-notes,
.dark-mode .close-button,
.dark-mode .preview-toolbar select,
.dark-mode .list-toolbar input,
.dark-mode .readonly-title,
