}
.dark-mode .metric-icon.amber {
  background: #3a2d18;
  color: #f0bd67;
}
.dark-mode .metric-icon.violet {
  background: #29213d;
  color: #bda3ef;
}
.dark-mode .metric-card small,
.dark-mode .metric-card span,
.dark-mode .bar-value,
.dark-mode .bar-column small,
.dark-mode .cult-bar-column small,
.dark-mode .site-footer,
.dark-mode .preview-toolbar select {
