}
.dark-mode .empty-insight strong,
.dark-mode .bar-column strong,
.dark-mode .cult-bar-column strong {
  color: var(--ink);
}
.dark-mode .content-actions,
.dark-mode .ministry-card > header,
.dark-mode .ministry-card section + section,
.dark-mode .site-footer,
.dark-mode .mobile-nav {
  border-color: var(--line);
}
.dark-mode .mobile-nav {
  background: #0f1c25;
  box-shadow: 0 -8px 25px rgba(0, 0, 0, 0.2);
}

@media (max-width: 760px) {
  .preview-toolbar {
    position: relative;
    inset: auto;
    width: 100%;
    margin: 0 0 18px;
    justify-content: center;
    padding: 8px;
  }
  .preview-toolbar span {
    display: none;
  }
  .preview-toolbar select {
    min-width: 0;
    flex: 1;
  }
  .compact-metrics {
    grid-template-columns: 1fr 1fr;
  }
  .page-heading,
  .section-heading,
  .cult-routine-top,
  .responsive-heading,
  .entry-card-header {
    align-items: stretch;
