  }
  .page-heading .primary-button,
  .cult-routine-top .card-actions,
  .segmented-control {
    width: 100%;
  }
  .segmented-control button {
    flex: 1;
  }
  .card-actions {
    justify-content: flex-start;
  }
  .settings-reset-card,
  .custom-fields-heading {
    align-items: stretch;
    flex-direction: column;
  }
  .settings-reset-card .ghost-button,
  .custom-fields-heading .ghost-button {
    width: 100%;
  }
  .custom-field-row {
    grid-template-columns: 1fr;
  }
