}
.app-shell .news-grid .news-card:first-child {
  grid-column: span 2;
  min-height: 260px;
  padding: 28px;
}
.app-shell .news-grid .news-card:first-child .news-image {
  max-height: 360px;
  object-fit: cover;
}
.page-heading-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
}
.selection-column {
  width: 44px;
  text-align: center;
}
.selection-column input {
