}
.app-shell .ministry-card h3,
.app-shell .ranking-list h3,
.app-shell .task-check-card > header strong,
.app-shell .user-card strong,
.app-shell .person-card strong {
  font-size: 14px;
}
.app-shell .ministry-card small,
.app-shell .task-row strong,
.app-shell .task-row small,
.app-shell .people-chips span,
.app-shell .user-card small,
.app-shell .person-card small,
.app-shell .role-pill,
.app-shell .church-title {
  font-size: 12px;
}
.app-shell .sidebar nav button,
.app-shell .sidebar nav .inline-name-trigger {
