}
.app-shell .nav-group summary {
  font-size: 11px;
}
.app-shell .toast {
  font-size: 14px;
}

.account-toolbar {
  position: relative;
  z-index: 28;
  min-height: 44px;
  margin: 0 0 20px;
}
.account-toolbar-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}
.account-action {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.88);
  color: var(--navy);
  text-decoration: none;
  font-size: 13px !important;
  font-weight: 750;
  cursor: pointer;
  box-shadow: 0 7px 22px rgba(23, 50, 77, 0.05);
}
.account-action > span:first-child {
  font-size: 18px;
}
.account-action:hover,
.account-action.active {
  border-color: color-mix(in srgb, var(--teal) 55%, var(--line));
  background: color-mix(in srgb, var(--teal) 7%, white);
}
.account-action b {
  min-width: 21px;
  height: 21px;
  display: inline-grid;
  place-items: center;
  padding: 0 5px;
  border-radius: 999px;
  background: #d94f55;
  color: #fff;
  font-size: 10px;
}
.logout-action {
  color: #9f3e45;
}
.notification-center {
  position: absolute;
  top: 49px;
  right: 0;
  width: min(440px, calc(100vw - 32px));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 26px 70px rgba(19, 42, 61, 0.2);
}
.notification-center > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 17px 18px;
  border-bottom: 1px solid var(--line);
}
.notification-center > header div {
  display: grid;
  gap: 3px;
}
.notification-center > header strong {
  color: var(--navy);
  font-size: 15px;
}
.notification-center > header small {
  color: var(--muted);
  font-size: 12px;
}
.notification-center > header button {
  border: 0;
  background: none;
  color: var(--teal);
  font-size: 12px !important;
  font-weight: 750;
  cursor: pointer;
}
.notification-list {
  max-height: 430px;
  overflow-y: auto;
  padding: 7px;
}
.notification-item {
  position: relative;
  width: 100%;
  display: grid;
  grid-template-columns: 39px minmax(0, 1fr);
  gap: 11px;
  padding: 12px;
  border: 0;
  border-radius: 13px;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.notification-item + .notification-item {
  margin-top: 3px;
}
.notification-item.unread {
  background: #f0f8f7;
}
.notification-item.unread::after {
  content: "";
  position: absolute;
  top: 15px;
  right: 12px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--teal);
}
.notification-item.type-importante.unread {
  background: #fff4f2;
}
.notification-item.type-importante.unread::after {
  background: #d85151;
}
.notification-symbol {
  width: 39px;
  height: 39px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #e4f3f1;
  color: var(--teal);
  font-size: 16px;
}
.notification-item > span:last-child {
  min-width: 0;
  display: grid;
  gap: 4px;
  padding-right: 10px;
}
.notification-item strong {
  color: var(--navy);
  font-size: 13px;
}
.notification-item small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}
.notification-item time {
  color: #8d9ba5;
  font-size: 10px;
}
.notification-empty {
  padding: 35px 18px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
}
.profile-logout {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 7px;
  border-radius: 9px;
  font-size: 11px;
  font-weight: 750;
}
.profile-logout:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}
.profile-preferences-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #f7fafb;
}
.profile-preferences-card > div {
  display: grid;
  gap: 4px;
}
.profile-preferences-card strong {
  color: var(--navy);
  font-size: 14px;
}
.profile-preferences-card small {
  color: var(--muted);
  font-size: 12px;
}
.profile-modal-logout {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  margin-right: auto;
  color: #a44249;
  font-size: 13px;
  font-weight: 750;
  text-decoration: none;
}

.user-directory-toolbar {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(170px, 0.45fr) minmax(190px, 0.5fr) auto;
  align-items: end;
  gap: 12px;
  margin-bottom: 17px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fff;
  box-shadow: var(--shadow);
}
.user-directory-toolbar > label {
  min-width: 0;
  display: grid;
  gap: 6px;
}
.user-directory-toolbar > label > span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
}
.user-directory-toolbar input,
.user-directory-toolbar select {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: #f8fafb;
  color: var(--ink);
  padding: 0 12px;
}
.user-search-field {
  position: relative;
}
.user-search-field > span {
  position: absolute;
  z-index: 1;
  left: 13px;
  bottom: 11px;
  color: var(--teal) !important;
  font-size: 17px !important;
}
.user-search-field input {
  padding-left: 39px;
}
.directory-count {
  min-height: 42px;
  display: grid;
  place-items: center;
  padding: 0 12px;
  border-radius: 11px;
  background: #edf6f5;
  color: var(--teal);
  font-size: 12px;
  white-space: nowrap;
}

/* Organização ajustável por aba */
.layout-toolbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 7px;
  margin: 0 0 18px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: color-mix(in srgb, var(--surface) 92%, var(--teal-soft));
}
.layout-toolbar span {
  margin-right: auto;
  padding: 0 7px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
}
.layout-toolbar button {
  min-height: 34px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  color: var(--navy);
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
}
.layout-toolbar button.active {
  border-color: var(--teal);
  background: var(--teal);
  color: white;
}
.tab-layout-compacto :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid) {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
.tab-layout-compacto :is(.panel, .news-card, .ministry-card, .team-card, .cell-card) {
  padding: 15px;
  border-radius: 14px;
}
.tab-layout-medio :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid) {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}
.tab-layout-grande :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid) {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}
.tab-layout-compacto .mobile-menu-grid,
.tab-layout-medio .mobile-menu-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.tab-layout-grande .mobile-menu-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.tab-layout-compacto .news-grid .news-card:first-child,
.tab-layout-medio .news-grid .news-card:first-child,
.tab-layout-grande .news-grid .news-card:first-child {
  grid-column: auto;
}

/* Editor de hierarquias */
.hierarchy-editor {
  display: grid;
  gap: 14px;
  margin-top: 8px;
}
.hierarchy-editor-heading,
.hierarchy-card-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.hierarchy-editor-heading small {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
}
.hierarchy-card {
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--surface);
}
.hierarchy-card-title > input {
  flex: 1 1 220px;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 0 12px;
  color: var(--navy);
  font-weight: 800;
}
.hierarchy-card-title label {
  display: flex;
  align-items: center;
  gap: 8px;
}
.hierarchy-card-title input[type="color"] {
  width: 48px;
  height: 38px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 9px;
}
.hierarchy-permissions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 14px;
}
.hierarchy-permissions label {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--teal-soft) 45%, var(--surface));
  color: var(--text);
  font-size: 12px;
}
.hierarchy-permissions input {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  accent-color: var(--teal);
}
.menu-order-row .delete-tab { color: #a53f3f; }
.menu-order-row .restore-tab { color: var(--teal); }

/* Menu do usuário: nomes e títulos não ficam mais cortados. */
.profile-card {
  grid-template-columns: 38px minmax(0, 1fr) auto;
}
.profile-card > span {
  min-width: 0;
}
.profile-card strong,
.profile-card small {
  max-width: none;
  overflow: visible;
  white-space: normal;
  text-overflow: clip;
  overflow-wrap: anywhere;
  line-height: 1.3;
}
.profile-card .church-title {
  width: fit-content;
  max-width: 100%;
  white-space: normal;
}
.profile-card .profile-logout {
  grid-column: 2 / -1;
  justify-self: start;
  padding-left: 0;
}
.mobile-menu-label,
.mobile-menu-card .inline-name-trigger > span:first-child {
  overflow: visible;
  white-space: normal;
  text-overflow: clip;
  overflow-wrap: anywhere;
  line-height: 1.35;
}

@media (max-width: 1180px) {
  .tab-layout-compacto :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid),
  .tab-layout-medio :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid) {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .hierarchy-permissions { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .tab-layout-compacto .mobile-menu-grid,
  .tab-layout-medio .mobile-menu-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 700px) {
  .layout-toolbar { justify-content: stretch; }
  .layout-toolbar span { flex: 1 0 100%; }
  .layout-toolbar button { flex: 1 1 110px; }
  .tab-layout-compacto :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid),
  .tab-layout-medio :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid),
  .tab-layout-grande :is(.metrics-grid, .news-grid, .module-grid, .ministry-grid, .team-grid, .cell-grid, .report-grid, .teens-grid, .entry-grid, .text-box-grid, .custom-content-grid) {
    grid-template-columns: 1fr;
  }
  .hierarchy-editor-heading,
  .hierarchy-card-title,
  .menu-order-row {
    align-items: stretch;
    flex-direction: column;
  }
  .hierarchy-permissions { grid-template-columns: 1fr; }
  .tab-layout-compacto .mobile-menu-grid,
  .tab-layout-medio .mobile-menu-grid,
  .tab-layout-grande .mobile-menu-grid { grid-template-columns: 1fr; }
  .menu-order-row > div { flex-wrap: wrap; }
}

.cell-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 17px;
}
.cell-grid > .empty-state {
  grid-column: 1 / -1;
}
.cell-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 19px;
  background: #fff;
  box-shadow: var(--shadow);
}
.cell-card-header {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 20px;
  border-bottom: 1px solid #e9eff1;
  background: linear-gradient(135deg, #f5fbfa, #fff);
}
.cell-icon {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: var(--teal);
  color: #fff;
  font-size: 18px;
}
.cell-card-header p {
  margin: 0 0 3px;
  color: var(--teal);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.12em;
}
.cell-card-header h2 {
  margin: 0;
  color: var(--navy);
  font-size: 20px;
}
.cell-member-count {
  padding: 6px 9px;
  border-radius: 999px;
  background: #eaf3f5;
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
}
.cell-owner,
.cell-members,
.cell-notes {
  margin: 0 20px;
}
.cell-owner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 17px 0;
  border-bottom: 1px solid #edf1f3;
}
.cell-owner span,
.cell-members h3 {
  color: var(--muted);
  font-size: 12px;
}
.cell-owner strong {
  color: var(--navy);
  font-size: 14px;
}
.cell-members {
  padding: 17px 0;
}
.cell-members h3 {
  margin: 0 0 10px;
}
.cell-members small {
  color: var(--muted);
  font-size: 13px;
}
.cell-notes {
  padding: 12px;
  border-radius: 11px;
  background: #f6f8f9;
  color: var(--muted);
  font-size: 13px;
}
.cell-card-footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 16px;
  padding: 13px 20px;
  border-top: 1px solid var(--line);
  background: #fafcfc;
}
.cell-action-button,
.cell-delete-button {
  min-height: 35px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  padding: 0 10px;
  font-size: 12px !important;
  font-weight: 750;
  cursor: pointer;
}
.cell-action-button {
  color: var(--teal);
}
.cell-action-button:hover {
  background: #e8f5f3;
}
.cell-delete-button {
  color: #ae494f;
}
.cell-delete-button:hover {
  background: #fff0f0;
}

.custom-area-shell {
  display: grid;
  gap: 14px;
}
.custom-area-tabs {
  display: flex;
  gap: 9px;
  overflow-x: auto;
  padding: 4px 2px 10px;
  scrollbar-width: thin;
}
.custom-area-tabs button {
  --module-color: var(--teal);
  min-width: max-content;
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  color: var(--navy);
  cursor: pointer;
}
.custom-area-tabs button span {
  color: var(--module-color);
  font-size: 17px;
}
.custom-area-tabs button strong {
  font-size: 13px;
}
.custom-area-tabs button.active {
  border-color: var(--module-color);
  box-shadow: inset 0 -3px 0 var(--module-color), var(--shadow);
}
.custom-area-workspace {
  --module-color: var(--teal);
  overflow: hidden;
