  background: linear-gradient(135deg, color-mix(in srgb, var(--module-color) 8%, white), white 50%);
}
.custom-area-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: var(--module-color);
  color: #fff;
  font-size: 22px;
}
.custom-area-header h2,
.custom-area-title-input {
  margin: 0 0 5px;
  color: var(--navy);
  font-size: 24px !important;
  font-weight: 800;
  letter-spacing: -0.03em;
}
.custom-area-title-input {
  width: 100%;
  border: 0;
  border-bottom: 1px dashed color-mix(in srgb, var(--module-color) 55%, var(--line));
  background: transparent;
  padding: 2px 0;
}
.custom-area-header p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}
.custom-area-admin-actions {
  display: flex;
  gap: 8px;
