.custom-block-title {
  grid-column: 1 / -1;
  margin: 10px 0 0;
  color: var(--navy);
  font-size: 26px;
  letter-spacing: -0.035em;
}
.custom-content-block {
  min-width: 0;
  margin: 0;
  padding: 19px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fafcfc;
}
.custom-content-block h3 {
  margin: 0 0 10px;
  color: var(--navy);
  font-size: 17px;
}
.custom-text-block p {
  margin: 0;
  color: #506674;
  font-size: 14px;
  line-height: 1.75;
  white-space: pre-wrap;
}
.custom-image-block {
  padding: 0;
  overflow: hidden;
}
.custom-image-block img,
.custom-image-placeholder {
  width: 100%;
  height: 260px;
  display: grid;
  place-items: center;
  object-fit: cover;
  background: #e8eef0;
