  font-size: 13px;
}
.custom-image-block figcaption {
  padding: 13px 16px;
  color: var(--navy);
  font-size: 13px;
  font-weight: 700;
}
.custom-chart-list {
  display: grid;
  gap: 11px;
}
.custom-chart-list > div {
  display: grid;
  grid-template-columns: minmax(80px, 0.55fr) minmax(100px, 1fr) 42px;
  align-items: center;
  gap: 9px;
}
.custom-chart-list span,
.custom-chart-list strong {
  font-size: 12px;
}
.custom-chart-list span {
  overflow: hidden;
  color: var(--muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.custom-chart-list > div > div {
  height: 11px;
  overflow: hidden;
  border-radius: 999px;
  background: #e6edef;
}
.custom-chart-list i {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: var(--module-color);
}
.custom-chart-list strong {
  color: var(--navy);
  text-align: right;
}
.custom-checklist-block > header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.custom-checklist-block > header span {
  padding: 5px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--module-color) 12%, white);
  color: var(--module-color);
  font-size: 11px;
  font-weight: 800;
}
.custom-checklist-block > div {
  display: grid;
  gap: 7px;
}
.custom-checklist-block label {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px;
  border-radius: 10px;
  background: #fff;
  color: var(--ink);
  font-size: 13px;
}
.custom-checklist-block label.done span {
  color: var(--muted);
  text-decoration: line-through;
}
.custom-checklist-block input {
  width: 18px;
  height: 18px;
  accent-color: var(--module-color);
}
.custom-area-empty-content {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  padding: 24px;
  border: 1px dashed color-mix(in srgb, var(--module-color) 45%, var(--line));
  border-radius: 16px;
  background: color-mix(in srgb, var(--module-color) 4%, white);
}
.custom-area-empty-content > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--module-color);
  color: #fff;
}
.custom-area-empty-content strong {
  color: var(--navy);
  font-size: 14px;
}
.custom-area-empty-content p {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 13px;
}
.custom-records-section {
  margin: 0 24px 24px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #f7fafb;
}
.custom-records-section > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 13px;
}
.custom-records-section h3 {
  margin: 0 0 4px;
  color: var(--navy);
  font-size: 17px;
}
.custom-records-section p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}
.custom-area-onboarding {
  display: grid;
  justify-items: center;
  padding: 58px 24px;
  border: 1px dashed var(--line);
  border-radius: 21px;
  background: #fff;
  text-align: center;
}
.custom-area-onboarding > span {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 17px;
  background: var(--teal-soft);
  color: var(--teal);
  font-size: 25px;
}
.custom-area-onboarding h2 {
  margin: 17px 0 7px;
  color: var(--navy);
  font-size: 23px;
}
.custom-area-onboarding p {
  max-width: 570px;
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 14px;
}
.custom-block-builder {
  display: grid;
  gap: 13px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: #f7fafb;
}
.custom-block-builder > header {
  display: grid;
  gap: 12px;
}
.custom-block-builder > header > div:first-child {
  display: grid;
  gap: 4px;
}
.custom-block-builder > header strong {
  color: var(--navy);
  font-size: 14px;
}
.custom-block-builder > header small {
  color: var(--muted);
  font-size: 12px;
}
.block-toolbox {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.block-toolbox button {
  min-height: 34px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #fff;
  color: var(--teal);
  padding: 0 10px;
  font-size: 12px !important;
  font-weight: 750;
  cursor: pointer;
}
.block-editor-list {
  display: grid;
  gap: 10px;
}
.block-editor-card {
  display: grid;
  gap: 11px;
  padding: 13px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: 12px;
  background: #fff;
}
.block-editor-card > header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}
.block-editor-card > header strong {
  color: var(--navy);
  font-size: 13px;
}
.block-editor-card > header div {
  display: flex;
  gap: 5px;
}
.block-editor-card > header button {
  min-height: 29px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f8fafb;
  color: var(--muted);
  padding: 0 8px;
  font-size: 11px !important;
  cursor: pointer;
}
.block-editor-card > header button:disabled {
  opacity: 0.35;
}
.block-editor-card > header .remove-block {
  color: #a74349;
}
.block-editor-card label {
  display: grid;
  gap: 6px;
}
.block-editor-card input,
.block-editor-card textarea {
  width: 100%;
}
.block-builder-empty {
  margin: 0;
  padding: 18px;
  border: 1px dashed var(--line);
  border-radius: 11px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
}

/* Superfícies que antes ficavam claras demais no modo escuro, especialmente Diaconia */
.dark-mode .account-action,
.dark-mode .notification-center,
.dark-mode .user-directory-toolbar,
.dark-mode .cell-card,
.dark-mode .custom-area-tabs button,
.dark-mode .custom-area-workspace,
.dark-mode .custom-content-block,
.dark-mode .custom-records-section,
.dark-mode .custom-area-onboarding,
.dark-mode .custom-block-builder,
.dark-mode .block-editor-card,
.dark-mode .profile-preferences-card,
.dark-mode .team-card,
.dark-mode .service-card,
.dark-mode .resource-link-card,
.dark-mode .checklist-item,
.dark-mode .checklist-complete,
.dark-mode .ranking-list,
.dark-mode .task-check-card,
.dark-mode .member-picker,
.dark-mode .member-picker > div > label {
  border-color: var(--line);
  background: var(--white);
  color: var(--ink);
  box-shadow: 0 15px 42px rgba(0, 0, 0, 0.16);
}
.dark-mode .account-action:hover,
.dark-mode .account-action.active,
.dark-mode .notification-item.unread,
.dark-mode .cell-card-header,
.dark-mode .cell-card-footer,
.dark-mode .custom-area-header,
.dark-mode .custom-area-empty-content,
.dark-mode .custom-checklist-block label,
.dark-mode .block-toolbox button,
.dark-mode .block-editor-card > header button,
.dark-mode .cell-notes,
.dark-mode .user-directory-toolbar input,
.dark-mode .user-directory-toolbar select {
  border-color: var(--line);
  background: #172630;
  color: var(--ink);
}
.dark-mode .notification-item.type-importante.unread {
  background: #382326;
}
.dark-mode .notification-center > header,
.dark-mode .cell-card-header,
.dark-mode .cell-owner,
.dark-mode .cell-card-footer,
.dark-mode .custom-area-header,
.dark-mode .custom-records-section {
  border-color: var(--line);
}
.dark-mode .notification-center strong,
.dark-mode .notification-item strong,
.dark-mode .cell-card h2,
.dark-mode .cell-owner strong,
.dark-mode .custom-area-header h2,
.dark-mode .custom-area-title-input,
.dark-mode .custom-block-title,
.dark-mode .custom-content-block h3,
.dark-mode .custom-image-block figcaption,
.dark-mode .custom-chart-list strong,
.dark-mode .custom-records-section h3,
.dark-mode .custom-area-onboarding h2,
.dark-mode .custom-block-builder strong,
.dark-mode .block-editor-card strong,
.dark-mode .profile-preferences-card strong,
.dark-mode .team-card h3,
.dark-mode .ranking-list h3,
.dark-mode .ranking-row > div strong,
.dark-mode .ranking-row > b,
.dark-mode .resource-link-card,
.dark-mode .checklist-item {
  color: var(--ink);
}
.dark-mode .news-card > p,
.dark-mode .news-card details p,
.dark-mode .custom-text-block p,
.dark-mode .custom-area-header p,
.dark-mode .custom-records-section p,
.dark-mode .custom-area-onboarding p,
.dark-mode .cell-notes {
  color: #b5c4cd;
}
.dark-mode .custom-chart-list > div > div,
.dark-mode .custom-image-placeholder {
  background: #263743;
}
.dark-mode .directory-count,
.dark-mode .notification-symbol,
.dark-mode .custom-area-onboarding > span {
  background: #173a39;
  color: var(--teal);
}
.dark-mode .cell-delete-button:hover,
.dark-mode .danger-button {
  border-color: #62383c;
  background: #332126;
  color: #f29aa0;
}
.dark-mode .task-check-card.task-feita {
  background: #162e28;
}
.dark-mode .task-check-card.task-ausente {
  background: #352628;
}
.dark-mode .task-check-card.task-substituto {
  background: #312d1f;
}
.dark-mode .task-check-card.task-pendente {
  background: #172630;
}

@media (max-width: 900px) {
  .user-directory-toolbar {
    grid-template-columns: 1fr 1fr;
  }
  .user-search-field {
    grid-column: 1 / -1;
  }
  .cell-grid {
    grid-template-columns: 1fr;
  }
  .custom-area-header {
    grid-template-columns: 48px minmax(0, 1fr);
  }
  .custom-area-admin-actions {
    grid-column: 1 / -1;
    justify-content: flex-end;
  }
}

@media (max-width: 760px) {
  .account-toolbar {
    position: sticky;
    top: 8px;
    z-index: 29;
    margin-bottom: 17px;
  }
  .account-toolbar-actions {
    width: 100%;
    justify-content: stretch;
    padding: 5px;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: color-mix(in srgb, var(--canvas) 88%, transparent);
    box-shadow: 0 10px 28px rgba(23, 50, 77, 0.12);
    backdrop-filter: blur(14px);
  }
  .account-action {
    flex: 1;
    min-width: 0;
    padding: 0 8px;
    box-shadow: none;
  }
  .account-action > span:nth-child(2) {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .notification-center {
    position: fixed;
    inset: 68px 12px auto;
    width: auto;
    max-height: calc(100vh - 155px);
  }
  .notification-list {
    max-height: calc(100vh - 250px);
  }
  .profile-preferences-card {
    align-items: stretch;
    flex-direction: column;
  }
  .profile-preferences-card button {
    width: 100%;
  }
  .user-directory-toolbar {
    grid-template-columns: 1fr;
  }
  .user-search-field {
    grid-column: auto;
  }
  .cell-card-header {
    grid-template-columns: 42px minmax(0, 1fr);
    padding: 17px;
  }
  .cell-member-count {
    grid-column: 1 / -1;
    justify-self: start;
  }
  .custom-area-header {
    padding: 18px;
  }
  .custom-area-admin-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .custom-content-grid {
    grid-template-columns: 1fr;
    padding: 17px;
  }
  .custom-block-title {
    grid-column: auto;
  }
  .custom-area-empty-content {
    grid-template-columns: 38px minmax(0, 1fr);
  }
  .custom-area-empty-content button {
    grid-column: 1 / -1;
    width: 100%;
  }
  .custom-records-section {
    margin: 0 17px 17px;
    padding: 16px;
  }
  .custom-records-section > header {
    align-items: stretch;
    flex-direction: column;
  }
  .custom-records-section > header button {
    width: 100%;
  }
  .block-editor-card > header {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .account-action {
    font-size: 12px !important;
  }
  .account-action > span:first-child {
    font-size: 16px;
  }
  .logout-action > span:last-child,
  .notification-trigger > span:nth-child(2) {
    display: none;
  }
  .notification-center > header {
    align-items: flex-start;
    flex-direction: column;
  }
  .custom-chart-list > div {
    grid-template-columns: 1fr 40px;
  }
  .custom-chart-list > div > div {
    grid-column: 1 / -1;
    grid-row: 2;
  }
}

/* Mensagens programadas, exibição por área e modo manutenção */
.login-scheduled-region {
  position: relative;
  z-index: 1;
  max-width: 720px;
  min-height: 158px;
  margin-top: 38px;
}
.login-scheduled-message {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 16px;
  align-items: start;
  padding: 22px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  box-shadow: 0 20px 46px rgba(0, 0, 0, 0.15);
  backdrop-filter: blur(16px);
  animation: scheduledFade var(--message-cycle, 7s) ease both;
}
.login-scheduled-message > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-size: 20px;
  font-weight: 850;
}
.login-scheduled-message > div {
  display: grid;
  gap: 6px;
}
.login-scheduled-message small {
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.13em;
}
.login-scheduled-message strong {
  font-size: 19px;
  line-height: 1.3;
}
.login-scheduled-message p {
  margin: 0;
  color: rgba(255, 255, 255, 0.86);
  font-size: 15px;
  line-height: 1.6;
}
.login-scheduled-message.type-importante {
  border-color: rgba(255, 207, 112, 0.7);
  background: rgba(122, 78, 13, 0.3);
}
.login-scheduled-message.type-urgente {
  border-color: rgba(255, 145, 151, 0.75);
  background: rgba(126, 30, 40, 0.35);
}
.login-message-progress {
  display: flex;
  justify-content: center;
  gap: 7px;
  margin-top: 14px;
}
.login-message-progress i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.3);
  transition: width 180ms ease, background 180ms ease;
}
.login-message-progress i.active {
  width: 25px;
  background: color-mix(in srgb, var(--login-accent) 45%, white);
}
.login-maintenance-alert {
  display: grid;
  grid-template-columns: 37px minmax(0, 1fr);
  gap: 12px;
  margin-bottom: 24px;
  padding: 16px;
  border: 1px solid #eab66b;
  border-radius: 15px;
  background: #fff7e8;
  color: #67420d;
}
.login-maintenance-alert > span {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #f5dfb8;
  font-weight: 850;
}
.login-maintenance-alert > div {
  display: grid;
  gap: 5px;
}
.login-maintenance-alert strong {
  color: #5c3805;
  font-size: 15px;
}
.login-maintenance-alert p,
.login-maintenance-alert small {
  margin: 0;
  font-size: 12px;
  line-height: 1.55;
}
.login-maintenance-alert small {
  color: #85612a;
}

.maintenance-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 16% 12%, rgba(23, 135, 127, 0.17), transparent 30%),
    linear-gradient(145deg, #102b43, #17324d);
}
.maintenance-page > section {
  width: min(560px, 100%);
  padding: clamp(30px, 6vw, 54px);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 34px 90px rgba(3, 17, 27, 0.35);
  text-align: center;
}
.maintenance-symbol {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  margin: 0 auto 22px;
  border-radius: 18px;
  background: var(--teal-soft);
  color: var(--teal);
  font-size: 28px;
}
.maintenance-page h1 {
  margin: 7px 0 14px;
  color: var(--navy);
  font-size: clamp(30px, 7vw, 45px);
  letter-spacing: -0.045em;
}
.maintenance-page p:not(.eyebrow) {
  margin: 0;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.7;
}
.maintenance-page small {
  display: block;
  margin-top: 14px;
  color: #78541d;
  font-size: 13px;
}
.maintenance-page a {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 25px;
  padding: 0 24px;
  border-radius: 12px;
  background: var(--teal);
  color: #fff;
  font-size: 14px;
  font-weight: 800;
  text-decoration: none;
}

.display-message-stack {
  margin: 0 0 20px;
}
.display-message-banner {
  position: relative;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: start;
  padding: 18px 20px;
  overflow: hidden;
  border: 1px solid #b9dadd;
  border-radius: 17px;
  background: linear-gradient(135deg, #eef9f8, #fff);
  color: var(--ink);
  box-shadow: 0 13px 35px rgba(23, 50, 77, 0.08);
  animation: scheduledFade var(--message-cycle, 7s) ease both;
}
.display-message-banner.type-importante {
  border-color: #e6c57d;
  background: linear-gradient(135deg, #fff7e5, #fff);
}
.display-message-banner.type-urgente {
  border-color: #e7a2a8;
  background: linear-gradient(135deg, #fff0f1, #fff);
}
.display-message-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: #d8efed;
  color: #116e68;
  font-size: 20px;
  font-weight: 900;
}
.type-importante .display-message-icon {
  background: #f5e4bc;
  color: #7b5411;
}
.type-urgente .display-message-icon {
  background: #f4d3d6;
  color: #9d323b;
}
.display-message-banner > div {
  min-width: 0;
  display: grid;
  gap: 4px;
}
.display-message-banner small {
  color: var(--teal);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.12em;
}
.display-message-banner strong {
  color: var(--navy);
  font-size: 17px;
  line-height: 1.35;
}
.display-message-banner p {
  margin: 0;
  color: #526978;
  font-size: 14px;
  line-height: 1.55;
  white-space: pre-wrap;
}
.display-message-counter {
  align-self: center;
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(23, 50, 77, 0.07);
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.display-control-panel {
  display: grid;
  gap: 20px;
  margin-bottom: 25px;
  padding: clamp(20px, 3vw, 30px);
  border: 1px solid var(--line);
  border-radius: 23px;
  background: var(--white);
  box-shadow: var(--shadow);
}
.display-control-heading,
.maintenance-control-title,
.maintenance-actions,
.scheduled-message-list-title,
.scheduled-editor-title,
.scheduled-message-status,
.scheduled-message-actions,
.login-message-management {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.display-control-heading h2 {
  margin: 4px 0 6px;
  color: var(--navy);
  font-size: 23px;
  letter-spacing: -0.035em;
}
.display-control-heading > div > p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}
.maintenance-control {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
  padding: 21px;
  border: 1px solid #d7e1e6;
  border-radius: 18px;
  background: #f8fafb;
}
.maintenance-control.active {
  border-color: #e0b35f;
  background: #fff8e9;
}
.maintenance-control-title {
  grid-column: 1 / -1;
}
.maintenance-control-title > span {
  width: 43px;
  height: 43px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: #e3f3f1;
  color: var(--teal);
  font-size: 20px;
}
.maintenance-control-title > div {
  flex: 1;
}
.maintenance-control-title strong {
  color: var(--navy);
  font-size: 17px;
}
.maintenance-control-title p {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}
.display-control-panel label,
.scheduled-message-editor label {
  display: grid;
  gap: 7px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 750;
}
.display-control-panel input:not([type="checkbox"]),
.display-control-panel select,
.display-control-panel textarea {
  width: 100%;
  min-height: 45px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--white);
  color: var(--ink);
  padding: 10px 12px;
  outline: none;
  font-size: 14px;
}
.display-control-panel textarea {
  resize: vertical;
  line-height: 1.55;
}
.display-control-panel input:focus,
.display-control-panel select:focus,
.display-control-panel textarea:focus {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(23, 135, 127, 0.11);
}
.switch-field {
  display: flex !important;
  align-items: center;
  gap: 9px !important;
  cursor: pointer;
}
.switch-field input {
  width: 20px;
  height: 20px;
  accent-color: var(--teal);
}
.switch-field span {
  font-size: 13px;
  font-weight: 800;
}
.maintenance-actions small {
  max-width: 570px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}
.scheduled-message-layout {
  display: grid;
  grid-template-columns: minmax(260px, 0.72fr) minmax(400px, 1.28fr);
  gap: 20px;
  align-items: start;
}
.scheduled-message-list,
.scheduled-message-editor {
  display: grid;
  gap: 13px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #f8fafb;
}
.scheduled-message-list-title strong {
  color: var(--navy);
  font-size: 15px;
}
.scheduled-message-list-title small {
  color: var(--muted);
  font-size: 12px;
}
.scheduled-message-card {
  display: grid;
  gap: 9px;
  padding: 15px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: 13px;
  background: var(--white);
}
.scheduled-message-card.type-importante {
  border-left-color: #ce942c;
}
.scheduled-message-card.type-urgente {
  border-left-color: #c74c56;
}
.scheduled-message-status span {
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 850;
}
.scheduled-message-status .live {
  background: #dff2e9;
  color: #24714e;
}
.scheduled-message-status .paused {
  background: #edf1f3;
  color: #6b7c89;
}
.scheduled-message-status small {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
}
.scheduled-message-card > strong {
  color: var(--navy);
  font-size: 15px;
}
.scheduled-message-card > p {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}
.scheduled-message-destinations {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.scheduled-message-destinations span {
  padding: 4px 7px;
  border-radius: 7px;
  background: #eef4f6;
  color: #526978;
  font-size: 10px;
  font-weight: 700;
}
.scheduled-message-actions {
  justify-content: flex-start;
  padding-top: 3px;
}
.scheduled-message-actions button,
.scheduled-editor-title button {
  border: 0;
  background: none;
  color: var(--teal);
  padding: 3px 0;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
.scheduled-message-actions .danger-link {
  color: #a13d45;
}
.scheduled-message-empty {
  padding: 22px;
  border: 1px dashed var(--line);
  border-radius: 12px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.55;
  text-align: center;
}
.scheduled-editor-title h3 {
  margin: 2px 0 0;
  color: var(--navy);
  font-size: 19px;
}
.scheduled-editor-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
.scheduled-editor-grid.two-columns {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.editor-active-switch {
  align-self: end;
  min-height: 45px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--white);
}
.destination-fieldset {
  margin: 0;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 13px;
}
.destination-fieldset legend {
  padding: 0 6px;
  color: var(--navy);
  font-size: 14px;
  font-weight: 850;
}
.destination-fieldset > p {
  margin: 0 0 12px;
  color: var(--muted);
  font-size: 12px;
}
.destination-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}
.destination-grid label {
  min-height: 40px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 9px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--white);
  cursor: pointer;
}
.destination-grid label.featured {
  border-color: #add5d1;
  background: #eef8f7;
}
.destination-grid input {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  accent-color: var(--teal);
}
.destination-grid span {
  font-size: 11px;
  line-height: 1.3;
}
.scheduled-save-button {
  width: 100%;
  justify-content: center;
}
.login-message-management {
  padding: 17px;
  border: 1px solid #bfddda;
  border-radius: 14px;
  background: #f1f9f8;
}
.login-message-management > div {
  display: grid;
  gap: 4px;
}
.login-message-management strong {
  color: var(--navy);
  font-size: 14px;
}
.login-message-management span {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}
.notification-header-actions {
  display: flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 10px !important;
}

.animation-deslizar {
  animation-name: scheduledSlide;
}
.animation-pulsar {
  animation-name: scheduledPulse;
}
@keyframes scheduledFade {
  0% { opacity: 0; transform: translateY(5px); }
  8%, 90% { opacity: 1; transform: translateY(0); }
  100% { opacity: 0; transform: translateY(-3px); }
}
@keyframes scheduledSlide {
  0% { opacity: 0; transform: translateX(-22px); }
  10%, 90% { opacity: 1; transform: translateX(0); }
  100% { opacity: 0; transform: translateX(18px); }
}
@keyframes scheduledPulse {
  0% { opacity: 0; transform: scale(0.985); }
  8% { opacity: 1; transform: scale(1); }
  45% { box-shadow: 0 16px 42px rgba(23, 135, 127, 0.18); }
  55% { box-shadow: 0 20px 54px rgba(23, 135, 127, 0.28); }
  90% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.99); }
}

.dark-mode .display-message-banner,
.dark-mode .display-control-panel,
.dark-mode .maintenance-control,
.dark-mode .scheduled-message-list,
.dark-mode .scheduled-message-editor,
.dark-mode .scheduled-message-card,
.dark-mode .destination-grid label,
.dark-mode .editor-active-switch,
.dark-mode .login-message-management {
  border-color: var(--line);
  background: var(--white);
  color: var(--ink);
}
.dark-mode .display-message-banner.type-importante,
.dark-mode .maintenance-control.active {
  background: #332b1d;
  border-color: #795f2d;
}
.dark-mode .display-message-banner.type-urgente {
  background: #382326;
  border-color: #774149;
}
.dark-mode .display-message-banner p,
.dark-mode .display-control-heading > div > p:last-child,
.dark-mode .maintenance-control-title p,
.dark-mode .maintenance-actions small,
.dark-mode .scheduled-message-card > p,
.dark-mode .destination-fieldset > p,
.dark-mode .login-message-management span {
  color: var(--muted);
}
.dark-mode .display-message-banner strong,
.dark-mode .display-control-heading h2,
.dark-mode .maintenance-control-title strong,
.dark-mode .scheduled-message-list-title strong,
.dark-mode .scheduled-message-card > strong,
.dark-mode .scheduled-editor-title h3,
.dark-mode .destination-fieldset legend,
.dark-mode .login-message-management strong {
  color: var(--ink);
}
.dark-mode .display-control-panel input:not([type="checkbox"]),
.dark-mode .display-control-panel select,
.dark-mode .display-control-panel textarea {
  border-color: var(--line);
  background: #172630;
  color: var(--ink);
}
.dark-mode .destination-grid label.featured,
.dark-mode .scheduled-message-destinations span {
  background: #1b3137;
  color: #c5d8dd;
}

@media (max-width: 1040px) {
  .scheduled-message-layout {
    grid-template-columns: 1fr;
  }
  .scheduled-editor-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 760px) {
  .login-scheduled-region {
    min-height: 0;
    margin-top: 28px;
  }
  .login-scheduled-message {
    grid-template-columns: 38px minmax(0, 1fr);
    gap: 12px;
    padding: 17px;
  }
  .login-scheduled-message > span {
    width: 37px;
    height: 37px;
  }
  .login-scheduled-message strong {
    font-size: 17px;
  }
  .login-scheduled-message p {
    font-size: 14px;
  }
  .display-control-heading,
  .maintenance-control-title,
  .maintenance-actions,
  .login-message-management {
    align-items: stretch;
    flex-direction: column;
  }
  .display-control-heading .primary-button,
  .maintenance-actions .primary-button,
  .login-message-management .ghost-button {
    width: 100%;
    justify-content: center;
  }
  .maintenance-control,
  .scheduled-editor-grid,
  .scheduled-editor-grid.two-columns {
    grid-template-columns: 1fr;
  }
  .maintenance-control-title > span {
    align-self: flex-start;
  }
  .maintenance-control-title .switch-field {
    min-height: 43px;
    padding: 0 11px;
    border: 1px solid var(--line);
    border-radius: 11px;
    background: var(--white);
  }
  .destination-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .display-message-banner {
    grid-template-columns: 39px minmax(0, 1fr);
    padding: 15px;
  }
  .display-message-icon {
    width: 38px;
    height: 38px;
  }
  .display-message-counter {
    grid-column: 2;
    justify-self: start;
  }
}
@media (max-width: 480px) {
  .destination-grid {
    grid-template-columns: 1fr;
  }
  .display-control-panel {
    padding: 15px;
    border-radius: 17px;
  }
  .notification-header-actions {
    width: 100%;
    align-items: flex-start;
    flex-direction: column !important;
  }
}
@media (prefers-reduced-motion: reduce) {
  .login-scheduled-message,
  .display-message-banner {
    opacity: 1;
    transform: none;
    animation: none;
  }
}

/* VÍNKULO V4.5 PILOTO */
:root {
  --pilot-bg: #f2f3f5;
  --pilot-surface: #fbfbfa;
  --pilot-surface-2: #e9ecef;
  --pilot-text: #1b2430;
  --pilot-muted: #687380;
  --pilot-line: #d6dbe0;
  --pilot-navy: #080b10;
  --pilot-purple: #b87b23;
  --pilot-blue: #2f7ee6;
  --pilot-cyan: #26a989;
  --pilot-primary: var(--pilot-purple);
  --pilot-accent: var(--pilot-cyan);
  --pilot-gradient: linear-gradient(135deg, #b87b23, #e0a542);
  --pilot-shadow: 0 20px 54px rgba(22, 30, 42, 0.09);
}
html[data-pilot-theme="escuro"] {
  color-scheme: dark;
  --pilot-bg: #05080d;
  --pilot-surface: #0b1016;
  --pilot-surface-2: #111821;
  --pilot-text: #f3f5f7;
  --pilot-muted: #9ca7b5;
  --pilot-line: #202a35;
  --pilot-purple: #e0a542;
  --pilot-blue: #62a7ff;
  --pilot-cyan: #4fd1a5;
  --pilot-gradient: linear-gradient(135deg, #b77a20, #e6ad4b);
  --pilot-shadow: 0 24px 70px rgba(0, 0, 0, 0.34);
}
html[data-pilot-theme="escuro"] body {
  background: var(--pilot-bg);
  color: var(--pilot-text);
}
.pilot-dashboard[data-community-palette] {
  --pilot-bg: var(--community-light-bg);
  --pilot-surface: var(--community-light-surface);
  --pilot-surface-2: var(--community-light-surface-2);
  --pilot-text: var(--community-light-text);
  --pilot-muted: var(--community-light-muted);
  --pilot-line: var(--community-light-line);
  --pilot-purple: var(--community-light-primary);
  --pilot-blue: var(--community-light-secondary);
  --pilot-cyan: var(--community-light-accent);
  --pilot-gradient: linear-gradient(135deg,var(--community-light-primary),var(--community-light-accent));
  --pilot-shadow: var(--community-light-shadow);
}
html[data-pilot-theme="escuro"] .pilot-dashboard[data-community-palette] {
  --pilot-bg: var(--community-dark-bg);
  --pilot-surface: var(--community-dark-surface);
  --pilot-surface-2: var(--community-dark-surface-2);
  --pilot-text: var(--community-dark-text);
  --pilot-muted: var(--community-dark-muted);
  --pilot-line: var(--community-dark-line);
  --pilot-purple: var(--community-dark-primary);
  --pilot-blue: var(--community-dark-secondary);
  --pilot-cyan: var(--community-dark-accent);
  --pilot-gradient: linear-gradient(135deg,var(--community-dark-primary),var(--community-dark-accent));
  --pilot-shadow: var(--community-dark-shadow);
}
@media (prefers-color-scheme: dark) {
  html:not([data-pilot-theme]) {
    color-scheme: dark;
    --pilot-bg: #05080d;
    --pilot-surface: #0b1016;
    --pilot-surface-2: #111821;
    --pilot-text: #f3f5f7;
    --pilot-muted: #9ca7b5;
    --pilot-line: #202a35;
    --pilot-purple: #e0a542;
    --pilot-blue: #62a7ff;
    --pilot-cyan: #4fd1a5;
    --pilot-gradient: linear-gradient(135deg, #b77a20, #e6ad4b);
  }
  html:not([data-pilot-theme]) body {
    background: var(--pilot-bg);
    color: var(--pilot-text);
  }
  html:not([data-pilot-theme]) .pilot-dashboard[data-community-palette] {
    --pilot-bg: var(--community-dark-bg);
    --pilot-surface: var(--community-dark-surface);
    --pilot-surface-2: var(--community-dark-surface-2);
    --pilot-text: var(--community-dark-text);
    --pilot-muted: var(--community-dark-muted);
    --pilot-line: var(--community-dark-line);
    --pilot-purple: var(--community-dark-primary);
    --pilot-blue: var(--community-dark-secondary);
    --pilot-cyan: var(--community-dark-accent);
    --pilot-gradient: linear-gradient(135deg,var(--community-dark-primary),var(--community-dark-accent));
    --pilot-shadow: var(--community-dark-shadow);
  }
}
.vinkulo-site,.pilot-dashboard,.pilot-legal-shell,.pilot-state-page,.pilot-loading {
  min-height: 100vh;
  background: var(--pilot-bg);
  color: var(--pilot-text);
}
.pilot-strip {
  min-height: 30px;
  display: grid;
  place-items: center;
  padding: 7px 20px;
  background: var(--pilot-gradient);
  color: #fff;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .15em;
  text-align: center;
}
.vinkulo-header {
  width: min(1180px,calc(100% - 40px));
  min-height: 82px;
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.vinkulo-brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: inherit;
  text-decoration: none;
}
.vinkulo-mark {
  position: relative;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: var(--pilot-navy);
  color: #fff;
  box-shadow: 0 14px 32px rgba(40,83,210,.22);
  font-size: 20px;
  font-weight: 950;
}
.vinkulo-mark i { color: var(--pilot-cyan); font-size: 14px; font-style: normal; }
.vinkulo-brand>span:last-child { display: grid; gap: 2px; }
.vinkulo-brand strong { font-size: 20px; letter-spacing: -.04em; }
.vinkulo-brand small {
  color: var(--pilot-muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .13em;
  text-transform: uppercase;
}
.vinkulo-header nav { display: flex; align-items: center; gap: clamp(14px,2.2vw,30px); }
.vinkulo-header nav a {
  color: var(--pilot-muted);
  font-size: 13px;
  font-weight: 750;
  text-decoration: none;
}
.vinkulo-header nav .header-login {
  padding: 11px 19px;
  border: 1px solid var(--pilot-line);
  border-radius: 999px;
  background: var(--pilot-surface);
  color: var(--pilot-text);
}
.vinkulo-hero {
  width: min(1180px,calc(100% - 40px));
  min-height: 690px;
  margin: auto;
  display: grid;
  grid-template-columns: minmax(0,1fr) minmax(420px,.86fr);
  align-items: center;
  gap: clamp(36px,7vw,100px);
  padding: 65px 0 90px;
}
.pilot-kicker {
  margin: 0 0 12px;
  color: var(--pilot-purple);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .16em;
}
.hero-copy h1,.directory-intro h1,.community-public-hero h1 {
  margin: 0;
  color: var(--pilot-text);
  font-size: clamp(45px,6.2vw,85px);
  line-height: .98;
  letter-spacing: -.065em;
}
.hero-copy h1 span {
  display: block;
  margin-top: 10px;
  background: var(--pilot-gradient);
  background-clip: text;
  color: transparent;
}
.hero-copy>p:not(.pilot-kicker),.directory-intro>p:last-child {
  max-width: 680px;
  margin: 26px 0 0;
  color: var(--pilot-muted);
  font-size: 18px;
  line-height: 1.65;
}
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.hero-actions a,.public-community-cta>a {
  min-height: 50px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 23px;
  border-radius: 14px;
  font-size: 13px;
  font-weight: 850;
  text-decoration: none;
}
.primary-action,.public-community-cta>a { background: var(--pilot-gradient); color: #fff; }
.secondary-action { border: 1px solid var(--pilot-line); background: var(--pilot-surface); color: var(--pilot-text); }
.hero-trust { display: flex; flex-wrap: wrap; gap: 15px 24px; margin: 25px 0 0; padding: 0; color: var(--pilot-muted); font-size: 12px; font-weight: 750; list-style: none; }
.hero-trust li:before { content: "✓"; margin-right: 7px; color: var(--pilot-cyan); }
.hero-visual {
  position: relative;
  min-height: 500px;
  overflow: hidden;
  border-radius: 42px;
  background: radial-gradient(circle at 25% 20%,rgba(120,68,245,.55),transparent 37%),radial-gradient(circle at 83% 75%,rgba(49,216,208,.45),transparent 35%),var(--pilot-navy);
  box-shadow: 0 40px 90px rgba(5,9,31,.28);
}
.hero-visual:before { content:"V+"; position:absolute; right:20px; bottom:-45px; color:rgba(255,255,255,.05); font-size:190px; font-weight:950; }
.hero-orbit { position:absolute; border:1px solid rgba(255,255,255,.1); border-radius:50%; }
.orbit-one { width:340px; height:340px; top:30px; right:-80px; }
.orbit-two { width:250px; height:250px; left:-100px; bottom:-55px; }
.hero-card {
  position:absolute;
  padding: 23px;
  border:1px solid rgba(255,255,255,.18);
  border-radius:22px;
  background:rgba(255,255,255,.1);
  color:#fff;
  backdrop-filter:blur(18px);
}
.hero-card small { color:rgba(255,255,255,.6); font-size:8px; font-weight:900; letter-spacing:.12em; }
.hero-card strong { display:block; margin-top:8px; font-size:17px; }
.hero-card p { margin:5px 0 0; color:rgba(255,255,255,.65); font-size:12px; }
.hero-card-main { top:82px; left:42px; width:calc(100% - 84px); }
.hero-card-main strong { font-size:22px; }
.status-dot { width:9px; height:9px; float:right; border-radius:50%; background:#62e7a8; }
.hero-card-small { left:42px; bottom:86px; width:55%; }
.review-badge { display:inline-flex; margin-top:13px; padding:6px 9px; border-radius:999px; background:rgba(49,216,208,.14); color:var(--pilot-cyan); font-size:8px; font-weight:900; }
.hero-card-lock { right:33px; bottom:33px; display:flex; align-items:center; gap:11px; padding:16px; }
.hero-card-lock>span { width:36px; height:36px; display:grid; place-items:center; border-radius:11px; background:rgba(255,255,255,.1); }
.pilot-principles { padding:100px max(20px,calc((100vw - 1180px)/2)); background:var(--pilot-navy); color:#fff; }
