  .community-selector>span,.pilot-top-actions { grid-column:1; }
  .pilot-top-actions { justify-content:space-between; }
  .pilot-sidebar { top:0; }
  .pilot-workspace { padding:25px 16px 50px; }
  .workspace-heading { flex-direction:column; }
  .pilot-metrics,.feature-flag-grid,.invite-generator,.invite-result { grid-template-columns:1fr; }
  .operations-notice { align-items:flex-start; flex-direction:column; }
  .operations-form,.operations-toolbar,.cell-create-form,.cell-grid,.ministry-create-form,.schedule-create-form,.assignment-form,.ministry-skeleton { grid-template-columns:1fr; }
  .operations-form .operations-wide-field { grid-column:1; }
  .ministry-create-form .ministry-wide-field,.schedule-create-form .schedule-wide-field { grid-column:1; }
  .volunteer-form { grid-template-columns:1fr; }
  .volunteer-form .day-selector,.volunteer-form>button { grid-column:1; }
  .ministry-tabs { overflow-x:auto; }
  .ministry-tabs button { flex:1; white-space:nowrap; }
  .ministry-team>div { grid-template-columns:34px minmax(0,1fr) auto; }
  .ministry-team>div>button { grid-column:2/-1; justify-self:start; }
  .assignment-list>div { grid-template-columns:minmax(0,1fr) auto; }
  .assignment-list>div>button { grid-column:1/-1; justify-self:start; }
  .event-form,.public-events-grid,.event-skeleton-grid { grid-template-columns:1fr; }
  .event-form .event-wide-field { grid-column:1; }
  .event-form-actions { justify-content:stretch; flex-direction:column; }
  .event-form-actions button { width:100%; }
  .public-events-section { width:min(100% - 28px,1100px); }
  .public-events-section>header { align-items:flex-start; flex-direction:column; }
  .operations-list>article { grid-template-columns:1fr; }
  .operation-card-actions { flex-direction:row; padding:0 9px 10px; }
}

/* V4.5 — controle do módulo de redes pelo SuperAdmin */
.network-feature-control {
  margin:0 0 20px;
  border:1px solid var(--pilot-line);
  border-radius:20px;
  background:var(--pilot-surface);
  overflow:hidden;
}
.network-feature-control>header {
  min-height:42px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:9px 16px;
  color:#fff;
  font-size:9px;
  letter-spacing:.04em;
}
.network-feature-control>header.enabled {
  background:linear-gradient(90deg,#1e7d50,#36a26f);
}
.network-feature-control>header.disabled {
  background:linear-gradient(90deg,#316b47,#45815a);
}
.network-feature-control>header strong { font-weight:950; }
.network-feature-control>header span {
  padding:5px 8px;
  border-radius:999px;
  background:rgba(255,255,255,.14);
  font-size:7px;
  font-weight:900;
}
.network-control-loading {
  min-height:260px;
  display:grid;
  place-content:center;
  justify-items:center;
  color:var(--pilot-muted);
}
.network-control-body {
  display:grid;
  grid-template-columns:minmax(0,1.08fr) minmax(330px,.92fr);
}
.network-control-form {
  display:grid;
  align-content:start;
  gap:17px;
  padding:24px;
  border-right:1px solid var(--pilot-line);
}
.network-control-form h2 {
  margin:3px 0 0;
  font-size:24px;
  letter-spacing:-.035em;
}
.network-control-form>div:first-child>p:last-child {
  max-width:600px;
  margin:8px 0 0;
  color:var(--pilot-muted);
  font-size:9px;
  line-height:1.55;
}
.network-status-choice,.network-scope-choice {
  display:grid;
  gap:7px;
  margin:0;
  padding:0;
  border:0;
}
.network-status-choice {
  grid-template-columns:repeat(2,minmax(0,1fr));
}
.network-status-choice legend,.network-scope-choice legend {
  grid-column:1/-1;
  margin-bottom:2px;
  color:var(--pilot-text);
  font-size:9px;
  font-weight:900;
}
.network-status-choice label,.network-scope-choice label {
  min-width:0;
  display:grid;
  grid-template-columns:16px minmax(0,1fr);
  align-items:center;
  gap:8px;
  padding:11px;
  border:1px solid var(--pilot-line);
  border-radius:12px;
  background:var(--pilot-surface-2);
  cursor:pointer;
}
.network-status-choice input,.network-scope-choice input {
  width:15px;
  height:15px;
  accent-color:var(--pilot-purple);
}
.network-status-choice strong,.network-status-choice small,
.network-scope-choice strong,.network-scope-choice small {
  display:block;
}
.network-status-choice strong,.network-scope-choice strong {
  font-size:9px;
}
.network-status-choice small,.network-scope-choice small {
  margin-top:3px;
  color:var(--pilot-muted);
  font-size:7px;
  line-height:1.35;
}
.network-scope-choice {
  grid-template-columns:repeat(2,minmax(0,1fr));
}
.network-scope-choice label:last-child { grid-column:1/-1; }
.network-control-field,.network-test-dates label,
.network-critical-confirmation label {
  display:grid;
  gap:6px;
  color:var(--pilot-muted);
  font-size:8px;
  font-weight:850;
}
.network-control-field select,.network-test-dates input,
.network-critical-confirmation input,.network-critical-confirmation textarea {
  width:100%;
  min-height:43px;
  padding:0 11px;
  border:1px solid var(--pilot-line);
  border-radius:11px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
}
.network-critical-confirmation textarea {
  min-height:66px;
  padding:10px 11px;
  resize:vertical;
}
.network-control-field>small {
  color:#d99a32;
  font-size:7px;
}
.network-test-dates {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:9px;
}
.network-affiliate-permission {
  display:grid;
  grid-template-columns:18px minmax(0,1fr);
  align-items:center;
  gap:10px;
  padding:13px;
  border:1px solid color-mix(in srgb,#35b878 30%,var(--pilot-line));
  border-radius:13px;
  background:color-mix(in srgb,#35b878 7%,var(--pilot-surface));
  cursor:pointer;
}
.network-affiliate-permission input {
  width:17px;
  height:17px;
  accent-color:#35b878;
}
.network-affiliate-permission strong,.network-affiliate-permission small {
  display:block;
}
.network-affiliate-permission strong { font-size:9px; }
.network-affiliate-permission small {
  margin-top:3px;
  color:var(--pilot-muted);
  font-size:7px;
}
.network-critical-confirmation {
  display:grid;
  grid-template-columns:1.25fr .75fr;
  gap:9px;
  padding:13px;
  border:1px solid color-mix(in srgb,#ef7187 33%,var(--pilot-line));
  border-radius:14px;
  background:color-mix(in srgb,#ef7187 6%,var(--pilot-surface));
}
.network-critical-confirmation label:first-child { grid-row:span 2; }
.network-control-submit {
  min-height:46px;
  border:0;
  border-radius:12px;
  background:linear-gradient(135deg,#315fef,#6b3ad5);
  color:#fff;
  font-size:9px;
  font-weight:900;
  cursor:pointer;
}
.network-control-submit:disabled {
  opacity:.5;
  cursor:not-allowed;
}
.network-control-preview {
  display:grid;
  align-content:center;
  gap:14px;
  min-width:0;
  padding:28px;
  background:linear-gradient(150deg,var(--pilot-surface),var(--pilot-surface-2));
}
.network-control-preview>.pilot-kicker { text-align:center; }
.network-preview-root {
  width:min(240px,100%);
  display:grid;
  grid-template-columns:38px minmax(0,1fr);
  align-items:center;
  gap:9px;
  justify-self:center;
  padding:12px;
  border:1px solid color-mix(in srgb,#3b82f6 35%,var(--pilot-line));
  border-radius:14px;
  background:var(--pilot-surface);
  text-align:left;
}
.network-preview-root>span {
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border-radius:11px;
  background:color-mix(in srgb,#3b82f6 12%,var(--pilot-surface));
  color:#3b82f6;
  font-size:17px;
}
.network-preview-root strong { font-size:9px; }
.network-preview-branches {
  position:relative;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px;
  padding-top:18px;
}
.network-preview-branches::before {
  content:"";
  position:absolute;
  top:0;
  left:16%;
  right:16%;
  height:14px;
  border-top:1px solid var(--pilot-line);
  border-left:1px solid var(--pilot-line);
  border-right:1px solid var(--pilot-line);
}
.network-preview-branches article {
  display:grid;
  justify-items:center;
  gap:4px;
  padding:14px 7px;
  border:1px solid var(--pilot-line);
  border-radius:13px;
  background:var(--pilot-surface);
  text-align:center;
}
.network-preview-branches article>span {
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:10px;
  background:color-mix(in srgb,#35b878 12%,var(--pilot-surface));
  color:#35b878;
  font-size:15px;
}
.network-preview-branches strong { font-size:8px; }
.network-preview-branches small {
  color:var(--pilot-muted);
  font-size:6px;
}
.network-preview-footer {
  padding:10px;
  border-radius:11px;
  background:var(--pilot-surface);
  color:var(--pilot-muted);
  font-size:8px;
  font-weight:850;
  text-align:center;
}
.network-control-state {
  display:flex;
  align-items:center;
  gap:10px;
  margin-top:6px;
  padding:13px;
  border:1px solid var(--pilot-line);
  border-radius:13px;
  background:var(--pilot-surface);
}
.network-control-state strong,.network-control-state small { display:block; }
.network-control-state strong { font-size:9px; }
.network-control-state small {
  margin-top:3px;
  color:var(--pilot-muted);
  font-size:7px;
}
@media (max-width:1040px) {
  .network-control-body { grid-template-columns:1fr; }
  .network-control-form { border-right:0; border-bottom:1px solid var(--pilot-line); }
}
@media (max-width:680px) {
  .network-feature-control>header {
    align-items:flex-start;
    flex-direction:column;
  }
  .network-control-form,.network-control-preview { padding:18px 14px; }
  .network-status-choice,.network-scope-choice,
  .network-test-dates,.network-critical-confirmation {
    grid-template-columns:1fr;
  }
  .network-scope-choice label:last-child { grid-column:1; }
  .network-critical-confirmation label:first-child { grid-row:auto; }
  .network-preview-branches { gap:5px; }
  .network-preview-branches article { padding:11px 4px; }
  .network-preview-branches strong { font-size:7px; }
}

/* V4.5 — redes, sedes e comunidades afiliadas */
.network-workspace { --network-accent:var(--pilot-purple); }
