}
.network-form-grid .network-checkbox input {
  width:17px;
  min-height:17px;
}

@media (max-width:1100px) {
  .network-metrics { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .network-dashboard-grid { grid-template-columns:1fr; }
}
@media (max-width:680px) {
  .network-workspace { min-width:0; max-width:100%; overflow:clip; }
  .network-heading { align-items:flex-start; flex-direction:column; }
  .network-secure-badge { align-self:flex-start; }
  .network-metrics { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .network-metric { min-height:92px; padding:13px; }
  .network-metric>span { width:34px; height:34px; }
  .network-metric strong { font-size:22px; }
  .network-switcher button { min-width:180px; }
  .network-unit-list>article {
    grid-template-columns:38px minmax(0,1fr);
  }
  .network-unit-icon { width:38px; height:38px; }
  .network-status {
    grid-column:2;
    justify-self:start;
  }
  .network-form-grid { grid-template-columns:1fr; padding:10px; }
  .network-hierarchy>header,.network-actions-panel>header {
    align-items:flex-start;
    flex-direction:column;
  }
}

/* V4.6 — Bloco 14: Diaconia */
.diaconia-workspace {
  display:grid;
  gap:18px;
}
.diaconia-heading {
  padding-bottom:4px;
}
.diaconia-metrics {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:12px;
}
.diaconia-metric {
  min-height:104px;
  display:flex;
  align-items:center;
  gap:13px;
  padding:17px;
  border:1px solid var(--pilot-line);
  border-radius:16px;
  background:var(--pilot-surface);
  box-shadow:var(--pilot-shadow);
}
.diaconia-metric>span {
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  flex:none;
  border-radius:12px;
  background:color-mix(in srgb,var(--pilot-purple) 15%,transparent);
  color:var(--pilot-purple);
  font-weight:900;
}
.diaconia-metric.green>span {
  color:#21c98a;
  background:color-mix(in srgb,#21c98a 15%,transparent);
}
.diaconia-metric.amber>span {
  color:#e9a928;
  background:color-mix(in srgb,#e9a928 15%,transparent);
}
.diaconia-metric.blue>span {
  color:#4a91ff;
  background:color-mix(in srgb,#4a91ff 15%,transparent);
}
.diaconia-metric div {
  display:grid;
  gap:3px;
}
.diaconia-metric strong {
  color:var(--pilot-text);
  font-size:25px;
  line-height:1;
}
.diaconia-metric small {
  color:var(--pilot-muted);
  font-size:10px;
}
.diaconia-loading {
  display:grid;
  gap:12px;
}
.diaconia-loading span {
  min-height:180px;
  border:1px solid var(--pilot-line);
  border-radius:18px;
  background:linear-gradient(
    90deg,
    var(--pilot-surface) 25%,
    var(--pilot-surface-2) 50%,
    var(--pilot-surface) 75%
  );
  background-size:200% 100%;
  animation:ministry-shimmer 1.3s infinite linear;
}
.diaconia-schedule-list {
  display:grid;
  gap:15px;
}
.diaconia-schedule-card {
  overflow:hidden;
  border:1px solid var(--pilot-line);
  border-radius:18px;
  background:var(--pilot-surface);
  box-shadow:var(--pilot-shadow);
}
.diaconia-schedule-card>header {
  min-height:64px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:14px 17px;
  border-bottom:1px solid var(--pilot-line);
  background:var(--pilot-surface-2);
}
.diaconia-schedule-card>header>div {
  display:flex;
  align-items:center;
  gap:10px;
}
.diaconia-schedule-card>header small,
.diaconia-schedule-card>header time {
  color:var(--pilot-muted);
  font-size:10px;
}
.diaconia-status {
  display:inline-flex;
  align-items:center;
  min-height:25px;
  padding:5px 9px;
  border-radius:999px;
  color:#4a91ff;
  background:color-mix(in srgb,#4a91ff 13%,transparent);
  font-size:8px;
  font-weight:900;
  letter-spacing:.06em;
  text-transform:uppercase;
}
.diaconia-status.aguardando_checklist {
  color:#e9a928;
  background:color-mix(in srgb,#e9a928 13%,transparent);
}
.diaconia-status.encerrada {
  color:#21c98a;
  background:color-mix(in srgb,#21c98a 13%,transparent);
}
.diaconia-status.cancelada {
  color:#ec6a79;
  background:color-mix(in srgb,#ec6a79 13%,transparent);
}
.diaconia-schedule-summary {
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(240px,.45fr);
  gap:22px;
  padding:18px;
}
.diaconia-schedule-summary h2 {
  margin:0 0 6px;
  color:var(--pilot-text);
  font-size:19px;
}
.diaconia-schedule-summary p {
  margin:0;
  color:var(--pilot-muted);
  font-size:11px;
  line-height:1.6;
}
.diaconia-schedule-summary dl {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:10px;
  margin:0;
}
.diaconia-schedule-summary dl div {
  padding:11px;
  border:1px solid var(--pilot-line);
  border-radius:12px;
  background:var(--pilot-surface-2);
}
.diaconia-schedule-summary dt {
  color:var(--pilot-muted);
  font-size:8px;
  font-weight:800;
  text-transform:uppercase;
}
.diaconia-schedule-summary dd {
  margin:5px 0 0;
  color:var(--pilot-text);
  font-size:10px;
  font-weight:750;
}
.diaconia-team-row {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  margin:0 18px;
  padding:13px 0;
  border-top:1px solid var(--pilot-line);
}
.diaconia-team-row>strong {
  color:var(--pilot-text);
  font-size:10px;
}
.diaconia-team-row>div {
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  justify-content:flex-end;
  gap:7px;
}
.diaconia-team-row>div>span {
  position:relative;
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border:2px solid var(--pilot-surface);
  border-radius:50%;
  background:var(--pilot-gradient);
  color:#fff;
  font-size:9px;
  font-weight:900;
}
.diaconia-team-row>div>span small {
  position:absolute;
  width:max-content;
  max-width:160px;
  left:50%;
  bottom:calc(100% + 7px);
  z-index:3;
  display:none;
  padding:6px 8px;
  transform:translateX(-50%);
  border-radius:7px;
  background:var(--pilot-text);
  color:var(--pilot-bg);
}
.diaconia-team-row>div>span:hover small {
  display:block;
}
.diaconia-team-row em {
  color:var(--pilot-muted);
  font-size:10px;
}
.diaconia-add-task {
  margin:0 18px 15px;
  border:1px dashed var(--pilot-line);
  border-radius:13px;
  background:var(--pilot-surface-2);
}
.diaconia-add-task summary {
  padding:12px 14px;
  color:var(--pilot-purple);
  cursor:pointer;
  font-size:10px;
  font-weight:850;
}
.diaconia-add-task form {
  grid-template-columns:minmax(0,1.5fr) minmax(180px,.7fr) auto;
  padding:0 13px 13px;
}
.diaconia-checklist {
  display:grid;
  gap:9px;
  padding:17px;
  border-top:1px solid var(--pilot-line);
  background:color-mix(in srgb,var(--pilot-surface-2) 72%,transparent);
}
.diaconia-section-title {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  margin-bottom:3px;
}
.diaconia-section-title strong {
  color:var(--pilot-text);
  font-size:12px;
}
.diaconia-section-title span {
  color:var(--pilot-muted);
  font-size:9px;
}
.diaconia-check-item {
  display:grid;
  grid-template-columns:minmax(190px,1fr) minmax(125px,.35fr) auto;
  align-items:end;
  gap:10px;
  padding:11px;
  border:1px solid var(--pilot-line);
  border-radius:12px;
  background:var(--pilot-surface);
}
.diaconia-check-item.status-feito {
  border-left:3px solid #21c98a;
}
.diaconia-check-item.status-nao_feito {
  border-left:3px solid #ec6a79;
}
.diaconia-check-item.status-substituido {
  border-left:3px solid #8f63ff;
}
.diaconia-task-copy {
  display:flex;
  align-items:center;
  gap:10px;
}
.diaconia-task-copy>span {
  width:29px;
  height:29px;
  display:grid;
  place-items:center;
  flex:none;
  border-radius:9px;
  background:var(--pilot-surface-2);
  color:var(--pilot-purple);
  font-weight:900;
}
.diaconia-task-copy div {
  display:grid;
  gap:3px;
}
.diaconia-task-copy strong {
  color:var(--pilot-text);
  font-size:10px;
}
.diaconia-task-copy small {
  color:var(--pilot-muted);
  font-size:8px;
}
.diaconia-check-item label,
.diaconia-report-form label {
  display:flex;
  flex-direction:column;
  gap:5px;
  color:var(--pilot-muted);
  font-size:8px;
  font-weight:800;
}
.diaconia-check-item select,
.diaconia-check-item input,
.diaconia-report-form textarea {
  width:100%;
  min-height:36px;
  padding:8px 10px;
  border:1px solid var(--pilot-line);
  border-radius:9px;
  outline:none;
  background:var(--pilot-input,var(--pilot-surface-2));
  color:var(--pilot-text);
  font-size:10px;
}
.diaconia-check-item button,
.diaconia-report-form button,
.diaconia-report-ready a {
  min-height:36px;
  padding:9px 13px;
  border:0;
  border-radius:9px;
  background:var(--pilot-gradient);
  color:#fff;
  cursor:pointer;
  font-size:9px;
  font-weight:850;
  text-decoration:none;
}
.diaconia-substitute-fields {
  grid-column:1/-1;
  display:grid;
  grid-template-columns:1fr auto 1fr;
  align-items:end;
  gap:10px;
}
.diaconia-substitute-fields>span {
  padding-bottom:10px;
  color:var(--pilot-muted);
  font-size:8px;
  font-weight:800;
}
.diaconia-observation {
  grid-column:1/3;
}
.diaconia-substitute-note {
  grid-column:1/-1;
  color:var(--pilot-muted);
  font-size:9px;
}
.diaconia-empty-inline {
  margin:0;
  padding:15px;
  border:1px dashed var(--pilot-line);
  border-radius:11px;
  color:var(--pilot-muted);
  font-size:10px;
  text-align:center;
}
.diaconia-report-form {
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:end;
  gap:12px;
  padding:17px;
  border-top:1px solid var(--pilot-line);
}
.diaconia-report-form textarea {
  resize:vertical;
}
.diaconia-report-ready {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:16px 18px;
  border-top:1px solid color-mix(in srgb,#21c98a 30%,var(--pilot-line));
  background:color-mix(in srgb,#21c98a 8%,var(--pilot-surface));
}
.diaconia-report-ready div {
  display:grid;
  gap:3px;
}
.diaconia-report-ready strong {
  color:var(--pilot-text);
  font-size:11px;
}
.diaconia-report-ready span {
  color:var(--pilot-muted);
  font-size:9px;
}
@media (max-width:900px) {
  .diaconia-metrics {
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
  .diaconia-schedule-summary {
    grid-template-columns:1fr;
  }
}
@media (max-width:680px) {
  .diaconia-workspace {
    gap:14px;
  }
  .diaconia-metrics {
    gap:8px;
  }
  .diaconia-metric {
    min-height:88px;
    padding:13px;
  }
  .diaconia-metric>span {
    width:36px;
    height:36px;
  }
  .diaconia-metric strong {
    font-size:21px;
  }
  .diaconia-schedule-card>header,
  .diaconia-team-row,
  .diaconia-report-ready {
    align-items:flex-start;
    flex-direction:column;
  }
  .diaconia-schedule-card>header {
    padding:13px;
  }
  .diaconia-schedule-summary,
  .diaconia-checklist,
  .diaconia-report-form {
    padding:13px;
  }
  .diaconia-schedule-summary dl {
    grid-template-columns:1fr 1fr;
  }
  .diaconia-team-row {
    margin:0 13px;
  }
  .diaconia-team-row>div {
    justify-content:flex-start;
  }
  .diaconia-add-task {
    margin:0 13px 13px;
  }
  .diaconia-add-task form,
  .diaconia-check-item,
  .diaconia-report-form,
  .diaconia-substitute-fields {
    grid-template-columns:1fr;
  }
  .diaconia-substitute-fields,
  .diaconia-observation {
    grid-column:1;
  }
  .diaconia-substitute-fields>span {
    padding:0;
    text-align:center;
  }
  .diaconia-check-item>button,
  .diaconia-report-form button,
  .diaconia-report-ready a {
    width:100%;
  }
}

/* Automação Editorial V4.5 */
.editorial-shell {
  display:grid;
  gap:18px;
  color:var(--pilot-text);
}
.editorial-hero {
  position:relative;
  overflow:hidden;
  min-height:210px;
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:30px;
  padding:clamp(24px,4vw,42px);
  border:1px solid var(--pilot-line);
  border-radius:24px;
  background:
    radial-gradient(circle at 82% 8%,color-mix(in srgb,var(--pilot-purple) 28%,transparent),transparent 36%),
    linear-gradient(145deg,var(--pilot-surface),var(--pilot-surface-2));
  box-shadow:var(--pilot-shadow);
}
.editorial-hero::after {
  content:"IA";
  position:absolute;
  right:6%;
  top:-34px;
  color:color-mix(in srgb,var(--pilot-purple) 8%,transparent);
  font-size:190px;
  font-weight:950;
  letter-spacing:-18px;
  pointer-events:none;
}
.editorial-hero>div { position:relative; z-index:1; }
.editorial-hero h1 {
  max-width:700px;
  margin:8px 0 10px;
  font-size:clamp(31px,4vw,54px);
  line-height:1;
  letter-spacing:-.05em;
}
.editorial-hero>div>p:last-child {
  max-width:650px;
  margin:0;
  color:var(--pilot-muted);
  line-height:1.65;
}
.editorial-status-card {
  min-width:225px;
  display:grid;
  grid-template-columns:auto 1fr;
  align-items:center;
  gap:9px 12px;
  padding:16px;
  border:1px solid var(--pilot-line);
  border-radius:16px;
  background:color-mix(in srgb,var(--pilot-surface) 88%,transparent);
  backdrop-filter:blur(14px);
}
.editorial-status-card>span {
  width:12px;
  height:12px;
  border-radius:50%;
  box-shadow:0 0 0 5px color-mix(in srgb,currentColor 12%,transparent);
}
.editorial-status-card .is-on { color:var(--pilot-cyan); background:currentColor; }
.editorial-status-card .is-paused { color:#d4863c; background:currentColor; }
.editorial-status-card small,.editorial-status-card strong { display:block; }
.editorial-status-card small { color:var(--pilot-muted); font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:.1em; }
.editorial-status-card strong { margin-top:3px; font-size:13px; }
.editorial-status-card em {
  grid-column:1/-1;
  padding-top:9px;
  border-top:1px solid var(--pilot-line);
  color:var(--pilot-muted);
  font-size:11px;
  font-style:normal;
}
.editorial-safety-row {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px;
}
.editorial-safety-row article {
  display:flex;
  gap:12px;
  padding:16px;
  border:1px solid var(--pilot-line);
  border-radius:15px;
  background:var(--pilot-surface);
}
.editorial-safety-row article>span {
  flex:0 0 34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:10px;
  background:color-mix(in srgb,var(--pilot-purple) 15%,var(--pilot-surface));
  color:var(--pilot-purple);
  font-weight:900;
}
.editorial-safety-row strong { display:block; font-size:13px; }
.editorial-safety-row p { margin:5px 0 0; color:var(--pilot-muted); font-size:11px; line-height:1.5; }
.editorial-config,.editorial-queue {
  padding:clamp(18px,3vw,28px);
  border:1px solid var(--pilot-line);
  border-radius:20px;
  background:var(--pilot-surface);
}
.editorial-section-heading {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
  margin-bottom:20px;
}
.editorial-section-heading h2 { margin:4px 0 0; font-size:clamp(22px,3vw,30px); letter-spacing:-.03em; }
.editorial-switch {
  display:flex;
  align-items:center;
  gap:9px;
  font-size:12px;
  font-weight:850;
  cursor:pointer;
}
.editorial-switch input { position:absolute; opacity:0; pointer-events:none; }
.editorial-switch span {
  width:42px;
  height:24px;
  padding:3px;
  border-radius:999px;
  background:var(--pilot-line);
  transition:.2s ease;
}
.editorial-switch span::after {
  content:"";
  display:block;
  width:18px;
  height:18px;
  border-radius:50%;
  background:#fff;
  box-shadow:0 2px 8px rgba(0,0,0,.2);
  transition:.2s ease;
}
.editorial-switch input:checked+span { background:var(--pilot-cyan); }
.editorial-switch input:checked+span::after { transform:translateX(18px); }
.editorial-mode-grid {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:10px;
  margin-bottom:18px;
}
.editorial-mode-grid button {
  min-height:120px;
  display:grid;
  align-content:start;
  gap:5px;
  padding:15px;
  border:1px solid var(--pilot-line);
  border-radius:14px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  text-align:left;
}
.editorial-mode-grid button.selected {
  border-color:var(--pilot-purple);
  background:color-mix(in srgb,var(--pilot-purple) 10%,var(--pilot-surface));
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--pilot-purple) 35%,transparent);
}
.editorial-mode-grid button:disabled { opacity:.52; }
.editorial-mode-grid span { color:var(--pilot-purple); font-size:10px; font-weight:900; letter-spacing:.12em; }
.editorial-mode-grid strong { font-size:15px; }
.editorial-mode-grid small { color:var(--pilot-muted); line-height:1.45; }
.editorial-fields {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  margin-bottom:18px;
}
.editorial-fields label,.editorial-policy-columns>label,.editorial-save-row label {
  display:grid;
  gap:7px;
  color:var(--pilot-muted);
  font-size:10px;
  font-weight:850;
  text-transform:uppercase;
  letter-spacing:.08em;
}
.editorial-fields input,.editorial-fields select,.editorial-policy-columns textarea,.editorial-save-row input,
.editorial-review-actions input {
  width:100%;
  min-height:43px;
  padding:10px 12px;
  border:1px solid var(--pilot-line);
  border-radius:10px;
  outline:none;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  font-size:13px;
  font-weight:600;
  text-transform:none;
  letter-spacing:0;
}
.editorial-fields input:focus,.editorial-fields select:focus,.editorial-policy-columns textarea:focus,
.editorial-save-row input:focus,.editorial-review-actions input:focus { border-color:var(--pilot-purple); }
.editorial-choice-panel {
  display:grid;
  grid-template-columns:minmax(180px,.32fr) minmax(0,1fr);
  gap:20px;
  padding:18px 0;
  border-top:1px solid var(--pilot-line);
}
.editorial-choice-panel h3 { margin:0 0 5px; font-size:14px; }
.editorial-choice-panel p { margin:0; color:var(--pilot-muted); font-size:11px; line-height:1.5; }
.editorial-chip-grid { display:flex; flex-wrap:wrap; gap:8px; }
.editorial-chip-grid label {
  position:relative;
  padding:9px 11px;
  border:1px solid var(--pilot-line);
  border-radius:999px;
  background:var(--pilot-surface-2);
  color:var(--pilot-muted);
  font-size:11px;
  font-weight:750;
  cursor:pointer;
}
.editorial-chip-grid label.selected {
  border-color:color-mix(in srgb,var(--pilot-purple) 60%,var(--pilot-line));
  background:color-mix(in srgb,var(--pilot-purple) 13%,var(--pilot-surface));
  color:var(--pilot-text);
}
.editorial-chip-grid input { position:absolute; opacity:0; pointer-events:none; }
.editorial-policy-columns {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:12px;
  padding-top:18px;
  border-top:1px solid var(--pilot-line);
}
.editorial-policy-columns textarea { min-height:156px; resize:vertical; }
.editorial-policy-columns>div {
  padding:15px;
  border:1px solid color-mix(in srgb,#dc5d5d 35%,var(--pilot-line));
  border-radius:13px;
  background:color-mix(in srgb,#dc5d5d 6%,var(--pilot-surface));
}
.editorial-policy-columns>div>strong { font-size:12px; }
.editorial-policy-columns ul {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:7px 12px;
  margin:12px 0 0;
  padding:0;
  list-style:none;
  color:var(--pilot-muted);
  font-size:10px;
}
.editorial-policy-columns li::first-letter { color:#dc5d5d; font-weight:900; }
.editorial-image-option {
  display:flex;
  align-items:flex-start;
  gap:10px;
  margin-top:14px;
  padding:14px;
  border:1px solid var(--pilot-line);
  border-radius:12px;
  background:var(--pilot-surface-2);
}
.editorial-image-option input { margin-top:3px; accent-color:var(--pilot-purple); }
.editorial-image-option strong,.editorial-image-option small { display:block; }
.editorial-image-option strong { font-size:12px; }
.editorial-image-option small { margin-top:4px; color:var(--pilot-muted); line-height:1.45; }
.editorial-save-row {
  display:flex;
  align-items:end;
  justify-content:flex-end;
  gap:10px;
  margin-top:15px;
}
.editorial-save-row label { width:min(100%,280px); }
.editorial-save-row button,.editorial-section-heading>button,.editorial-review-actions button {
  min-height:43px;
  padding:10px 15px;
  border:0;
  border-radius:10px;
  background:var(--pilot-gradient);
  color:#fff;
  font-size:11px;
  font-weight:900;
  cursor:pointer;
}
.editorial-save-row button:disabled,.editorial-section-heading>button:disabled {
  cursor:not-allowed;
  filter:grayscale(.4);
  opacity:.55;
}
.editorial-draft-list { display:grid; gap:12px; }
.editorial-draft-list>article {
  padding:18px;
  border:1px solid var(--pilot-line);
  border-radius:15px;
  background:var(--pilot-surface-2);
}
.editorial-draft-list article>header {
  display:flex;
  justify-content:space-between;
  gap:12px;
}
.editorial-draft-list time { color:var(--pilot-muted); font-size:10px; }
.editorial-badge {
  display:inline-block;
  margin:0 5px 5px 0;
  padding:5px 7px;
  border-radius:999px;
  background:var(--pilot-surface);
  color:var(--pilot-muted);
  font-size:8px;
  font-weight:900;
  letter-spacing:.06em;
}
.editorial-badge.status-AGUARDANDO_REVISAO { background:color-mix(in srgb,#d9962e 16%,var(--pilot-surface)); color:#d9962e; }
.editorial-badge.status-APROVADO { background:color-mix(in srgb,var(--pilot-cyan) 16%,var(--pilot-surface)); color:var(--pilot-cyan); }
.editorial-badge.status-BLOQUEADO,.editorial-badge.status-REJEITADO { background:color-mix(in srgb,#dc5d5d 15%,var(--pilot-surface)); color:#dc5d5d; }
.editorial-community { margin:12px 0 5px!important; color:var(--pilot-purple)!important; font-size:10px!important; font-weight:850; text-transform:uppercase; letter-spacing:.08em; }
.editorial-draft-list h3 { margin:0 0 8px; font-size:18px; }
.editorial-draft-list article>p { margin:0; color:var(--pilot-muted); font-size:12px; line-height:1.65; }
.editorial-draft-list article>small { display:block; margin-top:10px; color:var(--pilot-muted); }
.editorial-similarity,.editorial-decision {
  margin-top:10px;
  padding:9px 11px;
  border-radius:9px;
  background:var(--pilot-surface);
  color:var(--pilot-muted);
  font-size:10px;
}
.editorial-review-actions {
  display:grid;
  grid-template-columns:minmax(200px,1fr) repeat(3,auto);
  gap:8px;
  margin-top:15px;
  padding-top:15px;
  border-top:1px solid var(--pilot-line);
}
.editorial-review-actions button { background:var(--pilot-surface); color:var(--pilot-text); border:1px solid var(--pilot-line); }
.editorial-review-actions button.approve { border:0; background:var(--pilot-gradient); color:#fff; }
.editorial-review-actions button.block { color:#dc5d5d; }
.editorial-draft-list footer { margin-top:12px; color:var(--pilot-muted); font-size:9px; }
.editorial-empty {
  padding:40px 20px;
  border:1px dashed var(--pilot-line);
  border-radius:14px;
  text-align:center;
}
.editorial-empty span { color:var(--pilot-purple); font-size:28px; }
.editorial-empty h3 { margin:10px 0 4px; }
.editorial-empty p { margin:0; color:var(--pilot-muted); font-size:11px; }
.editorial-loading { min-height:180px; grid-template-columns:auto 1fr; align-items:center; padding:24px; border:1px solid var(--pilot-line); border-radius:18px; background:var(--pilot-surface); }
.editorial-loading>span { width:42px; height:42px; border:3px solid var(--pilot-line); border-top-color:var(--pilot-purple); border-radius:50%; animation:editorial-spin .8s linear infinite; }
.editorial-loading p { margin:5px 0 0; color:var(--pilot-muted); font-size:11px; }
@keyframes editorial-spin { to { transform:rotate(360deg); } }
@media (max-width:980px) {
  .editorial-safety-row { grid-template-columns:1fr; }
  .editorial-fields { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .editorial-review-actions { grid-template-columns:1fr repeat(3,auto); }
  .editorial-review-actions input { grid-column:1/-1; }
}
@media (max-width:680px) {
  .editorial-shell { gap:12px; }
  .editorial-hero { min-height:290px; align-items:stretch; flex-direction:column; padding:22px; }
  .editorial-hero::after { right:-10px; top:40px; font-size:145px; }
  .editorial-status-card { min-width:0; margin-top:auto; }
  .editorial-config,.editorial-queue { padding:16px; border-radius:17px; }
  .editorial-section-heading { align-items:flex-start; }
  .editorial-mode-grid { grid-template-columns:1fr; }
  .editorial-mode-grid button { min-height:96px; }
  .editorial-fields,.editorial-policy-columns,.editorial-choice-panel { grid-template-columns:1fr; }
  .editorial-choice-panel { gap:12px; }
  .editorial-policy-columns ul { grid-template-columns:1fr; }
  .editorial-save-row { align-items:stretch; flex-direction:column; }
  .editorial-save-row label,.editorial-save-row button { width:100%; }
  .editorial-draft-list article>header { align-items:flex-start; flex-direction:column; }
  .editorial-review-actions { grid-template-columns:1fr 1fr; }
  .editorial-review-actions input,.editorial-review-actions .approve { grid-column:1/-1; }
}

/* Bloco 9 — continuidade, cancelamento, desativação e reativação */
.lifecycle-workspace {
  --lifecycle-green:#20c997;
  --lifecycle-amber:#f6b94c;
  --lifecycle-red:#ff6b6b;
  display:grid;
  gap:18px;
  color:var(--pilot-text);
}
.lifecycle-hero {
  position:relative;
  overflow:hidden;
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:18px;
  padding:28px;
  border:1px solid var(--pilot-line);
  border-radius:24px;
  background:
    radial-gradient(circle at 90% 0%,color-mix(in srgb,var(--pilot-purple) 24%,transparent),transparent 38%),
    linear-gradient(145deg,var(--pilot-surface),var(--pilot-surface-2));
}
.lifecycle-hero:after {
  content:"";
  position:absolute;
  right:-65px;
  bottom:-90px;
  width:210px;
  height:210px;
  border:1px solid color-mix(in srgb,var(--pilot-purple) 34%,transparent);
  border-radius:50%;
}
.lifecycle-hero>div { position:relative; z-index:1; max-width:670px; }
.lifecycle-hero h2 {
  margin:5px 0 9px;
  font-size:clamp(24px,3vw,38px);
  letter-spacing:-.045em;
}
.lifecycle-hero p:not(.pilot-kicker) {
  margin:0;
  color:var(--pilot-muted);
  line-height:1.65;
}
.lifecycle-status {
  position:relative;
  z-index:1;
  display:inline-flex;
  align-items:center;
  gap:8px;
  flex:none;
  padding:9px 12px;
  border:1px solid color-mix(in srgb,var(--lifecycle-green) 35%,var(--pilot-line));
  border-radius:999px;
  background:color-mix(in srgb,var(--lifecycle-green) 11%,var(--pilot-surface));
  color:var(--pilot-text);
  font-size:11px;
  font-weight:850;
}
.lifecycle-status i {
  width:8px;
  height:8px;
  border-radius:50%;
  background:var(--lifecycle-green);
  box-shadow:0 0 0 5px color-mix(in srgb,var(--lifecycle-green) 18%,transparent);
}
.lifecycle-flow {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:1px;
  overflow:hidden;
  border:1px solid var(--pilot-line);
  border-radius:18px;
  background:var(--pilot-line);
}
.lifecycle-flow article {
  display:flex;
  align-items:center;
  gap:11px;
  min-width:0;
  padding:15px;
  background:var(--pilot-surface);
}
.lifecycle-flow article>span,
.lifecycle-section-title>span {
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  flex:none;
  border-radius:11px;
  background:color-mix(in srgb,var(--pilot-purple) 15%,var(--pilot-surface-2));
  color:var(--pilot-purple);
  font-size:10px;
  font-weight:900;
}
.lifecycle-flow strong,.lifecycle-flow small { display:block; }
.lifecycle-flow strong { font-size:11px; }
.lifecycle-flow small { margin-top:3px; color:var(--pilot-muted); font-size:8px; line-height:1.35; }
.lifecycle-protection-grid {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px;
}
.lifecycle-protection-grid article {
  display:flex;
  align-items:flex-start;
  gap:13px;
  padding:17px;
  border:1px solid var(--pilot-line);
  border-radius:17px;
  background:var(--pilot-surface);
}
.lifecycle-icon {
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  flex:none;
  border-radius:12px;
  font-weight:900;
}
.lifecycle-icon.shield { color:var(--lifecycle-green); background:color-mix(in srgb,var(--lifecycle-green) 13%,var(--pilot-surface-2)); }
.lifecycle-icon.lock { color:var(--lifecycle-amber); background:color-mix(in srgb,var(--lifecycle-amber) 14%,var(--pilot-surface-2)); }
.lifecycle-icon.archive { color:var(--lifecycle-red); background:color-mix(in srgb,var(--lifecycle-red) 12%,var(--pilot-surface-2)); }
.lifecycle-protection-grid small,
.lifecycle-protection-grid strong { display:block; }
.lifecycle-protection-grid small { color:var(--pilot-muted); font-size:8px; text-transform:uppercase; letter-spacing:.08em; }
.lifecycle-protection-grid strong { margin:5px 0; font-size:13px; }
.lifecycle-protection-grid p { margin:0; color:var(--pilot-muted); font-size:9px; line-height:1.45; }
.lifecycle-request-layout {
  display:grid;
  grid-template-columns:minmax(0,1fr) 255px;
  gap:14px;
  align-items:start;
}
.lifecycle-request-form,.lifecycle-requests {
  padding:20px;
  border:1px solid var(--pilot-line);
  border-radius:20px;
  background:var(--pilot-surface);
}
.lifecycle-section-title {
  display:flex;
  align-items:center;
  gap:11px;
  margin-bottom:17px;
}
.lifecycle-section-title h3 { margin:0; font-size:17px; }
.lifecycle-section-title p { margin:3px 0 0; color:var(--pilot-muted); font-size:9px; }
.lifecycle-type-selector {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px;
  margin:0 0 14px;
  padding:0;
  border:0;
}
.lifecycle-type-selector legend {
  grid-column:1/-1;
  margin-bottom:7px;
  color:var(--pilot-text);
  font-size:10px;
  font-weight:850;
}
.lifecycle-type-selector label { position:relative; }
.lifecycle-type-selector input {
  position:absolute;
  opacity:0;
  pointer-events:none;
}
.lifecycle-type-selector span {
  min-height:64px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  padding:11px;
  border:1px solid var(--pilot-line);
  border-radius:12px;
  background:var(--pilot-surface-2);
  cursor:pointer;
}
.lifecycle-type-selector input:checked+span {
  border-color:var(--pilot-purple);
  box-shadow:inset 0 0 0 1px var(--pilot-purple);
  background:color-mix(in srgb,var(--pilot-purple) 11%,var(--pilot-surface));
}
.lifecycle-type-selector strong { font-size:11px; }
.lifecycle-type-selector small { margin-top:4px; color:var(--pilot-muted); font-size:8px; line-height:1.35; }
.lifecycle-form-grid {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:10px;
}
.lifecycle-form-grid label,
.lifecycle-critical-confirmation label {
  display:flex;
  flex-direction:column;
  gap:6px;
  color:var(--pilot-text);
  font-size:9px;
  font-weight:800;
}
.lifecycle-form-grid input,.lifecycle-form-grid select,.lifecycle-form-grid textarea,
.lifecycle-critical-confirmation input {
  width:100%;
  min-height:42px;
  padding:10px 11px;
  border:1px solid var(--pilot-line);
  border-radius:10px;
  outline:none;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  font:inherit;
  font-weight:600;
  resize:vertical;
}
.lifecycle-form-grid input:focus,.lifecycle-form-grid select:focus,.lifecycle-form-grid textarea:focus,
.lifecycle-critical-confirmation input:focus {
  border-color:var(--pilot-purple);
  box-shadow:0 0 0 3px color-mix(in srgb,var(--pilot-purple) 15%,transparent);
}
.lifecycle-wide { grid-column:1/-1; }
.lifecycle-critical-confirmation {
  display:grid;
  grid-template-columns:minmax(0,1.5fr) repeat(2,minmax(0,1fr));
  gap:10px;
  align-items:end;
  margin-top:12px;
  padding:13px;
  border:1px solid color-mix(in srgb,var(--lifecycle-amber) 34%,var(--pilot-line));
  border-radius:13px;
  background:color-mix(in srgb,var(--lifecycle-amber) 7%,var(--pilot-surface-2));
}
.lifecycle-critical-confirmation strong,.lifecycle-critical-confirmation small { display:block; }
.lifecycle-critical-confirmation strong { font-size:11px; }
.lifecycle-critical-confirmation small { margin-top:5px; color:var(--pilot-muted); font-size:8px; line-height:1.45; }
.lifecycle-primary {
  min-height:43px;
  margin-top:13px;
  padding:0 17px;
  border:0;
  border-radius:11px;
  background:var(--pilot-gradient);
  color:#fff;
  font-weight:850;
  cursor:pointer;
}
.lifecycle-primary:disabled { opacity:.55; cursor:wait; }
.lifecycle-side-note {
  position:sticky;
  top:88px;
  padding:20px;
  border:1px solid color-mix(in srgb,var(--lifecycle-red) 28%,var(--pilot-line));
  border-radius:20px;
  background:
    linear-gradient(160deg,color-mix(in srgb,var(--lifecycle-red) 8%,var(--pilot-surface)),var(--pilot-surface));
}
.lifecycle-side-note>span {
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  border-radius:12px;
  background:color-mix(in srgb,var(--lifecycle-red) 13%,var(--pilot-surface-2));
  color:var(--lifecycle-red);
  font-weight:950;
}
.lifecycle-side-note h3 { margin:15px 0 8px; font-size:16px; line-height:1.25; }
.lifecycle-side-note p,.lifecycle-side-note li { color:var(--pilot-muted); font-size:9px; line-height:1.55; }
.lifecycle-side-note ul { display:grid; gap:7px; margin:14px 0 0; padding-left:17px; }
.lifecycle-request-list { display:grid; gap:10px; }
.lifecycle-request-list>article {
  overflow:hidden;
  border:1px solid var(--pilot-line);
  border-radius:15px;
  background:var(--pilot-surface-2);
}
.lifecycle-request-list>article>header {
  display:flex;
  justify-content:space-between;
  gap:12px;
  align-items:flex-start;
  padding:14px 14px 10px;
}
.lifecycle-request-list header small { color:var(--pilot-muted); font-size:8px; }
.lifecycle-request-list h4 { margin:4px 0 0; font-size:14px; }
.lifecycle-decision {
  padding:6px 8px;
  border-radius:999px;
  background:color-mix(in srgb,var(--lifecycle-amber) 13%,var(--pilot-surface));
  color:var(--lifecycle-amber);
  font-size:8px;
  font-weight:900;
}
.decision-recusada { background:color-mix(in srgb,var(--lifecycle-red) 12%,var(--pilot-surface)); color:var(--lifecycle-red); }
.lifecycle-request-list dl {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:1px;
  margin:0;
  border-block:1px solid var(--pilot-line);
  background:var(--pilot-line);
}
.lifecycle-request-list dl>div { min-width:0; padding:10px 13px; background:var(--pilot-surface); }
.lifecycle-request-list dt { color:var(--pilot-muted); font-size:7px; text-transform:uppercase; letter-spacing:.08em; }
.lifecycle-request-list dd { overflow:hidden; margin:4px 0 0; font-size:9px; font-weight:800; text-overflow:ellipsis; white-space:nowrap; }
.lifecycle-request-list>article>p { margin:0; padding:12px 14px; color:var(--pilot-muted); font-size:9px; line-height:1.55; }
.lifecycle-blockers { display:grid; gap:5px; margin:0 14px 12px; padding:10px 10px 10px 26px; border-radius:10px; background:color-mix(in srgb,var(--lifecycle-red) 7%,var(--pilot-surface)); }
.lifecycle-blockers li { color:var(--pilot-muted); font-size:8px; line-height:1.4; }
.lifecycle-request-list footer {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  padding:10px 14px;
  border-top:1px solid var(--pilot-line);
}
.lifecycle-request-list footer>span { color:var(--pilot-muted); font-size:8px; }
.lifecycle-request-list footer>div { display:flex; flex-wrap:wrap; justify-content:flex-end; gap:6px; }
.lifecycle-request-list footer button {
  min-height:31px;
  padding:0 10px;
  border:1px solid var(--pilot-line);
  border-radius:8px;
  background:var(--pilot-surface);
  color:var(--pilot-text);
  font-size:8px;
  font-weight:850;
  cursor:pointer;
}
.lifecycle-request-list footer .lifecycle-approval {
  border-color:color-mix(in srgb,var(--pilot-purple) 45%,var(--pilot-line));
  color:var(--pilot-purple);
}
.lifecycle-empty {
  display:grid;
  place-items:center;
  min-height:170px;
  padding:24px;
  border:1px dashed var(--pilot-line);
  border-radius:14px;
  text-align:center;
}
.lifecycle-empty>span {
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:50%;
  background:color-mix(in srgb,var(--lifecycle-green) 13%,var(--pilot-surface-2));
  color:var(--lifecycle-green);
}
.lifecycle-empty strong { margin-top:10px; font-size:13px; }
.lifecycle-empty p { margin:5px 0 0; color:var(--pilot-muted); font-size:9px; }
.lifecycle-external-note {
  display:flex;
  align-items:flex-start;
  gap:12px;
  padding:14px;
  border:1px solid color-mix(in srgb,var(--pilot-purple) 30%,var(--pilot-line));
  border-radius:14px;
  background:color-mix(in srgb,var(--pilot-purple) 7%,var(--pilot-surface));
}
.lifecycle-external-note>span {
  padding:5px 7px;
  border-radius:6px;
  background:var(--pilot-purple);
  color:#fff;
  font-size:7px;
  font-weight:950;
  letter-spacing:.09em;
}
.lifecycle-external-note strong { display:block; font-size:11px; }
.lifecycle-external-note p { margin:4px 0 0; color:var(--pilot-muted); font-size:9px; line-height:1.5; }
.lifecycle-loading {
  min-height:260px;
  place-items:center;
  align-content:center;
  padding:30px;
  border:1px solid var(--pilot-line);
  border-radius:20px;
  background:var(--pilot-surface);
}
.lifecycle-loading p { color:var(--pilot-muted); font-size:10px; }
.lifecycle-support { margin-top:22px; }

@media (max-width:1000px) {
  .lifecycle-flow { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .lifecycle-protection-grid { grid-template-columns:1fr; }
  .lifecycle-request-layout { grid-template-columns:1fr; }
  .lifecycle-side-note { position:static; }
}
@media (max-width:680px) {
  .lifecycle-workspace { gap:12px; }
  .lifecycle-hero { display:grid; padding:20px; border-radius:18px; }
  .lifecycle-status { justify-self:start; }
  .lifecycle-flow { grid-template-columns:1fr; }
  .lifecycle-flow article { padding:12px; }
  .lifecycle-request-form,.lifecycle-requests { padding:14px; border-radius:16px; }
  .lifecycle-type-selector,.lifecycle-form-grid,.lifecycle-critical-confirmation {
    grid-template-columns:1fr;
  }
  .lifecycle-type-selector span { min-height:56px; }
  .lifecycle-wide { grid-column:1; }
  .lifecycle-primary { width:100%; }
  .lifecycle-request-list dl { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .lifecycle-request-list footer { align-items:flex-start; flex-direction:column; }
  .lifecycle-request-list footer>div { width:100%; justify-content:flex-start; }
  .lifecycle-request-list footer button { flex:1; }
  .lifecycle-external-note { flex-direction:column; }
