  height:40px;
  display:grid;
  place-items:center;
  border:1px solid var(--pilot-line);
  border-radius:12px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  cursor:pointer;
}
.pilot-notification-trigger>span { font-size:16px; line-height:1; }
.pilot-notification-trigger b {
  position:absolute;
  top:-6px;
  right:-6px;
  min-width:18px;
  height:18px;
  display:grid;
  place-items:center;
  padding:0 4px;
  border:2px solid var(--pilot-surface);
  border-radius:999px;
  background:#ee5454;
  color:#fff;
  font-size:8px;
}
.pilot-notification-backdrop {
  position:fixed;
  inset:0;
  z-index:169;
  border:0;
  background:rgba(0,0,0,.22);
}
.pilot-notification-panel {
  position:fixed;
  z-index:170;
  top:92px;
  right:20px;
  width:min(390px,calc(100vw - 28px));
  max-height:min(620px,calc(100vh - 95px));
  display:flex;
  flex-direction:column;
  overflow:hidden;
  border:1px solid var(--pilot-line);
  border-radius:19px;
  background:var(--pilot-surface);
