  justify-content:space-between;
  align-items:center;
  padding:18px;
  border-bottom:1px solid var(--pilot-line);
}
.pilot-notification-panel h2 { margin:0; font-size:22px; }
.pilot-notification-panel>header>button {
  width:34px;
  height:34px;
  border:1px solid var(--pilot-line);
  border-radius:10px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  cursor:pointer;
}
.notification-read-all {
  align-self:flex-end;
  margin:11px 15px 4px;
  border:0;
  background:none;
  color:var(--pilot-purple);
  font-size:9px;
  font-weight:850;
  cursor:pointer;
}
.pilot-notification-list { overflow-y:auto; padding:10px 14px; }
.pilot-notification-list article {
  display:grid;
  grid-template-columns:14px minmax(0,1fr) auto;
  gap:9px;
  padding:13px 8px;
  border-bottom:1px solid var(--pilot-line);
}
.pilot-notification-list article>span { color:var(--pilot-muted); font-size:8px; }
.pilot-notification-list article.unread>span { color:var(--pilot-purple); }
.pilot-notification-list strong { display:block; font-size:11px; }
.pilot-notification-list p { margin:5px 0; color:var(--pilot-muted); font-size:9px; line-height:1.5; }
.pilot-notification-list time { color:var(--pilot-muted); font-size:8px; }
.pilot-notification-list button {
  border:0;
  background:none;
  color:var(--pilot-purple);
  font-size:8px;
  font-weight:850;
  cursor:pointer;
}
.notification-empty { padding:30px 18px; color:var(--pilot-muted); text-align:center; font-size:10px; }
.pilot-notification-panel>footer {
  padding:13px 18px;
  border-top:1px solid var(--pilot-line);
  color:var(--pilot-muted);
  font-size:8px;
  line-height:1.45;
}
@media (max-width:760px) {
  .login-config-form { grid-template-columns:1fr; }
  .login-config-fields { grid-template-columns:1fr; }
  .login-config-form .login-config-wide { grid-column:1; }
  .login-signup-builder,.login-config-save,
  .login-config-form>.pilot-form-message { grid-column:1; }
  .login-config-preview { min-height:260px; }
  .login-signup-builder>header { align-items:flex-start; flex-wrap:wrap; }
  .login-signup-builder>header>button { width:100%; }
  .signup-field-list>article {
    grid-template-columns:30px minmax(0,1fr) 32px;
    align-items:end;
  }
  .signup-field-list>article>label { grid-column:2; }
  .signup-field-list>article>span { grid-column:1; grid-row:1; }
  .signup-field-list .signup-field-remove { grid-column:3; grid-row:1; }
  .login-config-save { align-items:stretch; flex-direction:column; }
  .signup-accounts>header { flex-direction:column; }
  .signup-account-list dl { grid-template-columns:1fr; }
  .pilot-notification-center {
    top:36px;
    right:14px;
  }
  .pilot-notification-panel {
    position:fixed;
    inset:88px 12px auto 12px;
    width:auto;
    max-height:min(580px,calc(100dvh - 176px));
  }
}
@media (prefers-reduced-motion:reduce) {
  .pilot-loader,.event-skeleton-grid span,.ministry-skeleton span { animation:none; }
}

