.signup-field-order button:disabled { opacity:.35; cursor:not-allowed; }

/* Variações reais do portal de login */
.login-shell.layout-image-right .login-showcase { order:2; }
.login-shell.layout-image-right .login-access { order:1; }
.login-shell.layout-centered {
  grid-template-columns:1fr;
  position:relative;
}
.login-shell.layout-centered .login-showcase {
  min-height:100vh;
  grid-area:1/1;
}
.login-shell.layout-centered .login-welcome {
  max-width:520px;
  margin-top:clamp(55px,9vh,100px);
}
.login-shell.layout-centered .login-access {
  z-index:2;
  grid-area:1/1;
  background:transparent;
}
.login-card { background:var(--login-card,#fff); }
.login-shell.card-glass .login-card {
  border-color:rgba(255,255,255,.3);
  background:color-mix(in srgb,var(--login-card,#fff) 82%,transparent);
  backdrop-filter:blur(20px);
}
.login-shell.card-minimal .login-card {
  border-color:transparent;
  border-radius:12px;
  box-shadow:none;
}

@media (max-width:900px) {
  .control-summary-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .signup-field-list>article {
    grid-template-columns:30px minmax(0,1fr) 60px 32px;
  }
  .signup-field-list>article>label { grid-column:2/-1; }
  .signup-field-list>article>span { grid-column:1; grid-row:1; }
  .signup-field-order { grid-column:3; grid-row:1; }
  .signup-field-list .signup-field-remove { grid-column:4; grid-row:1; }
}
@media (max-width:760px) {
  .platform-controls-heading { gap:10px; }
  .platform-controls-heading .owner-control-badge { align-self:flex-start; }
  .platform-control-tabs {
    display:flex;
    overflow-x:auto;
    scroll-snap-type:x mandatory;
    scrollbar-width:none;
  }
  .platform-control-tabs::-webkit-scrollbar { display:none; }
  .platform-control-tabs button {
    min-width:132px;
    flex:none;
    scroll-snap-align:start;
  }
  .control-summary-grid,
  .control-health-card ul { grid-template-columns:1fr; }
  .control-summary-card p { min-height:0; }
  .login-config-workspace { padding:13px; border-radius:16px; }
  .login-config-workspace>header { flex-direction:column; }
  .login-config-section>header { padding:14px; }
  .login-config-fields { padding:13px; gap:13px; }
  .login-config-fields>label:not(.login-config-toggle) {
    font-size:10px;
  }
  .login-config-form input:not([type="checkbox"]):not([type="color"]):not([type="range"]),
  .login-config-form select,
  .login-config-form textarea { min-height:48px; font-size:14px; }
  .login-config-toggle { font-size:11px; }
  .signup-field-list { padding:10px; }
  .signup-field-list>article {
    grid-template-columns:30px minmax(0,1fr) 60px 32px;
    padding:10px;
  }
  .signup-field-list>article>label {
    grid-column:1/-1;
    font-size:10px;
  }
  .signup-field-list>article>span { grid-column:1; grid-row:1; }
  .signup-field-order { grid-column:3; grid-row:1; }
  .signup-field-list .signup-field-remove { grid-column:4; grid-row:1; }
  .login-config-preview { padding:20px; }
  .owner-access-banner,
  .owner-readonly-banner { padding:13px; }
  .login-shell.layout-image-right .login-showcase,
  .login-shell.layout-image-right .login-access { order:initial; }
  .login-shell.layout-centered .login-showcase {
    min-height:350px;
    grid-area:auto;
  }
  .login-shell.layout-centered .login-access {
    grid-area:auto;
    background:#f6f8f9;
  }
}

