}
.community-composer>summary {
  display:flex;
  align-items:center;
  gap:12px;
  padding:17px 20px;
  cursor:pointer;
}
.community-composer>summary>span {
  width:37px;
  height:37px;
  display:grid;
  place-items:center;
  border-radius:12px;
  background:color-mix(in srgb,var(--pilot-purple) 11%,var(--pilot-surface));
  color:var(--pilot-purple);
  font-size:20px;
}
.community-composer>summary strong,
.community-composer>summary small { display:block; }
.community-composer>summary strong { font-size:13px; }
.community-composer>summary small { margin-top:3px; color:var(--pilot-muted); font-size:9px; }
.community-composer form {
  grid-template-columns:repeat(2,minmax(0,1fr));
  padding:0 20px 20px;
}
.community-composer .composer-wide,
.community-composer .composer-share { grid-column:1/-1; }
.community-composer .composer-share {
  min-height:45px;
  display:flex;
  align-items:center;
  grid-template-columns:auto 1fr;
  padding:10px 13px;
  border:1px solid var(--pilot-line);
  border-radius:12px;
  background:var(--pilot-surface-2);
}
.community-composer .composer-share input { width:17px; min-height:17px; margin:0 9px 0 0; }
.community-home-grid {
  display:grid;
  grid-template-columns:minmax(0,1.5fr) minmax(270px,.58fr);
  align-items:start;
  gap:18px;
}
.community-feed-panel>header {
  display:flex;
  align-items:end;
  justify-content:space-between;
  gap:15px;
  margin-bottom:13px;
}
.community-feed-panel>header h2 { margin:0; font-size:24px; }
.community-feed-panel>header>span {
  color:var(--pilot-muted);
  font-size:9px;
  font-weight:800;
}
.community-feed-list { display:grid; gap:16px; }

.feed-pagination-controls {
  display: grid;
  justify-items: center;
  gap: 10px;
  padding: 18px 0 4px;
  text-align: center;
}

.feed-pagination-controls > button,
.feed-pagination-controls p button {
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--white);
  color: var(--ink);
  padding: 10px 20px;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
}

.feed-pagination-controls > button:hover,
.feed-pagination-controls p button:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.feed-pagination-controls button:disabled {
  cursor: wait;
  opacity: .65;
}

.feed-pagination-controls p,
.feed-pagination-controls small {
  color: var(--muted);
  line-height: 1.55;
}

.feed-load-sentinel {
  width: 100%;
  height: 1px;
}

.feed-skeleton {
  display: grid;
  gap: 12px;
  min-height: 180px;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--white);
  overflow: hidden;
}

.feed-skeleton span,
.feed-image-placeholder {
  display: block;
  border-radius: 10px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--white) 85%, transparent),
    color-mix(in srgb, var(--teal) 14%, var(--white)),
    color-mix(in srgb, var(--white) 85%, transparent)
  );
  background-size: 200% 100%;
  animation: feed-shimmer 1.25s ease-in-out infinite;
}

.feed-skeleton span:first-child { width: 46%; height: 18px; }
.feed-skeleton span:nth-child(2) { width: 92%; height: 15px; }
.feed-skeleton span:nth-child(3) { width: 70%; height: 15px; }
.feed-skeleton small { color: var(--muted); }

.feed-responsive-image {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  margin: 0;
  overflow: hidden;
  background: var(--white);
}

.feed-responsive-image .feed-image-placeholder {
  position: absolute;
  inset: 0;
}

.feed-responsive-image img {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity .24s ease;
}

.feed-responsive-image.is-loaded img { opacity: 1; }
.feed-responsive-image.is-loaded .feed-image-placeholder { display: none; }

@keyframes feed-shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .feed-skeleton span,
  .feed-image-placeholder { animation: none; }
  .feed-responsive-image img { transition: none; }
}

@media (max-width: 720px) {
  .feed-pagination-controls {
    padding-bottom: 88px;
  }

  .feed-pagination-controls > button {
    width: 100%;
  }

  .feed-responsive-image {
    aspect-ratio: 4 / 3;
  }
}

/* Conversas privadas: isoladas por comunidade e ciclo mensal. */
.private-chat-heading { display:flex; align-items:flex-end; justify-content:space-between; gap:20px; }
.private-chat-heading > span { border:1px solid var(--pilot-line); border-radius:999px; padding:9px 14px; color:var(--pilot-muted); font-size:12px; font-weight:800; }
.private-chat-layout { display:grid; grid-template-columns:minmax(280px, .78fr) minmax(0, 1.7fr); min-height:650px; border:1px solid var(--pilot-line); border-radius:28px; overflow:hidden; background:var(--pilot-surface); box-shadow:0 24px 65px rgb(9 20 38 / .1); }
.private-chat-sidebar { border-right:1px solid var(--pilot-line); padding:18px; background:var(--pilot-surface-2); min-width:0; }
.private-chat-sidebar > label input { width:100%; min-height:46px; border:1px solid var(--pilot-line); border-radius:14px; background:var(--pilot-surface); color:var(--pilot-text); padding:0 14px; }
.private-chat-conversations, .private-chat-people { display:grid; gap:8px; margin-top:16px; }
.private-chat-people { padding-top:16px; border-top:1px solid var(--pilot-line); }
.private-chat-people > strong { color:var(--pilot-muted); font-size:11px; letter-spacing:.1em; text-transform:uppercase; }
.private-chat-conversations button, .private-chat-people button { width:100%; display:grid; grid-template-columns:42px minmax(0,1fr) auto; align-items:center; gap:10px; border:1px solid transparent; border-radius:16px; padding:10px; text-align:left; background:transparent; color:var(--pilot-text); cursor:pointer; }
.private-chat-conversations button:hover, .private-chat-conversations button.active, .private-chat-people button:hover { border-color:var(--pilot-line); background:var(--pilot-surface); }
.private-chat-conversations button > div, .private-chat-people button > span { min-width:0; display:grid; }
.private-chat-conversations strong, .private-chat-people strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.private-chat-conversations small, .private-chat-people small { color:var(--pilot-muted); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.private-chat-conversations p { margin:4px 0 0; color:var(--pilot-muted); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.private-chat-conversations button > b { min-width:24px; height:24px; display:grid; place-items:center; border-radius:999px; background:var(--pilot-primary); color:white; font-size:11px; }
.private-chat-avatar { width:42px; height:42px; display:grid; place-items:center; overflow:hidden; border-radius:14px; background:linear-gradient(135deg,var(--pilot-primary),var(--pilot-accent)); color:white; font-weight:900; }
.private-chat-avatar img { width:100%; height:100%; object-fit:cover; }
.private-chat-thread { display:flex; flex-direction:column; min-width:0; background:var(--pilot-surface); }
.private-chat-thread > header { display:flex; align-items:center; gap:11px; min-height:76px; padding:14px 20px; border-bottom:1px solid var(--pilot-line); }
.private-chat-thread > header > button { display:none; border:0; background:transparent; color:var(--pilot-text); font-size:22px; }
.private-chat-thread > header > div { display:grid; }
.private-chat-thread > header small { color:var(--pilot-muted); }
.private-chat-messages { flex:1; display:flex; flex-direction:column; gap:12px; overflow:auto; padding:24px; background:linear-gradient(180deg,color-mix(in srgb,var(--pilot-surface-2) 70%,transparent),var(--pilot-surface)); }
.private-chat-messages article { align-self:flex-start; max-width:min(76%,650px); padding:12px 14px; border:1px solid var(--pilot-line); border-radius:18px 18px 18px 5px; background:var(--pilot-surface); color:var(--pilot-text); }
.private-chat-messages article.own { align-self:flex-end; border-radius:18px 18px 5px 18px; background:color-mix(in srgb,var(--pilot-primary) 14%,var(--pilot-surface)); }
.private-chat-messages small, .private-chat-messages time { color:var(--pilot-muted); font-size:10px; }
.private-chat-messages p { margin:5px 0; white-space:pre-wrap; overflow-wrap:anywhere; }
.private-chat-thread > form { display:grid; grid-template-columns:1fr auto; gap:10px; padding:16px; border-top:1px solid var(--pilot-line); }
.private-chat-thread textarea { resize:none; border:1px solid var(--pilot-line); border-radius:15px; background:var(--pilot-surface-2); color:var(--pilot-text); padding:12px; }
.private-chat-thread form button { border:0; border-radius:14px; padding:0 24px; background:linear-gradient(135deg,var(--pilot-primary),var(--pilot-accent)); color:white; font-weight:900; }
.private-chat-empty { margin:auto; padding:30px; text-align:center; color:var(--pilot-muted); }
.private-chat-empty span { display:block; font-size:36px; }
.private-chat-empty strong { display:block; margin:10px 0; color:var(--pilot-text); font-size:20px; }
.notification-sender-meta { display:block; margin-top:3px; color:var(--pilot-muted); font-size:10px; }

.private-chat-dialog-backdrop { position:fixed; inset:0; z-index:190; display:grid; place-items:end; padding:18px; pointer-events:none; }
.private-chat-dialog { width:min(430px,calc(100vw - 36px)); height:min(610px,calc(100dvh - 110px)); display:grid; grid-template-rows:auto minmax(0,1fr) auto auto; overflow:hidden; border:1px solid var(--pilot-line); border-radius:22px; background:var(--pilot-surface); color:var(--pilot-text); box-shadow:0 28px 80px rgb(0 0 0 / .32); pointer-events:auto; transition:width .18s ease,height .18s ease; }
.private-chat-dialog.maximized { width:min(880px,calc(100vw - 36px)); height:calc(100dvh - 36px); }
.private-chat-dialog.minimized { width:min(360px,calc(100vw - 36px)); height:auto; grid-template-rows:auto; }
.private-chat-dialog>header { display:flex; align-items:start; justify-content:space-between; gap:16px; padding:18px 20px; border-bottom:1px solid var(--pilot-line); }
.private-chat-dialog>header>div { display:grid; gap:3px; }
.private-chat-dialog>header small { color:var(--pilot-purple); font-size:9px; font-weight:900; letter-spacing:.12em; }
.private-chat-dialog>header strong { font-size:18px; }
.private-chat-dialog>header span { color:var(--pilot-muted); font-size:11px; }
.private-chat-window-actions { display:flex; align-items:center; gap:5px; }
.private-chat-window-actions>button { width:32px; height:32px; border:1px solid var(--pilot-line); border-radius:9px; background:var(--pilot-surface-2); color:var(--pilot-text); font-size:16px; cursor:pointer; }
.private-chat-window-actions>button:hover { border-color:var(--pilot-primary); color:var(--pilot-primary); }
.private-chat-dialog-messages { min-height:0; display:flex; flex-direction:column; gap:10px; overflow:auto; padding:18px; background:linear-gradient(180deg,var(--pilot-surface-2),var(--pilot-surface)); }
.private-chat-dialog-messages>p,.private-chat-dialog-empty { margin:auto; padding:24px; color:var(--pilot-muted); text-align:center; }
.private-chat-dialog-messages article { align-self:flex-start; max-width:78%; padding:10px 12px; border:1px solid var(--pilot-line); border-radius:15px 15px 15px 4px; background:var(--pilot-surface); }
.private-chat-dialog-messages article.own { align-self:flex-end; border-radius:15px 15px 4px 15px; background:color-mix(in srgb,var(--pilot-primary) 15%,var(--pilot-surface)); }
.private-chat-dialog-messages article p { margin:0 0 5px; white-space:pre-wrap; overflow-wrap:anywhere; }
.private-chat-dialog-messages article time { color:var(--pilot-muted); font-size:9px; }
.private-chat-dialog-error { margin:0; padding:8px 18px; background:#fff0f2; color:#b13b4a; font-size:11px; }
.private-chat-dialog>form { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:10px; padding:14px; border-top:1px solid var(--pilot-line); background:var(--pilot-surface); }
.private-chat-dialog>form textarea { width:100%; resize:none; border:1px solid var(--pilot-line); border-radius:14px; background:var(--pilot-surface-2); color:var(--pilot-text); padding:11px 12px; }
.private-chat-dialog>form button { min-width:100px; border:0; border-radius:14px; background:linear-gradient(135deg,var(--pilot-primary),var(--pilot-accent)); color:#fff; font-weight:900; cursor:pointer; opacity:1; }
.private-chat-dialog>form button:disabled { opacity:.55; cursor:not-allowed; }
.editorial-schedule-password { margin-top:4px; }
.editorial-schedule-password small { color:var(--pilot-muted); line-height:1.45; }
.editorial-schedule-feedback { margin:10px 0 0; padding:11px 13px; border:1px solid var(--pilot-line); border-radius:11px; background:var(--pilot-surface-2); color:var(--pilot-text); font-size:12px; }

@media (max-width: 760px) {
  .private-chat-heading { align-items:flex-start; }
  .private-chat-heading > span { display:none; }
  .private-chat-layout { display:block; min-height:calc(100dvh - 250px); border-radius:22px; }
  .private-chat-sidebar { min-height:560px; border-right:0; }
  .private-chat-layout.has-thread .private-chat-sidebar { display:none; }
  .private-chat-thread { min-height:560px; }
  .private-chat-layout:not(.has-thread) .private-chat-thread { display:none; }
  .private-chat-thread > header > button { display:block; }
  .private-chat-messages { padding:16px 12px; }
  .private-chat-messages article { max-width:88%; }
  .private-chat-thread > form { position:sticky; bottom:0; grid-template-columns:1fr auto; background:var(--pilot-surface); padding-bottom:max(12px,env(safe-area-inset-bottom)); }
  .private-chat-thread form button { padding:0 16px; }
  .private-chat-dialog-backdrop { padding:0; place-items:stretch; }
  .private-chat-dialog,.private-chat-dialog.maximized { width:100%; height:100dvh; border-radius:0; }
  .private-chat-dialog.minimized { width:calc(100% - 24px); height:auto; margin:12px; border-radius:18px; align-self:end; }
  .private-chat-dialog>form { padding:10px 12px max(10px,env(safe-area-inset-bottom)); }
  .private-chat-dialog>form button { min-width:86px; min-height:48px; }
}

/* Bloco 13 — Pessoas, membros e permissões */
.people-workspace {
  display: grid;
  gap: 20px;
}

.people-heading {
  align-items: flex-start;
}

.people-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.people-metrics article {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 92px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--white);
  box-shadow: var(--shadow);
}

.people-metrics article > span,
.people-avatar {
  display: grid;
  place-items: center;
  flex: 0 0 42px;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  color: var(--teal);
  background: var(--teal-soft);
  font-weight: 900;
}

.people-metrics small,
.people-card small,
.self-profile-card small {
  color: var(--muted);
}

.people-metrics strong {
  display: block;
  margin-top: 3px;
  color: var(--ink);
  font-size: 22px;
}

.people-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--white);
}

.people-toolbar > label {
  flex: 1;
  max-width: 430px;
}

.people-toolbar input[type="search"] {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--canvas);
  color: var(--ink);
  padding: 10px 14px;
}

.people-tabs {
  display: flex;
  gap: 6px;
}

.people-tabs button {
  min-height: 42px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: var(--muted);
  padding: 9px 14px;
  font-weight: 800;
  cursor: pointer;
}

.people-tabs button.active {
  color: var(--white);
  background: linear-gradient(135deg, var(--navy-2), var(--teal));
}

.people-tabs button span {
  margin-left: 6px;
  opacity: .78;
}

.people-list {
  display: grid;
  gap: 10px;
}

.people-card {
  display: grid;
  grid-template-columns: auto minmax(240px, 1fr) minmax(150px, .45fr) auto;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--white);
}

.people-card-main,
.people-card-main > div:first-child,
.people-card-contact {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.people-card-main strong,
.people-card-main small,
.people-card-contact span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.people-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.people-badges span,
.people-badges em {
  border-radius: 999px;
  padding: 4px 8px;
  color: var(--navy);
  background: var(--teal-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
}

.people-badges em {
  color: #714cff;
  background: color-mix(in srgb, #714cff 12%, var(--white));
}

.people-badges .member-badge {
  color: var(--muted);
  background: var(--canvas);
}

.people-card > button,
.people-form-actions button,
.self-profile-card form > button {
  min-height: 42px;
  border: 0;
  border-radius: 11px;
  background: var(--navy);
  color: var(--white);
  padding: 9px 14px;
  font-weight: 850;
  cursor: pointer;
}

.people-loading {
  min-height: 240px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--white);
  color: var(--muted);
}

.people-modal-backdrop {
  position: fixed;
  z-index: 120;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(3, 10, 18, .72);
  backdrop-filter: blur(8px);
}

.people-modal {
  width: min(720px, 100%);
  max-height: min(820px, calc(100dvh - 32px));
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: var(--white);
  color: var(--ink);
  box-shadow: 0 28px 80px rgba(0, 0, 0, .28);
}

.people-modal > header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  padding: 22px;
  border-bottom: 1px solid var(--line);
}

.people-modal h2,
.people-modal p {
  margin: 4px 0 0;
}

.people-modal > header > button {
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--canvas);
  color: var(--ink);
  font-size: 22px;
  cursor: pointer;
}

.people-role-form {
  display: grid;
  gap: 18px;
  padding: 22px;
}

.people-official-toggle {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--canvas);
}

.people-official-toggle span {
  display: grid;
  gap: 4px;
}

.people-role-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.people-role-grid label,
.people-role-form fieldset {
  display: grid;
  gap: 7px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.people-role-grid select {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--canvas);
  color: var(--ink);
  padding: 9px 11px;
}

.people-role-form fieldset {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px;
}

.people-permission-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.people-permission-grid label {
  display: flex;
  gap: 8px;
  align-items: center;
  min-height: 38px;
  padding: 8px 10px;
  border-radius: 9px;
  background: var(--canvas);
  color: var(--ink);
  font-size: 11px;
}

.people-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.people-form-actions button:last-child {
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink);
}

.self-profile-card {
  display: grid;
  grid-template-columns: minmax(180px, .45fr) minmax(0, 1.55fr);
  gap: 18px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: var(--white);
}

.self-profile-card > aside {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  padding: 28px 16px;
  border-radius: 17px;
  background:
    radial-gradient(circle at 80% 10%, color-mix(in srgb, var(--teal) 28%, transparent), transparent 45%),
    var(--canvas);
  text-align: center;
}

.self-profile-card > aside > .self-profile-avatar {
  display: grid;
  place-items: center;
  width: 72px;
  height: 72px;
  border-radius: 24px;
  background: linear-gradient(135deg, var(--navy-2), var(--teal));
  color: var(--white);
  font-size: 24px;
  font-weight: 900;
}

.self-profile-card > aside em {
  border-radius: 999px;
  padding: 5px 10px;
  background: var(--teal-soft);
  color: var(--teal);
  font-size: 11px;
  font-style: normal;
  font-weight: 900;
}

@media (max-width: 900px) {
  .people-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .people-card {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .people-card-contact {
    display: none;
  }
}

@media (max-width: 640px) {
  .people-workspace {
    gap: 14px;
  }

  .people-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .people-metrics article {
    min-height: 80px;
    padding: 12px;
  }

  .people-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .people-toolbar > label {
    max-width: none;
  }

  .people-tabs {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .people-card {
    grid-template-columns: auto minmax(0, 1fr);
    padding: 13px;
  }

  .people-card > button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .people-modal-backdrop {
    align-items: end;
    padding: 0;
  }

  .people-modal {
    max-height: 92dvh;
    border-radius: 24px 24px 0 0;
  }

  .people-role-grid,
  .people-permission-grid,
  .self-profile-card {
    grid-template-columns: 1fr;
  }

  .self-profile-card {
    padding: 12px;
  }

  .people-form-actions {
    flex-direction: column;
  }

  .people-form-actions button {
    width: 100%;
  }
}
