}
.visitor-registration-section { min-width:0; grid-column:1/-1; border:1px solid var(--pilot-line); border-radius:14px; background:var(--pilot-surface-2); overflow:hidden; }
.visitor-registration-section>summary { min-height:58px; display:flex; align-items:center; justify-content:space-between; gap:12px; padding:9px 12px; color:var(--pilot-text); cursor:pointer; list-style:none; }
.visitor-registration-section>summary::-webkit-details-marker { display:none; }
