.visitor-registration-section>summary b { grid-row:1/3; width:34px; height:34px; display:grid; place-items:center; border-radius:10px; background:color-mix(in srgb,var(--pilot-purple) 12%,var(--pilot-surface)); color:var(--pilot-purple); font-size:10px; }
