.diaconia-flow strong,.diaconia-flow small { display:block; }
.diaconia-flow strong { color:var(--pilot-text); font-size:10px; }
.diaconia-flow small {
  margin-top:3px;
  color:var(--pilot-muted);
  font-size:8px;
  line-height:1.4;
}
.diaconia-category-filter {
  display:flex;
  gap:7px;
  overflow-x:auto;
  padding:2px 0 7px;
  scrollbar-width:thin;
}
.diaconia-category-filter button {
  min-height:36px;
  flex:none;
  padding:0 13px;
  border:1px solid var(--pilot-line);
  border-radius:999px;
  background:var(--pilot-surface);
  color:var(--pilot-muted);
  font-size:9px;
  font-weight:850;
  cursor:pointer;
}
.diaconia-category-filter button.active {
  border-color:color-mix(in srgb,var(--pilot-purple) 58%,var(--pilot-line));
  background:color-mix(in srgb,var(--pilot-purple) 11%,var(--pilot-surface));
  color:var(--pilot-purple);
}

.resource-edit-card {
  overflow:hidden;
  border:1px solid var(--pilot-line);
  border-radius:13px;
  background:var(--pilot-surface-2);
}
.resource-edit-card>summary {
  min-height:56px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:12px;
  cursor:pointer;
  list-style:none;
}
.resource-edit-card>summary::-webkit-details-marker { display:none; }
.resource-edit-card>summary>span { min-width:0; }
.resource-edit-card>summary strong,
.resource-edit-card>summary small { display:block; }
.resource-edit-card>summary em {
  color:var(--pilot-purple);
  font-size:8px;
  font-style:normal;
  font-weight:900;
}
.resource-edit-form {
  grid-template-columns:repeat(2,minmax(0,1fr));
  padding:14px;
  border-top:1px solid var(--pilot-line);
}
.resource-edit-form .resource-wide-field,
.resource-edit-actions,
.resource-version-note { grid-column:1/-1; }
.resource-edit-actions {
  display:flex;
  flex-wrap:wrap;
  gap:8px;
}
.custom-field-builder {
  display:grid;
  gap:10px;
  min-width:0;
  margin:0;
  padding:14px;
  border:1px solid var(--pilot-line);
  border-radius:13px;
  background:color-mix(in srgb,var(--pilot-purple) 4%,var(--pilot-surface-2));
}
.custom-field-builder legend {
  padding:0 6px;
  color:var(--pilot-text);
  font-size:10px;
  font-weight:900;
}
.custom-field-builder>p {
  margin:0;
  color:var(--pilot-muted);
  font-size:8px;
  line-height:1.5;
}
.custom-field-row {
  display:grid;
  grid-template-columns:minmax(130px,1fr) minmax(115px,.7fr) minmax(150px,1fr) auto auto;
  align-items:end;
  gap:8px;
  padding:11px;
  border:1px solid var(--pilot-line);
  border-radius:11px;
  background:var(--pilot-surface);
}
.custom-field-row label {
  display:grid;
  gap:5px;
  color:var(--pilot-muted);
  font-size:8px;
  font-weight:800;
}
.custom-field-row .custom-field-required {
  display:flex;
  align-items:center;
  min-height:40px;
}
.custom-field-row .custom-field-required input {
  width:16px;
  min-height:16px;
}
.custom-schedule-field {
  min-width:0;
}
.resource-version-note {
  color:var(--pilot-muted);
  font-size:8px;
  line-height:1.5;
}

.requests-workspace { display:grid; gap:16px; }
.request-form {
  grid-template-columns:repeat(2,minmax(0,1fr));
  padding:0 18px 18px;
}
.request-form .request-wide-field,
.request-form>button { grid-column:1/-1; }
.request-list { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.request-list>article {
  min-width:0;
  display:grid;
  gap:10px;
  padding:17px;
  border:1px solid var(--pilot-line);
  border-radius:17px;
  background:var(--pilot-surface);
}
.request-list>article>header,
.request-list>article>footer,
.request-actions {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}
.request-list>article>header>span {
  color:var(--pilot-purple);
  font-size:8px;
  font-weight:950;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.request-status {
  padding:5px 8px;
  border-radius:999px;
  background:var(--pilot-surface-2);
  color:var(--pilot-muted);
  font-size:8px;
  font-style:normal;
  font-weight:850;
}
.request-status.status-em_analise { color:#c17a18; }
.request-status.status-concluida { color:#249269; }
.request-list h2 { margin:0; color:var(--pilot-text); font-size:17px; }
.request-list p { margin:0; color:var(--pilot-muted); font-size:10px; line-height:1.6; }
.request-list footer {
  padding-top:10px;
  border-top:1px solid var(--pilot-line);
  color:var(--pilot-muted);
  font-size:8px;
}
.request-actions { justify-content:flex-start; }
.request-actions button {
  min-height:36px;
  padding:0 12px;
  border:1px solid var(--pilot-line);
  border-radius:10px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  font-size:8px;
  font-weight:850;
  cursor:pointer;
}

.pilot-mobile-list-icon {
  width:22px;
  height:18px;
  display:flex !important;
  flex-direction:column;
  justify-content:space-between;
}
.pilot-mobile-list-icon i {
  width:100%;
  height:2px;
  border-radius:99px;
  background:currentColor;
}
.pilot-mobile-menu-content { display:grid; gap:16px; }
.pilot-mobile-community-switcher {
  display:grid;
  gap:10px;
  padding:15px;
  border:1px solid var(--pilot-line);
  border-radius:17px;
  background:var(--pilot-surface-2);
}
.pilot-mobile-community-switcher strong,
.pilot-mobile-community-switcher small { display:block; }
.pilot-mobile-community-switcher>div:first-child>strong {
  margin-top:4px;
  color:var(--pilot-text);
  font-size:13px;
}
.pilot-mobile-community-switcher>div:first-child>small {
  margin-top:3px;
  color:var(--pilot-muted);
  font-size:8px;
  line-height:1.45;
}
.pilot-mobile-community-switcher input {
  width:100%;
  min-height:42px;
  padding:0 12px;
  border:1px solid var(--pilot-line);
  border-radius:11px;
  background:var(--pilot-surface);
  color:var(--pilot-text);
}
.pilot-mobile-community-list {
  max-height:190px;
  display:grid;
  gap:6px;
  overflow-y:auto;
}
.pilot-mobile-community-list>button {
  display:grid;
  grid-template-columns:34px minmax(0,1fr);
  align-items:center;
  gap:9px;
  padding:8px;
  border:1px solid var(--pilot-line);
  border-radius:11px;
  background:var(--pilot-surface);
  color:var(--pilot-text);
  text-align:left;
  cursor:pointer;
}
.pilot-mobile-community-list>button>span {
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:10px;
  background:var(--pilot-gradient);
  color:#fff;
  font-size:7px;
  font-weight:950;
}
.pilot-mobile-community-list>button small {
  margin-top:2px;
  color:var(--pilot-muted);
  font-size:7px;
}
.pilot-mobile-community-list>button.active {
  border-color:color-mix(in srgb,var(--pilot-purple) 48%,var(--pilot-line));
}
.pilot-mobile-community-switcher>a {
  color:var(--pilot-purple);
  font-size:9px;
  font-weight:850;
  text-decoration:none;
}
.pilot-mobile-action-grid {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:10px;
}
.pilot-mobile-action-grid>button {
  min-height:92px;
  display:flex;
  align-items:center;
  gap:12px;
  padding:14px;
  border:1px solid var(--pilot-line);
  border-radius:16px;
  background:var(--pilot-surface-2);
  color:var(--pilot-text);
  text-align:left;
  cursor:pointer;
}
.pilot-mobile-action-grid>button>span {
  width:38px;
  height:38px;
  flex:none;
  display:grid;
  place-items:center;
  border-radius:12px;
  background:var(--pilot-gradient);
  color:#fff;
  font-weight:950;
}
.pilot-mobile-action-grid strong,
.pilot-mobile-action-grid small { display:block; }
.pilot-mobile-action-grid strong { font-size:10px; }
.pilot-mobile-action-grid small {
  margin-top:3px;
  color:var(--pilot-muted);
  font-size:8px;
  line-height:1.4;
}

@media (max-width:900px) {
  .diaconia-flow { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .custom-field-row { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .custom-field-row .custom-field-required,
  .custom-field-row>button { align-self:end; }
}
@media (max-width:680px) {
  .pilot-topbar {
    grid-template-columns:auto minmax(0,1fr);
    padding:10px 14px;
  }
  .pilot-account-cluster { min-width:0; }
  .pilot-user-trigger {
    width:44px;
    padding:5px;
  }
  .pilot-user-trigger>span { width:32px; height:32px; }
  .pilot-user-trigger>strong { display:none; }
  .pilot-notification-panel {
    position:fixed;
    inset:82px 10px auto 10px;
    width:auto;
  }
  .pilot-mobile-nav>button>.pilot-mobile-list-icon {
    font-size:inherit;
  }
  .pilot-mobile-sheet>header h2 { font-size:22px; }
  .diaconia-flow { grid-template-columns:1fr; }
  .diaconia-flow li { padding:12px; }
  .resource-edit-form,
  .request-form,
  .request-list,
  .custom-field-row { grid-template-columns:1fr; }
  .resource-edit-form .resource-wide-field,
  .resource-edit-actions,
  .resource-version-note,
  .request-form .request-wide-field,
  .request-form>button { grid-column:1; }
  .request-form>button { width:100%; }
  .pilot-mobile-action-grid { grid-template-columns:1fr; }
  .pilot-mobile-action-grid>button { min-height:74px; }
}
/* V4.5 — Smart UI e Editor Visual Avançado */
.smart-layout {
  --smart-accent: var(--pilot-accent, #21c7bf);
  margin: 0 0 28px;
  padding: 24px;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .22));
  border-radius: 28px;
  background:
    radial-gradient(circle at 92% 0%, color-mix(in srgb, var(--smart-accent) 18%, transparent), transparent 38%),
    var(--pilot-panel, #10172a);
  color: var(--pilot-text, #f4f7ff);
  box-shadow: 0 20px 55px rgba(4, 9, 20, .12);
}

.smart-layout-header,
.smart-layout-header-actions,
.smart-layout-toolbar,
.smart-widget-library,
.smart-hidden-widgets,
.smart-widget-controls {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.smart-layout-header {
  justify-content: space-between;
  margin-bottom: 18px;
}

.smart-layout-header h2 {
  margin: 4px 0;
  font-size: clamp(1.45rem, 3vw, 2.15rem);
  letter-spacing: -.04em;
}

.smart-layout-header p,
.smart-widget p {
  margin: 0;
  color: var(--pilot-muted, #9ca9c2);
}

.smart-layout-kicker {
  color: var(--smart-accent);
  font-size: .7rem;
  font-weight: 900;
  letter-spacing: .15em;
}

.smart-layout button,
.smart-layout-import {
  min-height: 40px;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .28));
  border-radius: 12px;
  padding: 9px 13px;
  background: var(--pilot-panel-soft, rgba(255, 255, 255, .05));
  color: inherit;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
}

.smart-layout button:hover,
.smart-layout button.active,
.smart-layout-import:hover {
  border-color: var(--smart-accent);
  color: var(--smart-accent);
}

.smart-layout button.primary {
  background: var(--smart-accent);
  color: #031918;
  border-color: var(--smart-accent);
}

.smart-layout-header-actions {
  justify-content: flex-end;
}

.smart-layout-header-actions small {
  flex-basis: 100%;
  text-align: right;
  color: var(--pilot-muted, #9ca9c2);
}

.smart-layout-toolbar,
.smart-widget-library,
.smart-hidden-widgets {
  margin: 0 0 16px;
  padding: 12px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--smart-accent) 7%, transparent);
  border: 1px dashed color-mix(in srgb, var(--smart-accent) 45%, transparent);
}

.smart-layout-import input {
  display: none;
}

.smart-layout-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 14px;
}

.smart-widget {
  grid-column: span 4;
  position: relative;
  min-height: 190px;
  padding: 20px;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .22));
  border-radius: 20px;
  background: var(--pilot-card, rgba(7, 13, 26, .68));
  overflow: hidden;
}

.smart-layout.is-designing .smart-widget {
  outline: 1px dashed color-mix(in srgb, var(--smart-accent) 48%, transparent);
  cursor: grab;
}

.smart-widget.size-p { grid-column: span 3; }
.smart-widget.size-m { grid-column: span 4; }
.smart-widget.size-g { grid-column: span 8; }
.smart-widget.is-pinned { border-color: color-mix(in srgb, var(--smart-accent) 68%, transparent); }

.smart-widget-icon {
  display: grid;
  width: 42px;
  height: 42px;
  margin-bottom: 20px;
  place-items: center;
  border-radius: 13px;
  background: color-mix(in srgb, var(--smart-accent) 16%, transparent);
  color: var(--smart-accent);
  font-size: .74rem;
  font-weight: 900;
}

.smart-widget h3 {
  margin: 0 0 6px;
  font-size: 1.18rem;
}

.smart-widget > input {
  display: block;
  width: 100%;
  margin: 7px 0;
  padding: 10px;
  border: 1px solid var(--pilot-border, rgba(130, 150, 190, .28));
  border-radius: 10px;
  background: var(--pilot-input, rgba(255, 255, 255, .04));
  color: inherit;
}

.smart-widget-open {
  position: absolute;
  right: 16px;
  bottom: 16px;
}

.smart-widget-controls {
  margin: -8px -8px 14px;
}

.smart-widget-controls button {
  min-height: 32px;
  padding: 5px 8px;
  font-size: .72rem;
}

.smart-layout.is-compact .smart-layout-grid { gap: 8px; }
.smart-layout.is-compact .smart-widget { min-height: 154px; padding: 14px; }

@media (max-width: 1100px) {
  .smart-widget.size-p,
  .smart-widget.size-m { grid-column: span 6; }
  .smart-widget.size-g { grid-column: span 12; }
}

@media (max-width: 760px) {
  .smart-layout {
    margin-inline: 0;
    padding: 16px;
    border-radius: 22px;
  }
  .smart-layout-header {
    align-items: flex-start;
  }
  .smart-layout-header-actions,
  .smart-layout-header-actions button {
    width: 100%;
  }
  .smart-layout-header-actions small {
    text-align: left;
  }
  .smart-layout-grid {
    display: flex;
    flex-direction: column;
  }
  .smart-widget,
  .smart-widget.size-p,
  .smart-widget.size-m,
  .smart-widget.size-g {
    width: 100%;
    min-height: 180px;
  }
  .smart-layout-toolbar > *,
  .smart-widget-library > *,
  .smart-hidden-widgets > * {
    flex: 1 1 44%;
    text-align: center;
  }
  .smart-widget-controls {
    position: static;
    overflow-x: auto;
    flex-wrap: nowrap;
  }
  .smart-widget-controls button {
    flex: 0 0 auto;
  }
}

/* Modo Editor global: sobrepõe o sistema sem ocupar espaço no conteúdo. */
.pilot-dashboard[data-visual-editor-root] {
  --ve-accent: var(--pilot-accent, #21c7bf);
  --ve-surface: transparent;
  --ve-text-scale: 1;
  --ve-radius: 18px;
  font-size: calc(1rem * var(--ve-text-scale));
}

.vinkulo-site[data-visual-editor-root] {
  position: relative;
  --ve-accent: var(--pilot-purple, #6558f5);
  --ve-surface: transparent;
  --ve-text-scale: 1;
  --ve-radius: 18px;
  font-size: calc(1rem * var(--ve-text-scale));
}

.global-editor-toolbar-slot {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
}

.social-public-header:has(.global-editor-toolbar-slot) {
  grid-template-columns: auto minmax(220px, 480px) auto auto auto;
}

.vinkulo-site {
  position: relative;
}

.pilot-dashboard[data-visual-editor-root] .pilot-topbar,
.pilot-dashboard[data-visual-editor-root] .pilot-sidebar,
.pilot-dashboard[data-visual-editor-root] .pilot-mobile-nav {
  border-radius: min(var(--ve-radius), 24px);
}

.pilot-dashboard[data-visual-editor-root][data-ve-density="compact"] .pilot-workspace {
  gap: 10px;
}

.pilot-dashboard[data-visual-editor-root][data-ve-density="compact"] article,
.pilot-dashboard[data-visual-editor-root][data-ve-density="compact"] form {
  padding: 14px;
}

.pilot-dashboard[data-visual-editor-root][data-ve-density="expanded"] .pilot-workspace {
  gap: 26px;
}

.pilot-dashboard[data-visual-editor-root][data-ve-density="expanded"] article,
.pilot-dashboard[data-visual-editor-root][data-ve-density="expanded"] form {
  padding: 28px;
}

.global-visual-editor-ui {
  color: #182238;
  font-size: 15px;
  line-height: 1.4;
}

.global-editor-pencil {
  position: relative;
  z-index: 1;
  display: inline-flex;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--ve-accent) 45%, #8993a9);
  border-radius: 13px;
  background: color-mix(in srgb, var(--pilot-surface, #fff) 94%, transparent);
  box-shadow: 0 10px 30px rgba(7, 17, 38, .14);
  color: var(--pilot-text, #172033);
  cursor: pointer;
  backdrop-filter: blur(15px);
}

.global-editor-pencil:hover,
.global-editor-pencil.active {
  border-color: var(--ve-accent);
  background: color-mix(in srgb, var(--ve-accent) 12%, var(--pilot-surface, #fff));
  color: var(--ve-accent);
}

.global-editor-pencil span {
  font-size: 1.25rem;
}

.global-editor-text-layer {
  position: absolute;
  z-index: 18;
  inset: 0;
  pointer-events: none;
}

.global-editor-free-text {
  position: absolute;
  min-width: 90px;
  min-height: 34px;
  padding: 9px 11px;
  border: 1px solid color-mix(in srgb, currentColor 18%, transparent);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(8, 18, 40, .12);
  line-height: 1.35;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  pointer-events: none;
}

[data-visual-editor-active="true"] .global-editor-free-text {
  cursor: move;
  pointer-events: auto;
  touch-action: none;
  user-select: none;
}

[data-visual-editor-active="true"] .global-editor-free-text:hover,
.global-editor-free-text.selected {
  outline: 3px solid var(--ve-accent, #6558f5);
  outline-offset: 3px;
}

.pilot-dashboard[data-visual-editor-active="true"] [data-ve-key] {
  cursor: pointer;
  transition: outline-color .15s ease, box-shadow .15s ease;
}

.vinkulo-site[data-visual-editor-active="true"] [data-ve-key] {
  cursor: pointer;
  transition: outline-color .15s ease, box-shadow .15s ease;
}

.vinkulo-site[data-visual-editor-active="true"] [data-editor-key] {
  outline: 1px dashed color-mix(in srgb, var(--ve-accent) 72%, #6b55ff);
  outline-offset: 3px;
}

.vinkulo-site[data-visual-editor-active="true"] [data-ve-key]:hover {
  outline: 2px solid var(--ve-accent);
  outline-offset: 3px;
}

.vinkulo-site[data-visual-editor-active="true"] [data-ve-selected="true"] {
  position: relative;
  z-index: 2;
  outline: 3px solid #6b55ff;
  outline-offset: 4px;
  box-shadow: 0 0 0 7px rgba(107, 85, 255, .13);
}

.pilot-dashboard[data-visual-editor-active="true"] [data-editor-key],
.pilot-dashboard[data-visual-editor-active="true"] .pilot-workspace article,
.pilot-dashboard[data-visual-editor-active="true"] .pilot-workspace form,
.pilot-dashboard[data-visual-editor-active="true"] .pilot-workspace table {
  outline: 1px dashed color-mix(in srgb, var(--ve-accent) 72%, #6b55ff);
  outline-offset: 3px;
}

.pilot-dashboard[data-visual-editor-active="true"] [data-ve-key]:hover {
  outline: 2px solid var(--ve-accent);
  outline-offset: 3px;
  outline-color: var(--ve-accent);
}

.pilot-dashboard[data-visual-editor-active="true"] [data-ve-selected="true"] {
  position: relative;
  z-index: 2;
  outline: 3px solid #6b55ff;
  outline-offset: 4px;
  box-shadow: 0 0 0 7px rgba(107, 85, 255, .13);
}

.global-editor-panel {
  position: fixed;
  z-index: 500;
  display: grid;
  width: min(390px, calc(100vw - 32px));
  height: min(720px, calc(100dvh - 32px));
