/* ADOTE — identidade, comunidade e liderança */
html,
body {
  min-height: 100%;
  min-height: 100dvh;
}

body {
  overflow-x: clip;
}

.adote-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 13px;
  background: linear-gradient(145deg, #14181d, #080b0f);
  box-shadow: 0 12px 28px rgba(3, 8, 14, .22);
}

.adote-mark img {
  width: 31px;
  height: 31px;
  object-fit: contain;
}

.community-brand-trigger {
  max-width: min(360px, 38vw);
  padding: 0;
  border: 0;
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.community-brand-trigger > span:last-child {
  min-width: 0;
}

.community-brand-trigger strong,
.community-brand-trigger small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.community-brand-mark {
  overflow: hidden;
  background: color-mix(in srgb, var(--pilot-purple) 13%, var(--pilot-surface));
  color: var(--pilot-purple);
  border: 1px solid color-mix(in srgb, var(--pilot-purple) 23%, var(--pilot-line));
  box-shadow: 0 12px 28px color-mix(in srgb, var(--pilot-purple) 16%, transparent);
}

.community-brand-mark img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.community-brand-mark b {
  font-size: 9px;
  font-weight: 950;
  letter-spacing: -.03em;
}

.community-info-backdrop {
  position: fixed;
  inset: 0;
  z-index: 420;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(3, 8, 15, .58);
  backdrop-filter: blur(10px);
}

.community-info-dialog {
  width: min(560px, 100%);
  max-height: calc(100dvh - 32px);
  overflow: auto;
  border: 1px solid var(--pilot-line);
  border-radius: 26px;
  background: var(--pilot-surface);
  color: var(--pilot-text);
  box-shadow: 0 30px 90px rgba(0, 0, 0, .34);
}

.community-info-dialog > header {
  position: relative;
  min-height: 108px;
  background:
    radial-gradient(circle at 85% 15%, color-mix(in srgb, var(--pilot-cyan) 38%, transparent), transparent 31%),
    var(--pilot-gradient);
  background-position: center;
  background-size: cover;
}

.community-info-dialog > header.has-banner::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(4, 8, 15, .08), rgba(4, 8, 15, .46));
}

.community-info-dialog > header > button {
  position: absolute;
  z-index: 2;
  top: 14px;
  right: 14px;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(255, 255, 255, .42);
  border-radius: 13px;
  background: rgba(7, 12, 20, .62);
  color: #fff;
  font-size: 23px;
  cursor: pointer;
  backdrop-filter: blur(12px);
}

.community-info-identity {
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr);
  align-items: center;
  gap: 16px;
  padding: 0 24px;
  transform: translateY(-29px);
  margin-bottom: -13px;
}

.community-info-identity > span {
  width: 74px;
  height: 74px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 5px solid var(--pilot-surface);
  border-radius: 23px;
  background: var(--pilot-gradient);
  color: #fff;
  font-size: 14px;
  font-weight: 950;
  box-shadow: var(--pilot-shadow);
}

.community-info-identity img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.community-info-identity h2 {
  margin: 5px 0 3px;
  color: var(--pilot-text);
  font-size: clamp(22px, 4vw, 32px);
  letter-spacing: -.035em;
}

.community-info-identity small,
.community-info-description,
.community-info-status {
  color: var(--pilot-muted);
}

.community-info-description,
.community-info-status {
  margin: 0;
  padding: 0 24px 20px;
  font-size: 12px;
  line-height: 1.65;
}

.community-info-status.error { color: #d75269; }

.community-info-dialog dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
  padding: 0 24px 24px;
}

.community-info-dialog dl > div {
  padding: 14px;
  border: 1px solid var(--pilot-line);
  border-radius: 15px;
  background: var(--pilot-surface-2);
}

.community-info-dialog dt {
  color: var(--pilot-muted);
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.community-info-dialog dd {
  margin: 6px 0 0;
  font-size: 10px;
  font-weight: 850;
}

.community-info-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 18px 24px 24px;
  border-top: 1px solid var(--pilot-line);
}

.community-info-dialog > footer > * {
  min-height: 43px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 15px;
  border: 1px solid var(--pilot-line);
  border-radius: 12px;
  background: var(--pilot-surface);
  color: var(--pilot-text);
  font: inherit;
  font-size: 10px;
  font-weight: 850;
  text-decoration: none;
  cursor: pointer;
}

.community-info-dialog > footer > button {
  border-color: transparent;
  background: var(--pilot-gradient);
  color: #fff;
}

/* Contrato de contraste do painel. Regras antigas do Editor Visual não podem
   deixar a visão geral híbrida depois da troca de tema. */
.pilot-dashboard .pilot-workspace {
  background: var(--pilot-bg) !important;
  color: var(--pilot-text) !important;
}

.pilot-dashboard .community-home :is(
  .community-home-welcome,
  .community-composer,
  .community-feed-entry,
  .community-home-rail > section
) {
  border-color: var(--pilot-line) !important;
  background: var(--pilot-surface) !important;
  color: var(--pilot-text) !important;
}

.pilot-dashboard .community-home :is(
  .community-home-welcome h1,
  .community-composer strong,
  .community-feed-panel > header h2,
  .community-feed-entry h3,
  .community-feed-entry header strong,
  .community-home-rail header strong
) {
  color: var(--pilot-text) !important;
}

.pilot-dashboard .community-home :is(
  .community-home-welcome > div > p:last-child,
  .community-composer small,
  .community-feed-panel > header > span,
  .community-feed-entry header small,
  .community-feed-entry p,
  .community-feed-entry footer
) {
  color: var(--pilot-muted) !important;
}

.pilot-dashboard .community-home-welcome > a {
  border-color: var(--pilot-line) !important;
  background: var(--pilot-surface) !important;
  color: var(--pilot-purple) !important;
}

@media (max-width: 680px) {
  .community-brand-trigger { max-width: 54px; }
  .community-brand-trigger > span:last-child { display: none; }
  .community-brand-mark { width: 48px; height: 48px; border-radius: 16px; }
  .community-info-backdrop { align-items: end; padding: 0; }
  .community-info-dialog {
    max-height: 90dvh;
    border-radius: 26px 26px 0 0;
  }
  .community-info-dialog dl { grid-template-columns: 1fr; }
  .community-info-dialog > footer {
    display: grid;
    grid-template-columns: 1fr;
  }
}

/* V8.2 — login imersivo, diretórios do proprietário e governança compacta */
.login-shell.login-shell-v2 {
  --login-v2-card: rgba(7, 18, 44, .76);
  --login-v2-card-strong: rgba(5, 13, 33, .9);
  --login-v2-text: #f7f9ff;
  --login-v2-muted: #b8c2db;
  --login-v2-line: rgba(203, 218, 255, .26);
  position: relative;
  isolation: isolate;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  background-color: var(--login-bg, #050817);
  background-image:
    radial-gradient(circle at 22% 18%, color-mix(in srgb, var(--login-accent) 34%, transparent), transparent 34%),
    radial-gradient(circle at 74% 52%, rgba(53, 100, 220, .3), transparent 42%),
    linear-gradient(145deg, #07122d, #020714 72%);
  background-repeat: no-repeat;
  background-size: cover;
  color: var(--login-v2-text);
}
.login-shell.login-shell-v2::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(1, 5, 18, .06), rgba(1, 5, 18, .54)),
    radial-gradient(circle at 50% 40%, transparent 0 30%, rgba(1, 5, 18, .32) 76%);
}
.login-v2-theme {
  position: fixed;
  top: max(18px, env(safe-area-inset-top));
  right: 20px;
  z-index: 20;
  display: flex;
  gap: 5px;
  border: 1px solid var(--login-v2-line);
  border-radius: 15px;
  background: var(--login-v2-card);
  padding: 5px;
  box-shadow: 0 16px 45px rgba(0, 0, 0, .22);
  backdrop-filter: blur(18px);
}
.login-v2-theme button {
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--login-v2-muted);
  cursor: pointer;
}
.login-v2-theme button.active {
  background: color-mix(in srgb, var(--login-accent) 22%, transparent);
  color: var(--login-v2-text);
}
.login-v2-stage {
  width: min(100%, 1060px);
  flex: 1;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 28px;
  margin: 0 auto;
  padding: 76px 24px 34px;
}
.login-card.login-v2-card {
  width: min(100%, 550px);
  border: 1px solid var(--login-v2-line);
  border-radius: 26px;
  background: var(--login-v2-card);
  color: var(--login-v2-text);
  padding: clamp(26px, 4vw, 42px);
  box-shadow: 0 30px 90px rgba(0, 0, 0, .38);
  backdrop-filter: blur(24px) saturate(125%);
}
.login-shell-v2.card-solid .login-v2-card { background: var(--login-v2-card-strong); }
.login-shell-v2.card-minimal .login-v2-card { background: rgba(4, 12, 31, .48); box-shadow: none; }
.login-card.login-v2-card.signup-card { width: min(100%, 880px); }
.login-v2-brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  margin-bottom: 27px;
  text-align: left;
}
.login-v2-brand > span,
.login-v2-brand img {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 16px;
  background: linear-gradient(135deg, var(--login-accent), #6b75ff);
  color: #fff;
  object-fit: contain;
  padding: 5px;
  font-size: 1.25rem;
  font-weight: 900;
  box-shadow: 0 12px 30px color-mix(in srgb, var(--login-accent) 28%, transparent);
}
.login-v2-brand div { display: grid; gap: 3px; }
.login-v2-brand strong { font-size: clamp(1.55rem, 4vw, 2.15rem); letter-spacing: .04em; }
.login-v2-brand small { color: var(--login-v2-muted); font-size: .66rem; letter-spacing: .08em; }
.login-v2-heading { margin-bottom: 24px; text-align: center; }
.login-v2-heading h1 { margin: 0; color: var(--login-v2-text); font-size: clamp(1.75rem, 4vw, 2.35rem); line-height: 1.08; letter-spacing: -.035em; }
.login-v2-heading p { max-width: 510px; margin: 10px auto 0; color: var(--login-v2-muted); line-height: 1.55; }
.login-v2-card .login-form label { color: var(--login-v2-text); font-size: .72rem; }
.login-v2-card .login-form :is(input, textarea) {
  min-height: 52px;
  border-color: var(--login-v2-line);
  background: rgba(4, 12, 30, .48);
  color: var(--login-v2-text);
  font-size: .9rem;
}
.login-v2-card .login-form :is(input, textarea)::placeholder { color: color-mix(in srgb, var(--login-v2-muted) 78%, transparent); }
.login-v2-card .password-field button,
.login-v2-card .login-links :is(button, a),
.login-v2-options button { color: color-mix(in srgb, var(--login-accent) 74%, #fff); }
.login-v2-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}
.login-v2-options > button {
  border: 0;
  background: transparent;
  padding: 4px 0;
  font-size: .75rem;
  cursor: pointer;
}
.login-v2-card .login-v2-remember {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .75rem;
  font-weight: 600;
}
.login-v2-card .login-v2-remember input { width: 17px; min-height: 17px; margin: 0; accent-color: var(--login-accent); }
.login-v2-card .login-submit {
  min-height: 54px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--login-accent) 82%, #2175ff), #2879f5);
  font-size: .95rem;
}
.login-v2-card .login-links { justify-content: center; flex-wrap: wrap; }
.login-v2-card .login-links :is(button, a) { font-size: .74rem; font-weight: 800; text-decoration: none; }
.login-v2-card .login-pilot-notice {
  margin: 20px 0 0;
  border: 1px solid var(--login-v2-line);
  border-radius: 13px;
  color: var(--login-v2-muted);
  padding: 0;
  font-size: .7rem;
}
.login-v2-card .login-pilot-notice summary { padding: 11px 13px; color: var(--login-v2-text); font-weight: 800; cursor: pointer; }
.login-v2-card .login-pilot-notice p { margin: 0; border-top: 1px solid var(--login-v2-line); padding: 11px 13px; line-height: 1.55; }
.login-v2-message {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 11px;
  margin-bottom: 18px;
  border: 1px solid var(--login-v2-line);
  border-radius: 14px;
  background: rgba(255, 255, 255, .06);
  padding: 12px;
}
.login-v2-message > span { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 10px; background: color-mix(in srgb, var(--login-accent) 18%, transparent); color: var(--login-v2-text); }
.login-v2-message div { display: grid; gap: 2px; }
.login-v2-message small { color: var(--login-accent); font-weight: 900; }
.login-v2-message p { margin: 2px 0 0; color: var(--login-v2-muted); font-size: .72rem; line-height: 1.45; }
.login-v2-benefits {
  width: min(100%, 650px);
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}
.login-v2-benefits > span { display: flex; align-items: center; gap: 10px; color: var(--login-v2-text); }
.login-v2-benefits i { width: 38px; height: 38px; display: grid; place-items: center; flex: 0 0 auto; border-radius: 50%; background: color-mix(in srgb, var(--login-accent) 22%, rgba(4,12,30,.7)); color: #fff; font-style: normal; }
.login-v2-benefits div { display: grid; gap: 3px; }
.login-v2-benefits small { color: var(--login-v2-muted); font-size: .64rem; }
.login-v2-footer { padding: 8px 20px max(24px, env(safe-area-inset-bottom)); color: var(--login-v2-muted); text-align: center; font-size: .65rem; }
.login-v2-footer a { color: inherit; }

.login-shell-v2[data-login-theme="claro"] {
  --login-v2-card: rgba(255, 255, 255, .84);
  --login-v2-card-strong: rgba(255, 255, 255, .94);
  --login-v2-text: #12203a;
  --login-v2-muted: #53617a;
  --login-v2-line: rgba(24, 47, 88, .18);
}
.login-shell-v2[data-login-theme="claro"]::before { background: linear-gradient(rgba(232, 240, 255, .38), rgba(224, 235, 255, .58)); }
