/* V8.1 — correções públicas, conta e fluxo de nova comunidade */
.no-community-page {
  background: var(--pilot-bg, #f2f3f5);
  color: var(--pilot-text, #172033);
}

.account-profile-workspace {
  color: var(--pilot-text, #172033);
  overflow: hidden;
}

.account-profile-workspace .workspace-heading h1 {
  color: var(--pilot-text, #172033);
  font-size: clamp(2rem, 4.2vw, 3.7rem);
  line-height: 1.02;
}

.account-profile-workspace .workspace-heading > div > p:last-child {
  max-width: 760px;
  color: var(--pilot-muted, #657082);
  line-height: 1.65;
}

.account-profile-form {
  display: grid;
  grid-template-columns: 1fr;
  gap: 18px;
}

.account-profile-section {
  min-width: 0;
  display: grid;
  gap: 20px;
  margin: 0;
  border: 1px solid var(--pilot-line, #d8dfeb);
  border-radius: 20px;
  background: var(--pilot-surface-2, #f5f7fb);
  padding: clamp(18px, 3vw, 28px);
}

.account-profile-section > header,
.account-profile-section > summary {
  min-width: 0;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
}

.account-profile-section > header > span,
.account-profile-section > summary > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: var(--pilot-gradient, linear-gradient(135deg, #6d45ff, #22cad0));
  color: #fff;
  font-weight: 900;
}

.account-profile-section > header div,
.account-profile-section > summary div { min-width: 0; display: grid; gap: 3px; }
.account-profile-section > header strong,
.account-profile-section > summary strong { color: var(--pilot-text, #172033); font-size: 1rem; }
.account-profile-section > header small,
.account-profile-section > summary small,
.account-profile-form label > small { color: var(--pilot-muted, #657082); line-height: 1.45; }

.account-profile-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.account-profile-grid > *,
.account-profile-section .native-image-upload { min-width: 0; }
.account-biography-field { grid-column: 1 / -1; }
.account-profile-collapsible { padding: 0; }
.account-profile-collapsible > summary {
  list-style: none;
  cursor: pointer;
  padding: clamp(18px, 3vw, 24px);
}
.account-profile-collapsible > summary::-webkit-details-marker { display: none; }
.account-profile-collapsible > summary > b {
  color: var(--pilot-muted, #657082);
  transition: transform .2s ease;
}
.account-profile-collapsible[open] > summary > b { transform: rotate(180deg); }
.account-profile-collapsible > .account-profile-grid {
  border-top: 1px solid var(--pilot-line, #d8dfeb);
  padding: clamp(18px, 3vw, 24px);
}
.account-profile-empty { grid-column: 1 / -1; margin: 0; color: var(--pilot-muted, #657082); }
.account-profile-submit { justify-self: end; min-width: min(100%, 250px); }

.directory-search-v81 {
  max-width: 760px;
  grid-template-columns: minmax(0, 1fr) auto;
