.community-card-details { margin-top: 16px; }
.community-card-details > summary {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  color: var(--pilot-text, #24231f);
  font-size: .72rem;
  font-weight: 850;
  cursor: pointer;
  list-style: none;
}
.community-card-details > summary::-webkit-details-marker { display: none; }
.community-card-details[open] > summary span { transform: rotate(180deg); }

.create-community-backdrop-v81 {
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(3, 8, 16, .74);
}
.create-community-dialog-v81 {
  width: min(780px, 100%);
  max-height: calc(100dvh - 40px);
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 0;
  border: 1px solid var(--pilot-line, #d8dfeb);
  border-radius: 26px;
