}
.create-community-dialog-v81 h2 { color: var(--pilot-text, #172033); }
.create-community-dialog-v81 .create-community-dialog-header-v81 p:last-child { color: var(--pilot-muted, #657082); }
.create-community-dialog-v81 .create-community-dialog-header-v81 > button {
  border-color: var(--pilot-line, #d8dfeb);
  background: var(--pilot-surface-2, #f5f7fb);
  color: var(--pilot-text, #172033);
}
.create-community-progress-v81 {
  margin: 18px 28px 0;
  border: 1px solid var(--pilot-line, #d8dfeb);
