.create-community-progress-v81 button.active { background: var(--pilot-surface, #fff); }
.create-community-progress-v81 button strong { color: var(--pilot-text, #172033); }
.create-community-progress-v81 button small { color: var(--pilot-muted, #657082); }
.create-community-form-v81 { display: block; padding: 20px 28px 0; }
.create-community-form-v81 [hidden] { display: none !important; }
.create-community-section-v81,
.create-community-review-v81 {
  border-color: var(--pilot-line, #d8dfeb);
