}
.create-community-dialog-v81 :is(input, textarea, select) {
  border-color: var(--pilot-line, #d8dfeb);
  background: var(--pilot-surface, #fff);
  color: var(--pilot-text, #172033);
}
.create-community-feedback-v81 { margin-inline: 0; }
.create-community-actions-v81 {
  position: sticky;
  bottom: 0;
  margin: 22px -28px 0;
  border-top: 1px solid var(--pilot-line, #d8dfeb);
  background: color-mix(in srgb, var(--pilot-surface, #fff) 95%, transparent);
  padding: 14px 28px max(14px, env(safe-area-inset-bottom));
  backdrop-filter: blur(18px);
}

html[data-pilot-theme="escuro"] :is(.no-community-page, .account-profile-workspace, .account-profile-section, .create-community-dialog-v81, .create-community-dialog-v81 > .create-community-dialog-header-v81, .landing-empty-communities) {
