/* O tema escuro do acesso é deliberadamente o último contrato de cor. */
.login-shell.login-shell-v2[data-login-theme="escuro"] {
  --login-v2-card: rgba(5, 15, 38, .72);
  --login-v2-card-strong: rgba(4, 12, 31, .9);
  --login-v2-text: #f8fbff;
  --login-v2-muted: #c1cbe0;
  --login-v2-line: rgba(188, 208, 246, .32);
  background-color: #020617;
  background-image:
    radial-gradient(circle at 18% 22%, color-mix(in srgb, var(--login-accent) 34%, transparent), transparent 31%),
    radial-gradient(circle at 78% 58%, rgba(36, 99, 235, .34), transparent 38%),
    linear-gradient(145deg, #071a3d 0%, #020817 68%, #01040c 100%);
}
.login-shell.login-shell-v2[data-login-theme="escuro"]::before {
  background:
    linear-gradient(180deg, rgba(2, 8, 24, .04), rgba(1, 5, 15, .5)),
    radial-gradient(circle at 50% 36%, transparent 0 26%, rgba(1, 4, 13, .24) 76%);
}
.login-shell.login-shell-v2[data-login-theme="escuro"] .login-card.login-v2-card {
  border-color: var(--login-v2-line) !important;
  background: var(--login-v2-card) !important;
  color: var(--login-v2-text) !important;
  box-shadow: 0 34px 100px rgba(0, 0, 0, .52), inset 0 1px 0 rgba(255,255,255,.06);
  backdrop-filter: blur(26px) saturate(135%);
}
.login-shell.login-shell-v2[data-login-theme="escuro"] .login-v2-card .login-form :is(input, textarea) {
  border-color: var(--login-v2-line) !important;
  background: rgba(2, 9, 25, .78) !important;
  color: var(--login-v2-text) !important;
  caret-color: var(--login-accent);
}

/* O modo automático troca o conjunto inteiro, evitando cartão claro sobre fundo escuro. */
@media (prefers-color-scheme: light) {
  .login-shell.login-shell-v2[data-login-theme="auto"] {
    --login-v2-card: rgba(248, 251, 255, .94);
    --login-v2-card-strong: rgba(255, 255, 255, .98);
    --login-v2-text: #14213a;
    --login-v2-muted: #56647c;
    --login-v2-line: rgba(32, 53, 91, .22);
    color-scheme: light;
    background-color: #eaf0fb;
  }
  .login-shell.login-shell-v2[data-login-theme="auto"]::before {
    background: linear-gradient(rgba(235, 242, 255, .62), rgba(219, 231, 251, .72));
  }
  .login-shell.login-shell-v2[data-login-theme="auto"] .login-card.login-v2-card {
    border-color: var(--login-v2-line) !important;
    background: var(--login-v2-card) !important;
    color: var(--login-v2-text) !important;
  }
  .login-shell.login-shell-v2[data-login-theme="auto"] .login-v2-card :is(h1, strong, label, summary) { color: var(--login-v2-text) !important; }
  .login-shell.login-shell-v2[data-login-theme="auto"] .login-v2-card :is(p, small) { color: var(--login-v2-muted) !important; }
}

@media (prefers-color-scheme: dark) {
  .login-shell.login-shell-v2[data-login-theme="auto"] {
    --login-v2-card: rgba(5, 15, 38, .78);
    --login-v2-card-strong: rgba(4, 12, 31, .92);
    --login-v2-text: #f8fbff;
    --login-v2-muted: #c1cbe0;
    --login-v2-line: rgba(188, 208, 246, .32);
    color-scheme: dark;
    background-color: #020617;
  }
  .login-shell.login-shell-v2[data-login-theme="auto"] .login-card.login-v2-card {
    border-color: var(--login-v2-line) !important;
    background: var(--login-v2-card) !important;
    color: var(--login-v2-text) !important;
  }
  .login-shell.login-shell-v2[data-login-theme="auto"] .login-v2-card :is(h1, strong, label, summary) { color: var(--login-v2-text) !important; }
  .login-shell.login-shell-v2[data-login-theme="auto"] .login-v2-card :is(p, small) { color: var(--login-v2-muted) !important; }
  .login-shell.login-shell-v2[data-login-theme="auto"] .login-v2-card .login-form :is(input, textarea) {
    border-color: var(--login-v2-line) !important;
    background: rgba(2, 9, 25, .78) !important;
    color: var(--login-v2-text) !important;
  }
}

.login-shell.login-shell-v2[data-login-theme="escuro"] { color-scheme: dark; }
.login-shell.login-shell-v2[data-login-theme="claro"] { color-scheme: light; }
.login-shell.login-shell-v2 .login-v2-card p.login-feedback {
