/* Visão Geral profissional — proprietário verificado, conta e escalas */
.pilot-strip { display: none !important; }

.verified-owner-name {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: inherit;
  font: inherit;
  font-weight: inherit;
}
.verified-owner-name > span:first-child { min-width: 0; overflow-wrap: anywhere; }
.verified-owner-badge {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--pilot-purple), var(--pilot-cyan));
  color: #fff;
  box-shadow: 0 4px 12px color-mix(in srgb, var(--pilot-purple) 28%, transparent);
}
.verified-owner-badge svg { width: 12px; height: 12px; fill: currentColor; }

.pilot-sidebar nav button > span svg,
.pilot-mobile-menu-grid button > span svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.pilot-user-menu { position: relative; }
.pilot-user-menu > summary { list-style: none; }
.pilot-user-menu > summary::-webkit-details-marker { display: none; }
.pilot-user-trigger { max-width: 230px; padding-right: 9px; }
.pilot-user-trigger > div { min-width: 0; display: grid; gap: 2px; text-align: left; }
.pilot-user-trigger > div .verified-owner-name { overflow: hidden; font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.pilot-user-trigger > div small { color: var(--pilot-muted); font-size: 7px; font-weight: 750; }
.pilot-user-trigger > i { color: var(--pilot-muted); font-style: normal; }
.pilot-user-popover {
  position: absolute;
  top: calc(100% + 9px);
  right: 0;
  z-index: 120;
  width: min(310px, calc(100vw - 28px));
  display: grid;
  gap: 5px;
  border: 1px solid var(--pilot-line);
  border-radius: 18px;
  background: var(--pilot-surface);
  padding: 10px;
  box-shadow: 0 24px 70px var(--pilot-shadow);
}
.pilot-user-popover > header { min-width: 0; display: grid; grid-template-columns: 42px minmax(0,1fr); gap: 10px; align-items: center; margin-bottom: 5px; border-bottom: 1px solid var(--pilot-line); padding: 5px 5px 12px; }
.pilot-user-popover > header > span { width: 42px; height: 42px; display: grid; place-items: center; overflow: hidden; border-radius: 13px; background: var(--pilot-gradient); color: #fff; font-size: 9px; font-weight: 900; }
.pilot-user-popover img { width: 100%; height: 100%; object-fit: cover; }
.pilot-user-popover > header > .pilot-user-popover-identity { min-width: 0; display: grid; gap: 3px; }
.pilot-user-popover > header small { overflow: hidden; color: var(--pilot-muted); font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
.pilot-user-popover > :is(a,button) { min-height: 42px; display: flex; align-items: center; border: 0; border-radius: 11px; background: transparent; color: var(--pilot-text); padding: 0 12px; font: inherit; font-size: 10px; font-weight: 800; text-align: left; text-decoration: none; cursor: pointer; }
.pilot-user-popover > :is(a,button):hover { background: var(--pilot-surface-2); }
.pilot-user-popover > .danger { color: #dc4f68; }

.community-home-command {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  gap: 24px;
  margin-bottom: 18px;
  padding: clamp(24px, 4vw, 42px);
  background:
    radial-gradient(circle at 92% 5%, color-mix(in srgb,var(--pilot-cyan) 20%,transparent), transparent 32%),
    radial-gradient(circle at 64% 92%, color-mix(in srgb,var(--pilot-purple) 16%,transparent), transparent 36%),
    var(--pilot-surface) !important;
}
.community-home-command::after { content:""; position:absolute; inset:0; pointer-events:none; border-radius:inherit; box-shadow:inset 0 1px color-mix(in srgb,#fff 44%,transparent); }
.community-home-intro { min-width: 0; }
.community-home-command .community-home-intro h1 { max-width: 760px; margin: 4px 0 0; font-size: clamp(34px, 5vw, 62px); line-height: .98; }
.community-home-command .community-home-intro > p:last-child { max-width: 620px; margin: 15px 0 0; color: var(--pilot-muted); font-size: 13px; line-height: 1.65; }
.community-home-account { min-width: 255px; align-self: start; display: grid; grid-template-columns: 46px minmax(0,1fr) auto auto; gap: 10px; align-items: center; border: 1px solid var(--pilot-line); border-radius: 16px; background: color-mix(in srgb,var(--pilot-surface-2) 84%,transparent); padding: 9px; }
.community-home-account-avatar { width: 46px; height: 46px; display: grid; place-items: center; overflow: hidden; border-radius: 13px; background: var(--pilot-gradient); color: #fff; font-size: 10px; font-weight: 950; }
.community-home-account-avatar img { width: 100%; height: 100%; object-fit: cover; }
.community-home-account > div { min-width: 0; display: grid; gap: 3px; }
.community-home-account > div .verified-owner-name { font-size: 10px; font-weight: 900; }
.community-home-account > div small { color: var(--pilot-muted); font-size: 8px; }
.community-home-account > :is(button,a) { min-height: 34px; border: 1px solid var(--pilot-line); border-radius: 10px; background: var(--pilot-surface); color: var(--pilot-text); padding: 0 10px; font: inherit; font-size: 8px; font-weight: 850; text-decoration: none; cursor: pointer; }
.community-home-account > a { display: flex; align-items: center; color: #dc4f68; }
.community-home-actions { grid-column: 1/-1; display: flex; gap: 9px; }
.community-home-actions a { min-height: 42px; display: inline-flex; align-items: center; border: 1px solid var(--pilot-line); border-radius: 12px; background: var(--pilot-surface-2); color: var(--pilot-purple); padding: 0 16px; font-size: 9px; font-weight: 850; text-decoration: none; }
.community-home-kpis { grid-column: 1/-1; display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 10px; }
.community-home-kpis article { min-width: 0; display: flex; align-items: center; gap: 11px; border: 1px solid var(--pilot-line); border-radius: 15px; background: color-mix(in srgb,var(--pilot-surface-2) 86%,transparent); padding: 13px; }
.community-home-kpis article > span { width: 34px; height: 34px; flex: none; display: grid; place-items: center; border-radius: 10px; background: color-mix(in srgb,var(--pilot-purple) 12%,var(--pilot-surface)); color: var(--pilot-purple); font-weight: 950; }
.community-home-kpis article.attention > span { background: color-mix(in srgb,#df9b2d 18%,var(--pilot-surface)); color: #bc7914; }
.community-home-kpis article > div { display: grid; gap: 2px; }
.community-home-kpis strong { color: var(--pilot-text); font-size: 18px; }
.community-home-kpis small { color: var(--pilot-muted); font-size: 8px; }

.community-my-schedules { display: grid; gap: 14px; margin-bottom: 18px; border: 1px solid var(--pilot-line); border-radius: 21px; background: var(--pilot-surface); padding: 18px; }
.community-my-schedules > header { display: flex; align-items: end; justify-content: space-between; gap: 14px; }
.community-my-schedules h2 { margin: 2px 0 0; color: var(--pilot-text); font-size: 22px; }
.community-my-schedules > header > span { border-radius: 999px; background: var(--pilot-surface-2); color: var(--pilot-muted); padding: 7px 10px; font-size: 8px; font-weight: 850; }
.community-schedule-feedback { margin: 0; border: 1px solid color-mix(in srgb,#22a06b 34%,var(--pilot-line)); border-radius: 11px; background: color-mix(in srgb,#22a06b 8%,var(--pilot-surface)); color: var(--pilot-text); padding: 10px 12px; font-size: 9px; }
.community-schedule-list { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px; }
.community-schedule-list > article { min-width: 0; display: grid; grid-template-columns: 52px minmax(0,1fr) auto; gap: 12px; align-items: center; border: 1px solid var(--pilot-line); border-radius: 16px; background: var(--pilot-surface-2); padding: 13px; }
.community-schedule-list > article[data-status="confirmada"] { border-color: color-mix(in srgb,#22a06b 36%,var(--pilot-line)); }
.community-schedule-list > article > time { width: 52px; height: 57px; display: grid; place-items: center; align-content: center; border-radius: 13px; background: color-mix(in srgb,var(--pilot-purple) 12%,var(--pilot-surface)); color: var(--pilot-purple); }
.community-schedule-list time strong { font-size: 19px; line-height: 1; }
.community-schedule-list time span { margin-top: 3px; font-size: 7px; font-weight: 900; }
.community-schedule-list > article > div:nth-child(2) { min-width: 0; display: grid; gap: 3px; }
.community-schedule-list > article > div:nth-child(2) small { color: var(--pilot-purple); font-size: 7px; font-weight: 900; text-transform: uppercase; letter-spacing: .08em; }
.community-schedule-list > article > div:nth-child(2) strong { overflow: hidden; color: var(--pilot-text); font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.community-schedule-list > article > div:nth-child(2) span { color: var(--pilot-muted); font-size: 8px; }
.community-schedule-list > article > div:nth-child(2) em { width: fit-content; border-radius: 999px; background: var(--pilot-surface); color: var(--pilot-text); padding: 4px 7px; font-size: 7px; font-style: normal; }
.community-schedule-actions { display: grid; gap: 6px; }
.community-schedule-actions button { min-width: 82px; min-height: 34px; border: 0; border-radius: 10px; background: var(--pilot-gradient); color: #fff; padding: 0 10px; font-size: 8px; font-weight: 900; cursor: pointer; }
.community-schedule-actions button.secondary { border: 1px solid var(--pilot-line); background: var(--pilot-surface); color: var(--pilot-text); }
.community-substitute-picker { grid-column: 1/-1; display: grid; gap: 10px; border-top: 1px solid var(--pilot-line); padding-top: 12px; }
.community-substitute-picker > strong { color: var(--pilot-text); font-size: 11px; }
.community-substitute-picker > p { margin: 0; color: var(--pilot-muted); font-size: 8px; }
.community-substitute-picker > div:not(.community-substitute-actions) { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 7px; }
.community-substitute-picker label { min-width: 0; display: grid; grid-template-columns: auto 32px minmax(0,1fr); align-items: center; gap: 7px; border: 1px solid var(--pilot-line); border-radius: 11px; background: var(--pilot-surface); padding: 7px; cursor: pointer; }
.community-substitute-picker label > :is(img,span:first-of-type) { width: 32px; height: 32px; display: grid; place-items: center; border-radius: 9px; background: var(--pilot-gradient); color: #fff; object-fit: cover; font-size: 8px; font-weight: 900; }
.community-substitute-picker label > span:last-child { min-width: 0; display: grid; gap: 2px; }
.community-substitute-picker label b { overflow: hidden; color: var(--pilot-text); font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.community-substitute-picker label small { color: var(--pilot-muted); font-size: 7px; }
.community-substitute-actions { display: flex; flex-wrap: wrap; gap: 7px; }
.community-substitute-actions button { min-height: 38px; border: 0; border-radius: 10px; background: var(--pilot-gradient); color: #fff; padding: 0 12px; font-size: 8px; font-weight: 900; }
.community-substitute-actions button.secondary { border: 1px solid var(--pilot-line); background: var(--pilot-surface); color: var(--pilot-text); }
.community-schedule-state { max-width: 120px; border-radius: 999px; background: var(--pilot-surface); color: var(--pilot-muted); padding: 7px 9px; font-size: 7px; font-weight: 900; text-align: center; }
.community-schedule-state.confirmada { background: color-mix(in srgb,#22a06b 12%,var(--pilot-surface)); color: #168158; }
.community-schedule-state.indisponivel,.community-schedule-state.ausente { background: color-mix(in srgb,#dc4f68 10%,var(--pilot-surface)); color: #c33c55; }
.community-schedule-empty { min-height: 84px; display: flex; align-items: center; justify-content: center; gap: 12px; border: 1px dashed var(--pilot-line); border-radius: 15px; color: var(--pilot-muted); text-align: left; }
.community-schedule-empty > span { width: 38px; height: 38px; display: grid; place-items: center; border-radius: 12px; background: color-mix(in srgb,#22a06b 12%,var(--pilot-surface)); color: #168158; font-weight: 900; }
.community-schedule-empty strong { color: var(--pilot-text); font-size: 10px; }
.community-schedule-empty p { margin: 3px 0 0; font-size: 8px; }

@media (max-width: 1080px) {
  .community-home-command { grid-template-columns: 1fr; }
  .community-home-account { min-width: 0; }
  .community-schedule-list { grid-template-columns: 1fr; }
}
@media (max-width: 680px) {
  .pilot-user-menu .pilot-user-trigger > div,
  .pilot-user-menu .pilot-user-trigger > i { display: none; }
  .pilot-user-menu .pilot-user-trigger { width: 46px; padding: 5px; }
  .pilot-user-popover { position: fixed; top: 78px; right: 12px; }
  .community-home-command { gap: 18px; padding: 22px 18px; border-radius: 22px; }
  .community-home-command .community-home-intro h1 { font-size: clamp(31px,11vw,44px); }
  .community-home-account { grid-template-columns: 42px minmax(0,1fr); }
  .community-home-account-avatar { width: 42px; height: 42px; }
  .community-home-account > :is(button,a) { min-height: 42px; justify-content: center; }
  .community-home-kpis { grid-template-columns: 1fr; }
  .community-home-kpis article { padding: 11px; }
  .community-my-schedules { padding: 15px; border-radius: 18px; }
  .community-my-schedules > header { align-items: flex-start; }
  .community-my-schedules h2 { font-size: 19px; }
  .community-schedule-list > article { grid-template-columns: 48px minmax(0,1fr); align-items: start; }
  .community-schedule-list > article > time { width: 48px; height: 54px; }
  .community-schedule-actions,.community-schedule-state { grid-column: 1/-1; width: 100%; max-width: none; }
  .community-schedule-actions { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .community-schedule-actions button { min-height: 42px; }
  .community-substitute-picker > div:not(.community-substitute-actions) { grid-template-columns: 1fr; }
  .community-substitute-actions { display: grid; grid-template-columns: 1fr; }
}

/* V8.2 — recepção pública profissional */
.commercial-landing {
  --reception-bg: #f6f7fb;
  --reception-surface: #ffffff;
  --reception-surface-soft: #eef1f7;
  --reception-text: #11182a;
  --reception-muted: #657087;
  --reception-line: #dfe4ee;
  --reception-shadow: 0 26px 70px rgba(17, 26, 51, .10);
  background:
    radial-gradient(circle at 92% 18%, color-mix(in srgb,var(--landing-c,#36cbd0) 10%,transparent), transparent 24%),
    var(--reception-bg);
  color: var(--reception-text);
}

.social-public-header.reception-header,
.social-public-header.reception-header:has(.global-editor-toolbar-slot) {
  position: sticky;
  top: 0;
  z-index: 90;
  width: 100%;
  min-height: 72px;
  display: grid;
  grid-template-columns: minmax(185px,auto) minmax(260px,1fr) auto;
  align-items: center;
  gap: 24px;
  border-bottom: 1px solid color-mix(in srgb,var(--reception-line,#dfe4ee) 82%,transparent);
  background: color-mix(in srgb,var(--reception-surface,#fff) 91%,transparent);
  color: var(--reception-text,#11182a);
  padding: 10px max(24px,calc((100vw - 1320px)/2));
  box-shadow: 0 10px 34px rgba(15, 24, 48, .04);
  backdrop-filter: blur(22px) saturate(145%);
}
.reception-header .vinkulo-brand { min-width: 0; gap: 11px; }
.reception-header .adote-mark {
  width: 43px;
  height: 43px;
  flex: 0 0 auto;
  border-radius: 14px;
  background: #091224;
  box-shadow: 0 13px 32px rgba(7, 16, 34, .14);
}
.reception-header .vinkulo-brand strong { color: var(--reception-text); font-size: 17px; letter-spacing: -.035em; }
.reception-header .vinkulo-brand small { color: var(--reception-muted); font-size: 7px; letter-spacing: .15em; }
.reception-header .reception-primary-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  justify-self: center;
}
.reception-header .reception-primary-nav a {
  min-height: 39px;
  display: inline-flex;
  align-items: center;
  border-radius: 11px;
  color: var(--reception-muted);
  padding: 0 12px;
  font-size: .72rem;
  font-weight: 800;
  text-decoration: none;
  transition: background .2s ease,color .2s ease;
}
.reception-header .reception-primary-nav a:hover { background: var(--reception-surface-soft); color: var(--reception-text); }
.reception-header-actions { justify-self: end; gap: 7px; }
.reception-icon-button,
.reception-header .reception-login {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--reception-line);
  border-radius: 12px;
  background: var(--reception-surface);
  color: var(--reception-text);
  padding: 0 11px;
  font-size: .68rem;
  font-weight: 850;
  text-decoration: none;
  cursor: pointer;
}
.reception-header details > summary { list-style: none; }
.reception-header details > summary::-webkit-details-marker { display: none; }
.public-search-menu,.public-account-menu { position: relative; }
.public-search-menu .public-global-search {
  position: absolute;
  z-index: 12;
  top: calc(100% + 12px);
  right: 0;
  width: min(440px,calc(100vw - 30px));
  min-height: 54px;
  display: grid;
  grid-template-columns: 20px minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--reception-line);
  border-radius: 15px;
  background: var(--reception-surface);
  color: var(--reception-text);
  padding: 6px 7px 6px 15px;
  box-shadow: 0 24px 60px rgba(13, 23, 47, .18);
}
.public-search-menu:not([open]) .public-global-search { display: none; }
.public-search-menu .public-global-search input { color: var(--reception-text); font-size: .76rem; }
.public-search-menu .public-global-search button {
  min-height: 40px;
  border: 0;
  border-radius: 10px;
  background: var(--reception-text);
  color: var(--reception-surface);
  padding: 0 14px;
  font: inherit;
  font-size: .68rem;
  font-weight: 850;
  cursor: pointer;
}
.reception-header .theme-control.compact {
  min-height: 42px;
  gap: 2px;
  border: 1px solid var(--reception-line);
  border-radius: 12px;
  background: var(--reception-surface);
  padding: 3px;
}
.reception-header .theme-control.compact button { width: 32px; height: 32px; border-radius: 9px; }
.reception-header .global-editor-pencil { width: 42px; height: 42px; border-color: var(--reception-line); border-radius: 12px; box-shadow: none; }
.public-account-menu > summary {
  min-height: 44px;
  display: grid;
  grid-template-columns: 34px minmax(0,auto) 10px;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--reception-line);
  border-radius: 13px;
  background: var(--reception-surface);
  color: var(--reception-text);
  padding: 4px 9px 4px 4px;
  cursor: pointer;
}
.public-account-avatar {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 10px;
  background: linear-gradient(135deg,var(--landing-b,#7551f4),var(--landing-c,#36cbd0));
  color: #fff;
  font-size: .62rem;
  font-weight: 950;
}
.public-account-avatar img { width: 100%; height: 100%; object-fit: cover; }
.public-account-copy { min-width: 0; display: grid; gap: 1px; text-align: left; }
.public-account-copy strong { max-width: 105px; overflow: hidden; font-size: .67rem; text-overflow: ellipsis; white-space: nowrap; }
.public-account-copy small { color: var(--reception-muted); font-size: .53rem; }
.public-account-chevron { color: var(--reception-muted); font-size: .7rem; }
.public-account-popover {
  position: absolute;
  z-index: 14;
  top: calc(100% + 12px);
  right: 0;
  width: min(290px,calc(100vw - 30px));
  overflow: hidden;
  border: 1px solid var(--reception-line);
  border-radius: 17px;
  background: var(--reception-surface);
  color: var(--reception-text);
  padding: 7px;
  box-shadow: 0 25px 65px rgba(12, 22, 46, .2);
}
.public-account-menu:not([open]) .public-account-popover { display: none; }
.public-account-popover > header { display: grid; grid-template-columns: 40px minmax(0,1fr); align-items: center; gap: 10px; border-bottom: 1px solid var(--reception-line); padding: 9px 9px 13px; }
.public-account-popover > header .public-account-avatar { width: 40px; height: 40px; }
.public-account-popover > header div { min-width: 0; display: grid; gap: 3px; }
.public-account-popover > header strong,.public-account-popover > header small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.public-account-popover > header strong { font-size: .72rem; }
.public-account-popover > header small { color: var(--reception-muted); font-size: .58rem; }
.public-account-popover > a { min-height: 41px; display: flex; align-items: center; gap: 10px; border-radius: 10px; color: var(--reception-text); padding: 0 10px; font-size: .68rem; font-weight: 780; text-decoration: none; }
.public-account-popover > a:hover { background: var(--reception-surface-soft); }
.public-account-popover > a.public-account-logout { margin-top: 5px; border-top: 1px solid var(--reception-line); border-radius: 0 0 10px 10px; color: #c43e58; }

.commercial-landing .landing-hero {
  position: relative;
  isolation: isolate;
  width: min(1320px,calc(100% - 40px));
  min-height: 620px;
  display: grid;
  grid-template-columns: minmax(0,.88fr) minmax(520px,1.12fr);
  align-items: center;
  gap: clamp(40px,6vw,88px);
  margin: 28px auto 0;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 34px;
  background:
    radial-gradient(circle at 88% 10%,color-mix(in srgb,var(--landing-c,#36cbd0) 23%,transparent),transparent 32%),
    radial-gradient(circle at 25% 110%,color-mix(in srgb,var(--landing-b,#7551f4) 24%,transparent),transparent 34%),
    linear-gradient(135deg,#081630 0%,color-mix(in srgb,#081630 77%,var(--landing-a,#0b1740)) 48%,#17124d 100%);
  color: #fff;
  padding: clamp(54px,6.2vw,86px);
  box-shadow: 0 34px 90px rgba(10, 20, 48, .2);
}
.commercial-landing .landing-hero.has-platform-banner {
  background-size: 100% 100%,cover;
  background-position: center,center;
  background-repeat: no-repeat;
  image-rendering: auto;
}
.commercial-landing .landing-hero.has-platform-banner::before { opacity: .08; }
.commercial-landing .landing-hero::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  opacity: .24;
  background-image: linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);
  background-size: 56px 56px;
  mask-image: linear-gradient(90deg,#000,transparent 70%);
}
.landing-status-badge {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 20px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 999px;
  background: rgba(255,255,255,.07);
  color: #cfd8ec;
  padding: 8px 12px;
  font-size: .67rem;
  font-weight: 800;
  backdrop-filter: blur(12px);
}
.landing-status-badge > span { width: 7px; height: 7px; border-radius: 50%; background: #44d6b4; box-shadow: 0 0 0 5px rgba(68,214,180,.11); }
.commercial-landing .landing-hero h1 { max-width: 650px; font-size: clamp(2.85rem,4.55vw,4.95rem); line-height: 1.02; letter-spacing: -.055em; }
.commercial-landing .landing-hero h1 span { display: block; background: linear-gradient(102deg,#aa95ff 4%,#69d8d7 84%); background-clip: text; color: transparent; }
.commercial-landing .landing-hero-copy > p:not(.landing-status-badge) { max-width: 590px; margin-top: 24px; color: #bdc8dd; font-size: clamp(.98rem,1.2vw,1.12rem); line-height: 1.68; }
.landing-actions { margin-top: 30px; }
.landing-actions a { min-height: 50px; gap: 9px; border-radius: 13px; padding-inline: 19px; font-size: .78rem; }
.commercial-landing .landing-primary-action { background: linear-gradient(135deg,var(--landing-b,#7551f4),var(--landing-c,#36cbd0)); box-shadow: 0 18px 42px color-mix(in srgb,var(--landing-b,#7551f4) 28%,transparent); }
.landing-secondary-action { border-color: rgba(255,255,255,.2); background: rgba(255,255,255,.055); }
.landing-trust-row { display: flex; flex-wrap: wrap; gap: 18px 23px; margin-top: 32px; }
.landing-trust-row > div { min-width: 0; display: flex; align-items: center; gap: 9px; border: 0; padding: 0; }
.landing-trust-row > div > span { width: 31px; height: 31px; flex: none; display: grid; place-items: center; border: 1px solid rgba(255,255,255,.12); border-radius: 10px; background: rgba(255,255,255,.06); color: #7fe1d6; }
.landing-trust-row p { display: grid; gap: 2px; margin: 0; }
.landing-trust-row strong { color: #fff; font-size: .64rem; }
.landing-trust-row small { color: #8494b4; font-size: .54rem; }

.landing-product-preview { transform: translateY(4px); }
.landing-preview-label { position: absolute; z-index: 4; top: -13px; left: 24px; display: flex; align-items: center; gap: 7px; border: 1px solid rgba(255,255,255,.14); border-radius: 999px; background: rgba(5,13,33,.9); color: #bfcbe2; padding: 7px 10px; font-size: .49rem; font-weight: 900; letter-spacing: .13em; }
.landing-preview-label span { width: 6px; height: 6px; border-radius: 50%; background: #34c99f; }
.landing-preview-window { border-color: rgba(255,255,255,.23); border-radius: 18px; box-shadow: 0 40px 100px rgba(0,0,0,.35); transform: rotateY(-3deg) rotateX(1deg); }
.landing-preview-window > header { height: 45px; gap: 9px; padding-inline: 15px; }
.landing-preview-window > header > span { width: 26px; height: 26px; border-radius: 8px; }
.landing-preview-window > header strong { font-size: .65rem; }
.landing-preview-window > header small { color: #8994a7; font-size: .5rem; }
.landing-preview-window > section { min-height: 330px; grid-template-columns: 112px 1fr; }
.landing-preview-window aside { gap: 4px; background: linear-gradient(180deg,#0b4437,#086346); padding: 16px 9px; }
.landing-preview-window aside span { display: flex; align-items: center; gap: 7px; padding: 9px; }
.landing-preview-window aside span i { width: 6px; height: 6px; border: 1px solid currentColor; border-radius: 2px; }
.landing-preview-window aside span.active { background: linear-gradient(90deg,#16a56a,#20b978); box-shadow: 0 8px 18px rgba(0,0,0,.12); }
.landing-preview-window section > div { padding: 23px; }
.landing-preview-heading { display: flex; align-items: start; justify-content: space-between; gap: 12px; }
.landing-preview-heading h2 { font-size: 1.18rem; }
.landing-preview-heading p { margin-bottom: 16px; }
.landing-preview-heading b { border-radius: 999px; background: #e8f7f1; color: #16845e; padding: 6px 8px; font-size: .46rem; }
.landing-preview-stats { gap: 8px; }
.landing-preview-stats article { border-radius: 10px; padding: 11px; }
.landing-preview-stats strong { font-size: 1.18rem; }
.landing-preview-chart { height: 135px; display: grid; grid-template-rows: auto 1fr; align-items: stretch; gap: 11px; margin-top: 14px; padding: 13px; }
.landing-preview-chart header { display: flex; justify-content: space-between; gap: 10px; }
.landing-preview-chart header strong { font-size: .56rem; }
.landing-preview-chart header small { color: #8994a7; font-size: .46rem; }
.landing-preview-chart > div { display: flex; align-items: end; gap: 7px; }
.landing-preview-chart > div span { flex: 1; border-radius: 5px 5px 2px 2px; }
