.request-create-collapsible { margin:0; }
.request-create-collapsible>summary { min-height:50px; padding:14px 16px; }
.request-category-tabs { display:flex; gap:7px; max-width:100%; overflow-x:auto; padding:3px; scrollbar-width:thin; }
.request-category-tabs>button {
