.request-category-tabs>button.active { border-color:var(--pilot-purple); background:var(--pilot-purple); color:#fff; }
.request-category-tabs>button>span { min-width:20px; height:20px; display:grid; place-items:center; padding:0 5px; border-radius:99px; background:color-mix(in srgb,currentColor 12%,transparent); font-size:.68rem; }
.request-compact-list { display:grid; gap:8px; }
.request-compact-list>details { border:1px solid var(--pilot-line); border-radius:14px; background:var(--pilot-surface); overflow:hidden; }
