.request-compact-list>details>summary strong { overflow:hidden; color:var(--pilot-text); font-size:.95rem; text-overflow:ellipsis; white-space:nowrap; }
.request-type-mark { width:10px; height:38px; border-radius:99px; background:#7357e8; }
