.community-post-actions-dialog>header button { width:31px; height:31px; border:0; border-radius:9px; background:var(--pilot-surface-2); color:var(--pilot-muted); font-size:20px; cursor:pointer; }
.community-post-actions-dialog>div { display:grid; gap:5px; }
.community-post-actions-dialog>div>button { min-height:43px; border:0; border-radius:11px; background:var(--pilot-surface-2); color:var(--pilot-text); padding:0 13px; font-size:11px; font-weight:850; text-align:left; cursor:pointer; }
.community-post-actions-dialog>div>button:hover { background:color-mix(in srgb,var(--pilot-purple) 10%,var(--pilot-surface-2)); }
