.event-registrants-preview { max-height:294px; overflow-y:auto; overscroll-behavior:contain; scrollbar-width:thin; }
.event-registrants-more { display:block; margin-top:7px; color:var(--pilot-muted); font-size:8px; }
.event-registrant-search-overlay { position:fixed; z-index:270; inset:0; display:grid; place-items:center; padding:16px; background:rgb(4 5 14 / .72); backdrop-filter:blur(7px); }
.event-registrant-search-dialog { width:min(480px,100%); max-height:min(680px,calc(100dvh - 32px)); display:grid; grid-template-rows:auto auto minmax(0,1fr); gap:11px; padding:15px; border:1px solid var(--pilot-line); border-radius:20px; background:var(--pilot-surface); box-shadow:0 28px 80px rgb(0 0 0 / .48); }
.event-registrant-search-dialog>header { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding-bottom:11px; border-bottom:1px solid var(--pilot-line); }
.event-registrant-search-dialog>header>div { display:grid; gap:3px; }
.event-registrant-search-dialog>header small { color:var(--pilot-purple); font-size:8px; font-weight:950; letter-spacing:.12em; }
.event-registrant-search-dialog>header strong { color:var(--pilot-text); font-size:16px; }
.event-registrant-search-dialog>header button { width:32px; height:32px; border:0; border-radius:9px; background:var(--pilot-surface-2); color:var(--pilot-muted); font-size:20px; cursor:pointer; }
.event-registrant-search-dialog input { width:100%; min-height:43px; border:1px solid var(--pilot-line); border-radius:11px; background:var(--pilot-surface-2); color:var(--pilot-text); padding:0 12px; outline:0; }
.event-registrant-search-results { min-height:0; display:grid; align-content:start; gap:6px; overflow-y:auto; }
.event-registrant-search-results article { display:grid; grid-template-columns:36px minmax(0,1fr); align-items:center; gap:9px; padding:9px; border-radius:11px; background:var(--pilot-surface-2); }
.event-registrant-search-results article>span { width:36px; height:36px; display:grid; place-items:center; border-radius:10px; background:color-mix(in srgb,var(--pilot-purple) 14%,var(--pilot-surface)); color:var(--pilot-purple); font-size:10px; font-weight:900; }
.event-registrant-search-results article>div { min-width:0; display:grid; gap:2px; }
.event-registrant-search-results strong,.event-registrant-search-results small { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.event-registrant-search-results strong { color:var(--pilot-text); font-size:11px; }
.event-registrant-search-results small,.event-registrant-search-results>p { color:var(--pilot-muted); font-size:8px; }

.shared-publication-page { min-height:100vh; display:grid; align-content:start; gap:28px; background:var(--pilot-bg); color:var(--pilot-text); padding-bottom:50px; }
.shared-publication-card { width:min(760px,calc(100% - 32px)); margin:12px auto 0; overflow:hidden; border:1px solid var(--pilot-line); border-radius:24px; background:var(--pilot-surface); box-shadow:0 28px 80px color-mix(in srgb,var(--pilot-shadow) 44%,transparent); }
.shared-publication-card>header { display:flex; align-items:center; justify-content:space-between; gap:14px; padding:18px 20px 12px; }
.shared-publication-card>header>div { min-width:0; display:grid; gap:3px; }
.shared-publication-card>header span { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:10px; font-weight:850; }
.shared-publication-card>header>small { flex:none; border-radius:999px; background:var(--pilot-surface-2); color:var(--pilot-purple); padding:6px 9px; font-size:8px; font-weight:900; }
.shared-publication-copy { display:grid; gap:9px; padding:8px 20px 18px; }
.shared-publication-copy h1 { margin:0; font-size:clamp(25px,4vw,40px); letter-spacing:-.035em; }
.shared-publication-copy p { margin:0; white-space:pre-wrap; color:var(--pilot-muted); line-height:1.65; }
.shared-publication-copy nav { display:flex; flex-wrap:wrap; gap:8px; padding-top:4px; }
.shared-publication-copy nav a { color:var(--pilot-purple); font-size:10px; font-weight:850; text-decoration:none; }
.shared-publication-card>img { width:100%; max-height:620px; display:block; object-fit:contain; background:#080a11; }
.shared-publication-card>footer { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:14px 20px; border-top:1px solid var(--pilot-line); color:var(--pilot-muted); font-size:9px; }
.shared-publication-card>footer a { min-height:36px; display:inline-flex; align-items:center; border-radius:10px; background:var(--pilot-gradient); color:#fff; padding:0 12px; font-weight:850; text-decoration:none; }

@media (max-width:680px) {
  .visitor-category-filter-cards { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .community-post-actions-overlay { place-items:end center; padding:8px 8px calc(88px + env(safe-area-inset-bottom)); }
  .community-post-actions-dialog { width:100%; border-radius:20px 20px 14px 14px; }
  .event-registrant-search-overlay { align-items:end; padding:8px 8px calc(86px + env(safe-area-inset-bottom)); }
  .event-registrant-search-dialog { width:100%; max-height:72dvh; border-radius:20px 20px 14px 14px; }
  .shared-publication-page { gap:14px; }
  .shared-publication-card { width:calc(100% - 16px); margin-top:0; border-radius:18px; }
  .shared-publication-card>header,.shared-publication-copy,.shared-publication-card>footer { padding-inline:14px; }
  .shared-publication-card>footer { align-items:flex-start; flex-direction:column; }
}

/* V146 final — evita que regras legadas deformem os novos cartões. */
.community-composer-trigger { box-shadow:0 10px 26px color-mix(in srgb,var(--pilot-shadow) 28%,transparent); }
.feed-responsive-image { aspect-ratio:16 / 7.4; max-height:360px; }
.feed-responsive-image img { object-fit:cover; }
@media (max-width:680px) {
  .feed-responsive-image { aspect-ratio:4 / 3; max-height:280px; }
}

/* --------------------------------------------------------------------------
   VÍNKULO V2 — linguagem editorial, compacta e responsiva
   A camada abaixo implementa os frames aprovados no Figma sem alterar regras,
   dados ou permissões. O atributo data-ui-version mantém a migração isolada.
   -------------------------------------------------------------------------- */

:root {
  --v2-canvas:#f7f8fa;
  --v2-surface:#ffffff;
  --v2-surface-subtle:#f2f4f7;
  --v2-ink:#0b1117;
  --v2-muted:#5d6975;
  --v2-line:#dde2e8;
  --v2-line-strong:#c9d0d8;
  --v2-blue:#2554b8;
  --v2-blue-hover:#1d469d;
  --v2-blue-soft:#edf4ff;
  --v2-teal:#168778;
  --v2-teal-soft:#e7f7f4;
  --v2-danger:#c63e56;
  --v2-warning:#a66a13;
  --v2-radius:14px;
  --v2-radius-sm:10px;
  --v2-shadow:0 12px 36px rgba(19,31,46,.08);
  --v2-shadow-dialog:0 24px 80px rgba(12,21,33,.2);
}

html[data-pilot-theme="escuro"] {
  --v2-canvas:#0c1118;
  --v2-surface:#121922;
  --v2-surface-subtle:#18212c;
  --v2-ink:#f4f7fa;
  --v2-muted:#a7b2bd;
  --v2-line:#283441;
  --v2-line-strong:#3a4857;
  --v2-blue:#78a2ff;
  --v2-blue-hover:#91b3ff;
  --v2-blue-soft:#182846;
  --v2-teal:#52c8b5;
  --v2-teal-soft:#15352f;
  --v2-danger:#ff8092;
  --v2-warning:#f2b65f;
  --v2-shadow:0 14px 40px rgba(0,0,0,.24);
  --v2-shadow-dialog:0 28px 90px rgba(0,0,0,.55);
}

:is(.pilot-dashboard,.owner-area,.social-public-community)[data-ui-version="v2"] {
  --pilot-bg:var(--v2-canvas)!important;
  --pilot-surface:var(--v2-surface)!important;
  --pilot-surface-2:var(--v2-surface-subtle)!important;
  --pilot-text:var(--v2-ink)!important;
  --pilot-muted:var(--v2-muted)!important;
  --pilot-line:var(--v2-line)!important;
  --pilot-primary:var(--v2-blue)!important;
  --pilot-purple:var(--v2-blue)!important;
