  --pilot-gradient:linear-gradient(135deg,var(--v2-blue),var(--v2-teal))!important;
  --pilot-shadow:rgba(19,31,46,.12)!important;
  min-width:0;
  background:var(--v2-canvas)!important;
  color:var(--v2-ink)!important;
