}

:is(.pilot-dashboard,.owner-area,.social-public-community)[data-ui-version="v2"] *,
.login-shell[data-ui-version="v2"] * { box-sizing:border-box; }

:is(.pilot-dashboard,.owner-area)[data-ui-version="v2"] :is(button,a,summary,input,select,textarea) {
