    align-items:end!important;
    padding:calc(8px * var(--vinkulo-ui-scale-inverse)) calc(8px * var(--vinkulo-ui-scale-inverse)) calc((84px + env(safe-area-inset-bottom)) * var(--vinkulo-ui-scale-inverse))!important;
