  }

  html[data-vinkulo-scale="ampliado"] .pilot-dashboard[data-ui-version="v2"] .cell-detail-overlay-v2:has(.cell-detail-v4) {
    inset:auto!important;
    top:calc((64px + env(safe-area-inset-top)) * var(--vinkulo-ui-scale-inverse))!important;
    left:0!important;
