/* Cadastro público por link temporário — isolado do painel, mas usa os mesmos
   tokens de tema para manter contraste e leitura em qualquer dispositivo. */
.member-registration-public {
  width:min(100%, 1080px);
  min-height:100dvh;
  display:grid;
  align-content:start;
  gap:16px;
  margin:0 auto;
  padding:clamp(20px, 4vw, 56px) clamp(14px, 3vw, 40px);
  background:var(--pilot-bg, #07111f);
  color:var(--pilot-text, #eef4ff);
}
.member-registration-public :is(input, select, button) { font:inherit; }
.member-registration-public-head,
.member-registration-public-form > section,
.member-registration-review,
.member-registration-state,
.member-registration-success {
  border:1px solid var(--pilot-line, #243449);
  border-radius:20px;
  background:var(--pilot-surface, #101c2b);
  box-shadow:0 18px 54px rgba(0, 0, 0, .16);
}
.member-registration-public-head {
  display:grid;
  grid-template-columns:54px minmax(0, 1fr);
  align-items:center;
  gap:14px;
  padding:18px 20px;
}
.member-registration-public-head > span,
.member-registration-state > span,
.member-registration-success > span {
  display:grid;
  place-items:center;
  width:54px;
  height:54px;
  border-radius:16px;
  background:var(--pilot-gradient, linear-gradient(135deg, #566cf0, #55cec2));
  color:#fff;
  font-size:20px;
  font-weight:950;
}
.member-registration-public :is(.member-registration-public-head, .member-registration-review, .member-registration-state, .member-registration-success) p {
  margin:0;
  color:var(--pilot-primary, #6f94ff);
  font-size:10px;
  font-weight:900;
  letter-spacing:.12em;
}
.member-registration-public-head h1,
.member-registration-state h1,
.member-registration-success h1 { margin:4px 0; font-size:clamp(21px, 3vw, 32px); letter-spacing:-.035em; }
.member-registration-public-head small,
.member-registration-state small,
.member-registration-success small { color:var(--pilot-muted, #9aa9be); line-height:1.55; }
.member-registration-public-form { display:grid; gap:14px; }
.member-registration-public-form > section { overflow:hidden; }
.member-registration-public-form > section > header {
  display:flex;
  align-items:center;
  gap:12px;
  padding:15px 18px;
  border-bottom:1px solid var(--pilot-line, #243449);
}
.member-registration-public-form > section > header b {
  flex:0 0 auto;
  display:grid;
  place-items:center;
  width:31px;
  height:31px;
  border-radius:10px;
  background:color-mix(in srgb, var(--pilot-primary, #6f94ff) 15%, var(--pilot-surface, #101c2b));
  color:var(--pilot-primary, #6f94ff);
  font-size:11px;
}
.member-registration-public-form h2 { margin:0; font-size:16px; }
.member-registration-public-form > section > header p { margin:3px 0 0; color:var(--pilot-muted, #9aa9be); font-size:11px; }
.member-registration-fields { display:grid; grid-template-columns:repeat(2, minmax(0, 1fr)); gap:14px; padding:18px; }
.member-registration-fields > label,
.member-registration-days { min-width:0; display:grid; gap:7px; color:var(--pilot-muted, #9aa9be); font-size:11px; font-weight:800; }
.member-registration-fields > label > small { color:var(--pilot-muted, #9aa9be); font-weight:600; }
.member-registration-fields :is(input, select) {
  width:100%;
  min-height:46px;
  border:1px solid var(--pilot-line, #243449);
  border-radius:11px;
  outline:0;
  background:var(--pilot-surface-2, #152437);
  color:var(--pilot-text, #eef4ff);
  padding:0 12px;
}
.member-registration-fields :is(input, select):focus { border-color:var(--pilot-primary, #6f94ff); box-shadow:0 0 0 3px color-mix(in srgb, var(--pilot-primary, #6f94ff) 18%, transparent); }
.member-registration-photo { grid-row:span 2; grid-template-columns:62px minmax(0, 1fr); align-content:center; min-height:106px; padding:12px; border:1px dashed var(--pilot-line, #243449); border-radius:13px; background:var(--pilot-surface-2, #152437); }
.member-registration-photo > span { grid-row:1 / 3; display:grid; place-items:center; width:58px; height:58px; overflow:hidden; border-radius:14px; background:color-mix(in srgb, var(--pilot-primary, #6f94ff) 15%, var(--pilot-surface, #101c2b)); color:var(--pilot-primary, #6f94ff); font-size:27px; }
.member-registration-photo img { width:100%; height:100%; object-fit:cover; }
.member-registration-photo > strong { align-self:end; color:var(--pilot-text, #eef4ff); }
.member-registration-photo > input { align-self:start; min-height:auto; border:0; padding:0; background:transparent; font-size:10px; }
.member-registration-days { grid-column:1 / -1; grid-template-columns:repeat(7, minmax(0, 1fr)); padding:0; border:0; }
.member-registration-days legend { grid-column:1 / -1; margin-bottom:7px; color:var(--pilot-text, #eef4ff); font-size:12px; }
.member-registration-days label { display:flex; align-items:center; justify-content:center; gap:5px; min-height:37px; border:1px solid var(--pilot-line, #243449); border-radius:9px; background:var(--pilot-surface-2, #152437); color:var(--pilot-text, #eef4ff); font-size:10px; cursor:pointer; }
.member-registration-days input { width:15px; min-height:15px; padding:0; accent-color:var(--pilot-primary, #6f94ff); }
.member-registration-wide,.member-registration-empty { grid-column:1 / -1; }
.member-registration-empty { margin:0; color:var(--pilot-muted, #9aa9be); }
.member-registration-feedback { margin:0; padding:12px 14px; border:1px solid #db7486; border-radius:12px; background:color-mix(in srgb, #db7486 12%, var(--pilot-surface, #101c2b)); color:#ef91a2; font-size:12px; }
.member-registration-primary { min-height:50px; border:0; border-radius:13px; background:var(--pilot-gradient, linear-gradient(135deg, #566cf0, #55cec2)); color:#fff; font-weight:900; cursor:pointer; }
.member-registration-primary:disabled { opacity:.48; cursor:not-allowed; }
.member-registration-review { display:grid; gap:18px; padding:22px; }
.member-registration-review header { display:grid; gap:5px; }
.member-registration-review h2 { margin:0; font-size:23px; }.member-registration-review header span { color:var(--pilot-muted, #9aa9be); font-size:12px; }
.member-registration-review > img { width:86px; height:86px; object-fit:cover; border-radius:16px; }
.member-registration-review dl { display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); margin:0; border:1px solid var(--pilot-line, #243449); border-radius:13px; overflow:hidden; }
.member-registration-review dl > div { min-width:0; padding:13px; border-right:1px solid var(--pilot-line, #243449); border-bottom:1px solid var(--pilot-line, #243449); }
.member-registration-review dt { color:var(--pilot-muted, #9aa9be); font-size:9px; font-weight:850; text-transform:uppercase; letter-spacing:.07em; }.member-registration-review dd { margin:5px 0 0; overflow-wrap:anywhere; font-size:13px; font-weight:800; }
.member-registration-review footer { display:flex; justify-content:flex-end; gap:10px; }.member-registration-review footer button { min-height:43px; border:1px solid var(--pilot-line, #243449); border-radius:10px; background:transparent; color:var(--pilot-text, #eef4ff); padding:0 14px; font-weight:850; cursor:pointer; }.member-registration-review footer button:last-child { border:0; background:var(--pilot-gradient, linear-gradient(135deg, #566cf0, #55cec2)); color:#fff; }
.member-registration-state,.member-registration-success { justify-self:center; width:min(100%, 620px); display:grid; justify-items:center; gap:10px; padding:clamp(28px, 6vw, 58px); text-align:center; }.member-registration-state strong,.member-registration-success strong { font-size:16px; }.member-registration-state time,.member-registration-state em { color:var(--pilot-muted, #9aa9be); font-style:normal; }.member-registration-public > .member-registration-privacy { margin:2px 0 0; color:var(--pilot-muted, #9aa9be); font-size:10px; text-align:center; }
.member-first-access-success { width:min(100%,700px); }
.member-first-access-credentials {
  width:100%;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  margin:12px 0 0;
  border:1px solid var(--pilot-line,#243449);
  border-radius:14px;
  overflow:hidden;
  text-align:left;
}
.member-first-access-credentials > div { min-width:0; padding:14px; background:var(--pilot-surface-2,#152437); }
.member-first-access-credentials > div + div { border-left:1px solid var(--pilot-line,#243449); }
.member-first-access-credentials :is(dt,dd) { margin:0; overflow-wrap:anywhere; }
.member-first-access-credentials dt { color:var(--pilot-muted,#9aa9be); font-size:9px; font-weight:850; text-transform:uppercase; letter-spacing:.07em; }
