.parking-qr-backdrop { position:fixed; inset:0; z-index:2147483200; display:grid; place-items:center; background:rgba(2,8,18,.72); backdrop-filter:blur(8px); padding:18px; }
.parking-qr-dialog { width:min(520px,100%); max-height:min(760px,calc(100dvh - 28px)); overflow:auto; border:1px solid color-mix(in srgb,var(--parking-accent) 55%,var(--pilot-line)); border-radius:18px; background:var(--pilot-surface); color:var(--pilot-text); box-shadow:0 28px 90px rgba(0,0,0,.4); }
.parking-qr-dialog>header { position:sticky; top:0; z-index:2; display:flex; align-items:center; justify-content:space-between; padding:15px 16px; border-bottom:1px solid var(--pilot-line); background:color-mix(in srgb,var(--pilot-surface) 94%,transparent); backdrop-filter:blur(12px); }
