.parking-qr-alternatives>label { min-height:62px; display:grid; place-items:center; border:1px solid var(--pilot-line); border-radius:11px; background:var(--pilot-surface-2); color:var(--pilot-text); padding:8px; font-size:8px; font-weight:850; text-align:center; cursor:pointer; }
