  .parking-mobile-copy { flex:0 0 auto; min-height:34px; padding:0 10px; border:1px solid #b8c3b5; border-radius:9px; background:transparent; color:#36523f; font-size:9px; font-weight:850; }
  .parking-mobile-step-success .parking-reservation-qr { grid-template-columns:1fr; justify-items:center; margin-top:16px; padding:16px; border:1px solid var(--pm-line); border-radius:18px; background:var(--pm-card); color:var(--pm-ink); text-align:center; }
  .parking-mobile-step-success .parking-reservation-qr img { width:min(230px,100%); }
  .parking-mobile-success.status-checkin>span { background:#41d2a0; box-shadow:0 8px 0 #239d75; }
}
@media (max-width:680px) {
  html[data-pilot-theme="escuro"] .pilot-dashboard[data-ui-version="v2"] .pilot-workspace:has(.parking-mobile-app) { background:#08131d!important; }
  html[data-pilot-theme="escuro"] .parking-mobile-app { --pm-ink:#eef6f1; --pm-muted:#9aa9a0; --pm-line:#2a3b46; --pm-card:#101e29; --pm-surface:#08131d; background:var(--pm-surface); color:var(--pm-ink); }
  html[data-pilot-theme="escuro"] .parking-mobile-app::before { opacity:.16; }
  html[data-pilot-theme="escuro"] .parking-mobile-header>button,
  html[data-pilot-theme="escuro"] .parking-mobile-help { border-color:var(--pm-line); background:var(--pm-card); color:var(--pm-ink); }
  html[data-pilot-theme="escuro"] .parking-mobile-main h1 { color:var(--pm-ink); }
  html[data-pilot-theme="escuro"] .parking-mobile-main h1 em { color:#cfe77a; }
  html[data-pilot-theme="escuro"] :is(.parking-mobile-intro,.parking-mobile-step-label,.parking-mobile-success>p:last-child) { color:var(--pm-muted); }
  html[data-pilot-theme="escuro"] :is(.parking-mobile-sector-list>button,.parking-mobile-form fieldset,.parking-mobile-form :is(input,select),.parking-mobile-map,.parking-mobile-summary,.parking-mobile-ticket,.parking-mobile-secondary,.parking-mobile-save-profile) { border-color:var(--pm-line); background:var(--pm-card); color:var(--pm-ink); }
  html[data-pilot-theme="escuro"] .parking-mobile-map { background:#0d1923; }
  html[data-pilot-theme="escuro"] .parking-mobile-spots>button { border-color:#43545c; background:#13232e; color:#aab8b0; }
  html[data-pilot-theme="escuro"] .parking-mobile-spots>button.busy { background:#26343c; color:#66747b; }
  html[data-pilot-theme="escuro"] .parking-mobile-spots>button.selected { border-color:#d5f247; background:#d5f247; color:#1a271f; }
  html[data-pilot-theme="escuro"] .parking-mobile-form :is(input,select) { background:#0b1721; color:#eef6f1; }
  html[data-pilot-theme="escuro"] .parking-mobile-action { background:color-mix(in srgb,#08131d 92%,transparent); }
  html[data-pilot-theme="escuro"] .parking-mobile-copy { border-color:var(--pm-line); color:#d5f247; }
}
@media (max-width:680px) and (prefers-color-scheme:dark) {
  html:not([data-pilot-theme]) .pilot-dashboard[data-ui-version="v2"] .pilot-workspace:has(.parking-mobile-app) { background:#08131d!important; }
  html:not([data-pilot-theme]) .parking-mobile-app { --pm-ink:#eef6f1; --pm-muted:#9aa9a0; --pm-line:#2a3b46; --pm-card:#101e29; --pm-surface:#08131d; background:var(--pm-surface); color:var(--pm-ink); }
}

/* Final visitor registration override: a single, scrollable task on phones. */
@media (max-width:680px) {
  .visitor-registration-backdrop { align-items:stretch!important; padding:0!important; }
  .visitor-registration-dialog { width:100%!important; max-width:none!important; height:100dvh!important; max-height:100dvh!important; border:0!important; border-radius:0!important; }
  .visitor-registration-dialog>header { flex:0 0 auto; padding:calc(18px + env(safe-area-inset-top)) 18px 14px!important; }
  .visitor-registration-dialog .visitor-registration { flex:1 1 auto; min-height:0; overflow-x:hidden!important; overflow-y:auto!important; overscroll-behavior:contain; padding:12px 12px calc(96px + env(safe-area-inset-bottom))!important; }
  .visitor-registration-dialog .visitor-registration-section { display:block!important; scroll-margin-top:12px; }
  .visitor-registration-dialog .visitor-registration-section>summary { position:relative!important; top:auto!important; min-height:64px; }
  .visitor-registration-dialog .visitor-registration-actions { position:static!important; margin:16px 0 0!important; padding:12px 0 0!important; }
}

/* --------------------------------------------------------------------------
   V147 — Comentários do feed, bloco único.
   Substitui as onze camadas anteriores que estavam espalhadas pelo arquivo e
   se sobrescreviam com `!important`. Nenhuma regra fora daqui estiliza estes
   seletores: para ajustar o painel, edite apenas este bloco.
   -------------------------------------------------------------------------- */
.community-comments { overflow: hidden; border-top: 1px solid var(--pilot-line); }

.community-comments-toggle {
  width: 100%;
  min-height: 42px;
  display: flex;
  align-items: center;
  gap: 8px;
  border: 0;
  background: transparent;
  color: var(--pilot-text);
  padding: 0 14px;
  text-align: left;
  font-size: .72rem;
  font-weight: 800;
  cursor: pointer;
}
.community-comments-toggle:hover { background: color-mix(in srgb, var(--pilot-text) 4%, transparent); }
.community-comments-toggle > svg {
  width: 15px;
  height: 15px;
  flex: none;
  fill: none;
  stroke: var(--pilot-muted);
  stroke-width: 1.7;
}
.community-comments-toggle i {
  margin-left: auto;
  color: var(--pilot-muted);
  font-size: .62rem;
  font-style: normal;
  transition: transform .18s ease;
}
.community-comments-toggle[aria-expanded="true"] i { transform: rotate(180deg); }

.community-comments-panel {
  min-width: 0;
  display: grid;
  gap: 4px;
  border-top: 1px solid var(--pilot-line);
  padding: 4px 14px 12px;
}

.community-comments-more {
  justify-self: start;
  min-height: 30px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--pilot-primary);
  padding: 0 6px;
  font-size: .7rem;
  font-weight: 800;
  cursor: pointer;
}
.community-comments-more:hover { background: var(--pilot-surface-2); }

.community-comments-list { min-width: 0; display: grid; }

.community-comment {
  min-width: 0;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--pilot-line) 55%, transparent);
}
.community-comment:last-child { border-bottom: 0; }
.community-comment[data-pending="true"] { opacity: .55; }
.community-comment > :is(img, span) {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 50%;
  background: color-mix(in srgb, var(--pilot-primary) 14%, var(--pilot-surface));
  color: var(--pilot-primary);
  object-fit: cover;
  font-size: .6rem;
  font-weight: 900;
}

.community-comment-body { min-width: 0; display: grid; gap: 3px; }
.community-comment-body > header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 3px 7px;
}
.community-comment-name {
  max-width: min(100%, 220px);
  color: var(--pilot-text);
  font-size: .76rem;
  font-weight: 800;
}
.community-comment-name > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow-wrap: normal;
}
.community-comment-role {
  flex: none;
  border-radius: 999px;
  background: var(--pilot-surface-2);
  color: var(--pilot-muted);
  padding: 1px 7px;
  font-size: .58rem;
  font-weight: 800;
}
.community-comment-role[data-highlight="true"] {
  background: color-mix(in srgb, var(--pilot-primary) 13%, var(--pilot-surface));
  color: var(--pilot-primary);
}
.community-comment-time { flex: none; color: var(--pilot-muted); font-size: .6rem; }
.community-comment-body p {
  margin: 0;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  color: var(--pilot-text);
  font-size: .78rem;
  line-height: 1.55;
}

.community-comments-empty { margin: 6px 0; color: var(--pilot-muted); font-size: .72rem; }
.community-comments-error {
  margin: 0;
  border-radius: 9px;
  background: color-mix(in srgb, #d34a62 10%, transparent);
  color: #d34a62;
  padding: 7px 10px;
  font-size: .7rem;
  font-weight: 700;
}

.community-comments-skeleton { display: grid; gap: 10px; padding: 8px 0; }
.community-comments-skeleton > span {
  height: 32px;
  border-radius: 9px;
  background: linear-gradient(
    90deg,
    var(--pilot-surface-2),
    color-mix(in srgb, var(--pilot-surface-2) 45%, var(--pilot-surface)),
    var(--pilot-surface-2)
  );
  background-size: 200% 100%;
  animation: community-comment-shimmer 1.2s ease-in-out infinite;
}
.community-comments-skeleton > span:last-child { width: 72%; }
@keyframes community-comment-shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .community-comments-skeleton > span { animation: none; }
  .community-comments-toggle i { transition: none; }
}

.community-comment-form {
  min-width: 0;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: end;
  gap: 8px;
  margin-top: 6px;
}
.community-comment-form-avatar {
  width: 32px;
  height: 32px;
  align-self: end;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--pilot-surface-2);
  color: var(--pilot-muted);
  font-size: .58rem;
  font-weight: 900;
}
.community-comment-form > label {
  min-width: 0;
  display: block;
  border: 1px solid var(--pilot-line);
  border-radius: 16px;
  background: var(--pilot-surface-2);
  padding: 4px 12px;
  transition: border-color .18s ease, box-shadow .18s ease;
}
.community-comment-form > label:focus-within {
  border-color: color-mix(in srgb, var(--pilot-primary) 70%, var(--pilot-line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--pilot-primary) 12%, transparent);
}
.community-comment-form textarea {
  width: 100%;
  min-height: 30px;
  max-height: 132px;
  display: block;
  overflow-y: auto;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--pilot-text);
  padding: 5px 0;
  font: inherit;
  font-size: .78rem;
  line-height: 1.45;
  resize: none;
}
.community-comment-form textarea::placeholder { color: var(--pilot-muted); }
.community-comment-form > button {
  width: 34px;
  min-width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: var(--pilot-gradient);
  color: #fff;
  padding: 0;
  cursor: pointer;
  transition: opacity .18s ease, transform .12s ease;
}
.community-comment-form > button:hover:not(:disabled) { transform: translateY(-1px); }
.community-comment-form > button:disabled {
  background: var(--pilot-surface-2);
  color: var(--pilot-muted);
  cursor: default;
}
.community-comment-send-icon { display: block; font-size: 16px; font-weight: 700; line-height: 1; }

.community-comment-counter {
  justify-self: end;
  color: var(--pilot-muted);
  font-size: .6rem;
}

@media (max-width: 680px) {
  .community-comments-panel { padding-inline: 11px; }
  .community-comment-form { gap: 7px; }
}

/* Camada V2: mesma estrutura, paleta e densidade editorial. */
.pilot-dashboard[data-ui-version="v2"] .community-comments { border-top: 0; }
.pilot-dashboard[data-ui-version="v2"] .community-comments-toggle {
  min-height: 40px;
  border-top: 1px solid var(--v2-line);
  padding: 0 12px;
  color: var(--v2-ink);
  font-size: 10px;
}
.pilot-dashboard[data-ui-version="v2"] .community-comments-toggle > svg { stroke: var(--v2-muted); }
.pilot-dashboard[data-ui-version="v2"] .community-comments-panel {
  border-top: 1px solid var(--v2-line);
  background: var(--v2-surface-subtle);
  padding: 8px 12px 12px;
}
.pilot-dashboard[data-ui-version="v2"] .community-comment { border-bottom-color: var(--v2-line); }
.pilot-dashboard[data-ui-version="v2"] .community-comment-name { color: var(--v2-ink); }
.pilot-dashboard[data-ui-version="v2"] .community-comment-body p { color: var(--v2-ink); font-size: 11px; }
.pilot-dashboard[data-ui-version="v2"] .community-comment-role { background: var(--v2-surface); color: var(--v2-muted); }
.pilot-dashboard[data-ui-version="v2"] .community-comment-role[data-highlight="true"] {
  background: color-mix(in srgb, var(--v2-blue) 12%, var(--v2-surface));
  color: var(--v2-blue);
}
.pilot-dashboard[data-ui-version="v2"] .community-comment-time { color: var(--v2-muted); }
.pilot-dashboard[data-ui-version="v2"] .community-comment-form > label {
  border-color: var(--v2-line);
  border-radius: 11px;
  background: var(--v2-surface);
}
.pilot-dashboard[data-ui-version="v2"] .community-comment-form textarea { color: var(--v2-ink); font-size: 10px; }
.pilot-dashboard[data-ui-version="v2"] .community-comment-form > button {
  border-radius: 9px;
  background: var(--v2-blue);
}
.pilot-dashboard[data-ui-version="v2"] .community-comment-form > button:disabled {
  background: var(--v2-surface);
  color: var(--v2-muted);
}
.pilot-dashboard[data-ui-version="v2"] .community-comments-more { color: var(--v2-blue); }
